export default "k lines\\n        payload = {\\n            \\\"nodes\\\": [\\n                _node(node_id=\\\"URLComponent-ws\\\", component_type=\\\"URLComponent\\\", code=node_code_with_trailing),\\n            ],\\n        }\\n\\n        with patch(\\n            \\\"lfx.mcp.flow_builder_tools._state._load_registry_user_aware\\\",\\n            return_value=registry,\\n        ):\\n            violations = _scan_flow_component_code(payload)\\n\\n        assert violations == []\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/agentic/services/test_flow_run_error_classification.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d0c28cbda732a9b73f947e8742f047895c49b92e9460e8c0828c1c90e26e1f18\",\"content\":\"\\\"\\\"\\\"classify_run_error \u2014 decide if a failed verification run is fixable.\\n\\nThe flow-verification loop must NOT burn LLM tokens retrying a flow whose\\nrun failed for a reason the LLM cannot fix (missing user API key, DB,\\nfile, network) or a timeout. It SHOULD retry genuine code/wiring/spec\\nbugs. This classifier is the pure decision at the heart of that loop.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport pytest\\nfrom langflow.agentic.services.flow_run_error_classification import (\\n    RunErrorKind,\\n    classify_run_error,\\n)\\n\\n\\nclass TestExternalResourceErrors:\\n    @pytest.mark.parametrize(\\n        \\\"message\\\",\\n        [\\n            \\\"Incorrect API key provided: sk-abc***\\\",\\n            \\\"AuthenticationError: invalid api key\\\",\\n            \\\"401 Unauthorized\\\",\\n            \\\"403 Forbidden\\\",\\n            \\\"OPENAI_API_KEY is not set. Please configure it.\\\",\\n            \\\"Missing API key for provider Anthropic\\\",\\n            \\\"Connection refused\\\",\\n            \\\"Failed to resolve 'api.openai.com'\\\",\\n            \\\"Max retries exceeded with url: /v1/chat/completions\\\",\\n            \\\"No such file or directory: '/data/handbook.pdf'\\\",\\n            \\\"could not connect to database: connection timed out\\\",\\n            \\\"Rate limit reached for gpt-4o\\\",\\n            \\\"429 Too Many Requests\\\",\\n            # A model the account can't call \u2014 the agent can't fix this by\\n            # rebuilding, so it must NOT trigger the 3x fix-retry loop (which\\n            # hangs the chat on \\\"Crafting your component...\\\").\\n            \\\"Model not available. Please select a different model.\\\",\\n            \\\"The model `gpt-5.4` model_not_found\\\",\\n            \\\"Project does not have access to model gpt-5.4\\\",\\n        ],\\n    )\\n    def test_should_classify_as_external_resource_when_error_needs_user_supplied_resource(self, message):\\n        assert classify_run_error(message) is RunErrorKind.EXTERNAL_RESOURCE\\n\\n\\nclass TestTimeout:\\n    def test_should_classify_as_timeout_when_run_timed_out(self):\\n        assert classify_run_error(\\\"The flow run timed out after 120s.\\\") is RunErrorKind.TIMEOUT\\n\\n\\nclass TestFixableErrors:\\n    @pytest.mark.parametrize(\\n        \\\"message\\\",\\n        [\\n            \\\"Attribute build_output not found in PrimeChecker\\\",\\n            \\\"No model selected\\\",\\n            \\\"Component type 'FooBar' not found in registry\\\",\\n            \\\"AttributeError: 'NoneType' object has no attribute 'text'\\\",\\n            \\\"ValidationError: 1 validation error for ChatOutput\\\",\\n            \\\"TypeError: run() missing 1 required positional argument\\\",\\n            \\\"NameError: name 'Messsage' is not defined\\\",\\n            \\\"Edge target handle 'xyz' does not exist on node Agent-1\\\",\\n        ],\\n    )\\n    def test_should_classify_as_fixable_when_error_is_a_code_or_wiring_bug(self, message):\\n        assert classify_run_error(message) is RunErrorKind.FIXABLE\\n\\n    def test_should_classify_keyerror_as_fixable_not_external_even_when_it_mentions_api_key(self):\\n        # Adversarial: a missing dict key named 'api_key' in the SPEC is a\\n        # code/wiring bug the LLM can fix \u2014 it is NOT a missing credential.\\n        # The Python-exception marker must win over the 'api key' substring.\\n        assert classify_run_error(\\\"KeyError: 'api_key'\\\") is RunErrorKind.FIXABLE\\n\\n\\nclass TestUnknownAndEmpty:\\n    @pytest.mark.parametrize(\\\"message\\\", [\\\"\\\", \\\"   \\\", None])\\n    def test_should_classify_empty_error_as_unknown(self, message):\\n        assert classify_run_error(message) is RunErrorKind.UNKNOWN\\n\\n    def test_should_classify_unmatched_error_as_unknown(self):\\n        assert classify_run_error(\\\"something weird happened deep in the engine\\\") is RunErrorKind.UNKNOWN\\n\\n    def test_should_be_case_insensitive(self):\\n        assert classify_run_error(\\\"INCORRECT API KEY PROVIDED\\\") is RunErrorKind.EXTERNAL_RESOURCE\\n        assert classify_run_error(\\\"attributeerror: boom\\\") is RunErrorKind.FIXABLE\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/agentic/services/test_flow_static_validation.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"9a21b9273ce3c57a3a5e867ca68837eef0f97e2db7b69ab6e26cdb67fede63d6\",\"content\":\"\\\"\\\"\\\"validate_flow_spec \u2014 Tier-1 static validation of a built flow.\\n\\nThin wrapper that reuses Langflow's existing CLI validator\\n(``validate_flow_file`` + the STRUCTURAL\u2192REQUIRED_INPUTS semantic\\nchecks) on an in-memory flow dict, with ZERO LLM tokens. Its own\\nresponsibility is only: serialize \u2192 delegate \u2192 map to a small stable\\nreport. Credentials are skipped (a missing user key is handled by the\\nagent-model resolver / honest caveat, NOT a fixable validation error).\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom pathlib import Path\\nfrom unittest.mock import patch\\n\\nfrom langflow.agentic.services.flow_static_validation import (\\n    FlowValidationReport,\\n    validate_flow_spec,\\n)\\n\\nMODULE = \\\"langflow.agentic.services.flow_static_validation\\\"\\n\\n\\ndef _fake_result(*, errors=(), warnings=()):\\n    from lfx.cli.validation.core import ValidationIssue, ValidationResult\\n\\n    res = ValidationResult(path=Path(\\\"x\\\"))\\n    for msg, node in errors:\\n        res.issues.append(ValidationIssue(level=2, severity=\\\"error\\\", node_id=node, node_name=node, message=msg))\\n    for msg in warnings:\\n        res.issues.append(ValidationIssue(level=1, severity=\\\"warning\\\", node_id=None, node_name=None, message=msg))\\n    return res\\n\\n\\nclass TestValidateFlowSpecContract:\\n    def test_should_report_ok_when_the_validator_finds_no_errors(self):\\n        with patch(f\\\"{MODULE}.validate_flow_file\\\", return_value=_fake_result()):\\n            report = validate_flow_spec({\\\"name\\\": \\\"f\\\", \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}})\\n\\n        assert isinstance(report, FlowValidationReport)\\n        assert report.ok is True\\n        assert report.errors == []\\n\\n    def test_should_surface_errors_with_the_node_name_and_not_be_ok(self):\\n        with patch(\\n            f\\\"{MODULE}.validate_flow_file\\\",\\n            return_value=_fake_result(errors=[(\\\"Unknown component type 'FooBar'\\\", \\\"FooBar-1\\\")]),\\n        ):\\n            report = validate_flow_spec({\\\"name\\\": \\\"f\\\", \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}})\\n\\n        assert report.ok is False\\n        assert len(report.errors) == 1\\n        assert \\\"FooBar\\\" in report.errors[0]\\n\\n    def test_should_separate_warnings_from_errors_and_stay_ok_on_warnings_only(self):\\n        with patch(\\n            f\\\"{MODULE}.validate_flow_file\\\",\\n            return_value=_fake_result(warnings=[\\\"Outdated component version\\\"]),\\n        ):\\n            report = validate_flow_spec({\\\"name\\\": \\\"f\\\", \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}})\\n\\n        assert report.ok is True\\n        assert report.errors == []\\n        assert any(\\\"Outdated\\\" in w for w in report.warnings)\\n\\n    def test_should_skip_credentials_so_a_missing_user_key_is_not_a_blocking_error(self):\\n        captured = {}\\n\\n        def _spy(_path, **kwargs):\\n            captured.update(kwargs)\\n            return _fake_result()\\n\\n        with patch(f\\\"{MODULE}.validate_flow_file\\\", side_effect=_spy):\\n            validate_flow_spec({\\\"name\\\": \\\"f\\\", \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}})\\n\\n        assert captured.get(\\\"skip_credentials\\\") is True\\n\\n    def test_should_not_leave_a_temp_file_behind(self, tmp_path, monkeypatch):\\n        monkeypatch.setenv(\\\"TMPDIR\\\", str(tmp_path))\\n        seen = {}\\n\\n        def _spy(path, **_kwargs):\\n            seen[\\\"path\\\"] = Path(path)\\n            assert seen[\\\"path\\\"].exists()  # file exists DURING validation\\n            return _fake_result()\\n\\n        with patch(f\\\"{MODULE}.validate_flow_file\\\", side_effect=_spy):\\n            validate_flow_spec({\\\"name\\\": \\\"f\\\", \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}})\\n\\n        # ...and is cleaned up afterwards.\\n        assert not seen[\\\"path\\\"].exists()\\n\\n    def test_should_be_resilient_when_the_flow_cannot_be_serialized(self):\\n        # A non-JSON-serializable value must NOT raise \u2014 return not-ok.\\n        report = validate_flow_spec({\\\"data\\\": {\\\"nodes\\\": [{\\\"bad\\\": {1, 2, 3}}]}})\\n        assert report.ok is False\\n        assert report.errors\\n\\n\\nclass TestValidateFlowSpecRealReuse:\\n    def test_should_flag_an_unknown_component_type_via_the_real_validator(self):\\n        # No mock \u2014 proves the real lfx validator is actually wired.\\n        flow = {\\n            \\\"id\\\": \\\"flow-1\\\",  # _REQUIRED_TOP_LEVEL = {\\\"id\\\", \\\"name\\\", \\\"data\\\"}\\n            \\\"name\\\": \\\"f\\\",\\n            \\\"data\\\": {\\n                \\\"nodes\\\": [\\n                    {\\n                        \\\"id\\\": \\\"Bogus-1\\\",\\n                        \\\"data\\\": {\\n                            \\\"type\\\": \\\"TotallyNotARealComponentType\\\",\\n                            \\\"id\\\": \\\"Bogus-1\\\",\\n                            \\\"node\\\": {\\\"template\\\": {}},\\n                        },\\n                    }\\n                ],\\n                \\\"edges\\\": [],\\n            },\\n        }\\n        report = validate_flow_spec(flow)\\n        assert report.ok is False\\n        assert any(\\\"TotallyNotARealComponentType\\\" in e for e in report.errors)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/agentic/services/test_flow_structural_validation.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"4f79b488b4fdb9039b509e58662551c9fd3b4fcbcad9973f6ef4f6466145b1aa\",\"content\":\"\\\"\\\"\\\"Unit tests for structural (no-execution) flow validation.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom langflow.agentic.services.flow_structural_validation import structural_failures\\n\\n\\ndef _node(node_id, ntype, *, template=None, outputs=None):\\n    return {\\n        \\\"id\\\": node_id,\\n        \\\"data\\\": {\\\"id\\\": node_id, \\\"type\\\": ntype, \\\"node\\\": {\\\"template\\\": template or {}, \\\"outputs\\\": outputs or []}},\\n    }\\n\\n\\ndef _input_edge(source, target, field, *, source_output=\\\"message\\\"):\\n    return {\\n        \\\"source\\\": source,\\n        \\\"target\\\": target,\\n        \\\"data\\\": {\\n            \\\"sourceHandle\\\": {\\\"name\\\": source_output, \\\"id\\\": source},\\n            \\\"targetHandle\\\": {\\\"fieldName\\\": field, \\\"id\\\": target},\\n        },\\n    }\\n\\n\\ndef _feedback_edge(source, loop_id, port=\\\"item\\\"):\\n    return {\\n        \\\"source\\\": source,\\n        \\\"target\\\": loop_id,\\n        \\\"data\\\": {\\n            \\\"sourceHandle\\\": {\\\"name\\\": \\\"data_output\\\", \\\"id\\\": source},\\n            \\\"targetHandle\\\": {\\\"name\\\": port, \\\"id\\\": loop_id, \\\"output_types\\\": [\\\"Data\\\"]},\\n        },\\n    }\\n\\n\\n_LOOP_OUTPUTS = [\\n    {\\\"name\\\": \\\"item\\\", \\\"types\\\": [\\\"Data\\\"], \\\"allows_loop\\\": True, \\\"group_outputs\\\": True},\\n    {\\\"name\\\": \\\"done\\\", \\\"types\\\": [\\\"DataFrame\\\"], \\\"allows_loop\\\": False, \\\"group_outputs\\\": True},\\n]\\n\\n\\ndef _complete_loop_flow():\\n    nodes = [\\n        _node(\\\"ChatInput-1\\\", \\\"ChatInput\\\"),\\n        _node(\\\"LoopComponent-1\\\", \\\"LoopComponent\\\", template={\\\"data\\\": {\\\"input_types\\\": [\\\"Data\\\"]}}, outputs=_LOOP_OUTPUTS),\\n        _node(\\\"Parser-1\\\", \\\"ParserComponent\\\", template={\\\"input_data\\\": {\\\"required\\\": True, \\\"input_types\\\": [\\\"Data\\\"]}}),\\n        _node(\\n            \\\"Type-1\\\", \\\"TypeConverterComponent\\\", template={\\\"input_data\\\": {\\\"required\\\": True, \\\"input_types\\\": [\\\"Message\\\"]}}\\n        ),\\n        _node(\\\"ChatOutput-1\\\", \\\"ChatOutput\\\", template={\\\"input_value\\\": {\\\"required\\\": True, \\\"input_types\\\": [\\\"Message\\\"]}}),\\n    ]\\n    edges = [\\n        _input_edge(\\\"ChatInput-1\\\", \\\"LoopComponent-1\\\", \\\"data\\\"),\\n        {\\n            \\\"source\\\": \\\"LoopComponent-1\\\",\\n            \\\"target\\\": \\\"Parser-1\\\",\\n            \\\"data\\\": {\\n                \\\"sourceHandle\\\": {\\\"name\\\": \\\"item\\\", \\\"id\\\": \\\"LoopComponent-1\\\"},\\n                \\\"targetHandle\\\": {\\\"fieldName\\\": \\\"input_data\\\", \\\"id\\\": \\\"Parser-1\\\"},\\n            },\\n        },\\n        _input_edge(\\\"Parser-1\\\", \\\"Type-1\\\", \\\"input_data\\\", source_output=\\\"parsed_text\\\"),\\n        _feedback_edge(\\\"Type-1\\\", \\\"LoopComponent-1\\\"),\\n        {\\n            \\\"source\\\": \\\"LoopComponent-1\\\",\\n            \\\"target\\\": \\\"ChatOutput-1\\\",\\n            \\\"data\\\": {\\n                \\\"sourceHandle\\\": {\\\"name\\\": \\\"done\\\", \\\"id\\\": \\\"LoopComponent-1\\\"},\\n                \\\"targetHandle\\\": {\\\"fieldName\\\": \\\"input_value\\\", \\\"id\\\": \\\"ChatOutput-1\\\"},\\n            },\\n        },\\n    ]\\n    return {\\\"data\\\": {\\\"nodes\\\": nodes, \\\"edges\\\": edges}}\\n\\n\\ndef test_should_pass_when_loop_flow_is_structurally_complete():\\n    assert structural_failures(_complete_loop_flow()) == []\\n\\n\\ndef test_should_return_empty_for_empty_flow():\\n    assert structural_failures({\\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}}) == []\\n\\n\\ndef test_should_flag_loop_without_data_source():\\n    flow = _complete_loop_flow()\\n    flow[\\\"data\\\"][\\\"edges\\\"] = [\\n        e\\n        for e in flow[\\\"data\\\"][\\\"edges\\\"]\\n        if not (e[\\\"target\\\"] == \\\"LoopComponent-1\\\" and e[\\\"data\\\"][\\\"targetHandle\\\"].get(\\\"fieldName\\\") == \\\"data\\\")\\n    ]\\n    # Drop the now-orphaned ChatInput so only the data-source issue remains.\\n    flow[\\\"data\\\"][\\\"nodes\\\"] = [n for n in flow[\\\"data\\\"][\\\"nodes\\\"] if n[\\\"id\\\"] != \\\"ChatInput-1\\\"]\\n    issues = structural_failures(flow)\\n    assert any(\\\"no data source\\\" in i for i in issues)\\n\\n\\ndef test_should_flag_loop_whose_item_is_never_consumed():\\n    flow = {\\n        \\\"data\\\": {\\n            \\\"nodes\\\": [\\n                _node(\\\"LoopComponent-1\\\", \\\"LoopComponent\\\", outputs=_LOOP_OUTPUTS),\\n                _node(\\\"Type-1\\\", \\\"TypeConverterComponent\\\"),\\n            ],\\n            \\\"edges\\\": [_feedback_edge(\\\"Type-1\\\", \\\"LoopComponent-1\\\")],\\n        }\\n    }\\n    issues = structural_failures(flow)\\n    assert any(\\\"never starts\\\" in i for i in issues)\\n    assert any(\\\"no data source\\\" in i for i in issues)\\n\\n\\ndef test_should_flag_open_loop_missing_feedback():\\n    flow = _complete_loop_flow()\\n    flow[\\\"data\\\"][\\\"edges\\\"] = [\\n        e\\n        for e in flow[\\\"data\\\"][\\\"edges\\\"]\\n        if not (e[\\\"target\\\"] == \\\"LoopComponent-1\\\" and e[\\\"data\\\"][\\\"targetHandle\\\"].get(\\\"name\\\") == \\\"item\\\")\\n    ]\\n    issues = structural_failures(flow)\\n    assert any(\\\"not a closed cycle\\\" in i for i in issues)\\n\\n\\ndef test_should_flag_required_input_neither_connected_nor_set():\\n    flow = {\\n        \\\"data\\\": {\\n            \\\"nodes\\\": [\\n                _node(\\\"ChatInput-1\\\", \\\"ChatInput\\\"),\\n                _node(\\n                    \\\"ChatOutput-1\\\",\\n                    \\\"ChatOutput\\\",\\n                    template={\\\"input_value\\\": {\\\"required\\\": True, \\\"input_types\\\": [\\\"Message\\\"], \\\"value\\\": \\\"\\\"}},\\n                ),\\n            ],\\n            \\\"edges\\\": [_input_edge(\\\"ChatInput-1\\\", \\\"ChatOutput-1\\\", \\\"session_id\\\")],\\n        }\\n    }\\n    issues = structural_failures(flow)\\n    assert any(\\\"required input\\\" in i for i in issues)\\n\\n\\ndef test_should_not_flag_required_input_satisfied_by_value():\\n    flow = {\\n        \\\"data\\\": {\\n            \\\"nodes\\\": [\\n                _node(\\\"A-1\\\", \\\"ChatInput\\\"),\\n                _node(\\n                    \\\"B-1\\\",\\n                    \\\"ChatOutput\\\",\\n                    template={\\\"input_value\\\": {\\\"required\\\": True, \\\"input_types\\\": [\\\"Message\\\"], \\\"value\\\": \\\"hello\\\"}},\\n                ),\\n            ],\\n            \\\"edges\\\": [_input_edge(\\\"A-1\\\", \\\"B-1\\\", \\\"session_id\\\")],\\n        }\\n    }\\n    assert structural_failures(flow) == []\\n\\n\\ndef test_should_skip_advanced_and_hidden_required_inputs():\\n    flow = {\\n        \\\"data\\\": {\\n            \\\"nodes\\\": [\\n                _node(\\\"A-1\\\", \\\"ChatInput\\\"),\\n                _node(\\n                    \\\"B-1\\\",\\n                    \\\"ChatOutput\\\",\\n                    template={\\n                        \\\"adv\\\": {\\\"required\\\": True, \\\"input_types\\\": [\\\"Message\\\"], \\\"value\\\": \\\"\\\", \\\"advanced\\\": True},\\n                        \\\"hidden\\\": {\\\"required\\\": True, \\\"input_types\\\": [\\\"Message\\\"], \\\"value\\\": \\\"\\\", \\\"show\\\": False},\\n                    },\\n                ),\\n            ],\\n            \\\"edges\\\": [_input_edge(\\\"A-1\\\", \\\"B-1\\\", \\\"adv\\\")],\\n        }\\n    }\\n    assert structural_failures(flow) == []\\n\\n\\ndef test_should_flag_orphan_node_in_multi_node_flow():\\n    flow = {\\n        \\\"data\\\": {\\n            \\\"nodes\\\": [_node(\\\"A-1\\\", \\\"ChatInput\\\"), _node(\\\"B-1\\\", \\\"ChatOutput\\\"), _node(\\\"C-1\\\", \\\"TextInput\\\")],\\n            \\\"edges\\\": [_input_edge(\\\"A-1\\\", \\\"B-1\\\", \\\"input_value\\\")],\\n        }\\n    }\\n    issues = structural_failures(flow)\\n    assert any(\\\"disconnected\\\" in i for i in issues)\\n\\n\\ndef test_should_not_flag_orphan_in_single_node_flow():\\n    flow = {\\\"data\\\": {\\\"nodes\\\": [_node(\\\"A-1\\\", \\\"ChatInput\\\")], \\\"edges\\\": []}}\\n    assert structural_failures(flow) == []\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/agentic/services/test_flow_types.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"978ef6f082c6eaee012bc066e822506f1f085cb27d5e47e859b7728b5819f3e3\",\"content\":\"\\\"\\\"\\\"Tests for flow execution types and constants.\\n\\nTests the dataclasses and constants used in flow execution.\\n\\\"\\\"\\\"\\n\\nfrom pathlib import Path\\n\\nfrom langflow.agentic.services.flow_types import (\\n    FLOWS_BASE_PATH,\\n    LANGFLOW_ASSISTANT_FLOW,\\n    MAX_VALIDATION_RETRIES,\\n    STREAMING_EVENT_TIMEOUT_SECONDS,\\n    STREAMING_QUEUE_MAX_SIZE,\\n    TRANSLATION_FLOW,\\n    VALIDATION_RETRY_TEMPLATE,\\n    VALIDATION_UI_DELAY_SECONDS,\\n    FlowExecutionResult,\\n    IntentResult,\\n)\\n\\n\\ndef test_should_expose_max_flow_verification_attempts_constant_when_importing_flow_types():\\n    \\\"\\\"\\\"flow_verification.py imports MAX_FLOW_VERIFICATION_ATTEMPTS from flow_types.\\n\\n    Without this constant, importing the agentic router at boot time raises\\n    ImportError and the FastAPI server exits before binding the port (the\\n    agentic router is mounted unconditionally at api/router.py:109).\\n\\n    Bug: PR-12575 round 6 \u2014 backend boot failure\\n    \\\"\\\"\\\"\\n    # Importing flow_verification triggers the same import chain as boot.\\n    from langflow.agentic.services import flow_types\\n\\n    assert hasattr(flow_types, \\\"MAX_FLOW_VERIFICATION_ATTEMPTS\\\"), (\\n        \\\"flow_verification.py imports MAX_FLOW_VERIFICATION_ATTEMPTS from \\\"\\n        \\\"flow_types; the constant must be declared or the agentic router \\\"\\n        \\\"fails to load at server boot.\\\"\\n    )\\n    assert isinstance(flow_types.MAX_FLOW_VERIFICATION_ATTEMPTS, int)\\n    assert flow_types.MAX_FLOW_VERIFICATION_ATTEMPTS >= 1\\n\\n\\ndef test_should_load_flow_verification_module_when_constant_is_present():\\n    \\\"\\\"\\\"End-to-end import check: importing flow_verification must not raise.\\n\\n    This is the exact failure path observed at boot: the agentic router\\n    transitively imports flow_verification, which imports the missing\\n    constant. If this test passes, the boot path is clean.\\n    \\\"\\\"\\\"\\n    # Must not raise ImportError.\\n    from langflow.agentic.services import flow_verification\\n\\n    assert flow_verification.verify_built_flow is not None\\n\\n\\nclass TestFlowExecutionResult:\\n    \\\"\\\"\\\"Tests for FlowExecutionResult dataclass.\\\"\\\"\\\"\\n\\n    def test_should_create_with_defaults(self):\\n        \\\"\\\"\\\"Should create with empty result and no error by default.\\\"\\\"\\\"\\n        result = FlowExecutionResult()\\n        assert result.result == {}\\n        assert result.error is None\\n\\n    def test_should_detect_error_when_set(self):\\n        \\\"\\\"\\\"Should return has_error=True when error is set.\\\"\\\"\\\"\\n        result = FlowExecutionResult(error=ValueError(\\\"test error\\\"))\\n        assert result.has_error is True\\n        assert result.has_result is False\\n\\n    def test_should_detect_result_when_set(self):\\n        \\\"\\\"\\\"Should return has_result=True when result is non-empty.\\\"\\\"\\\"\\n        result = FlowExecutionResult(result={\\\"key\\\": \\\"value\\\"})\\n        assert result.has_result is True\\n        assert result.has_error is False\\n\\n    def test_should_allow_both_result_and_error(self):\\n        \\\"\\\"\\\"Should allow both result and error to be set simultaneously.\\\"\\\"\\\"\\n        result = FlowExecutionResult(\\n            result={\\\"partial\\\": \\\"data\\\"},\\n            error=RuntimeError(\\\"partial failure\\\"),\\n        )\\n        assert result.has_result is True\\n        assert result.has_error is True\\n\\n    def test_should_return_false_for_empty_dict_result(self):\\n        \\\"\\\"\\\"Should return has_result=False for empty dict.\\\"\\\"\\\"\\n        result = FlowExecutionResult(result={})\\n        assert result.has_result is False\\n\\n    def test_should_store_exception_details(self):\\n        \\\"\\\"\\\"Should preserve exception details.\\\"\\\"\\\"\\n        error = ValueError(\\\"detailed message\\\")\\n        result = FlowExecutionResult(error=error)\\n        assert result.error is error\\n        assert str(result.error) == \\\"detailed message\\\"\\n\\n\\nclass TestIntentResult:\\n    \\\"\\\"\\\"Tests for IntentResult dataclass.\\\"\\\"\\\"\\n\\n    def test_should_create_with_translation_and_intent(self):\\n        \\\"\\\"\\\"Should create with translation and intent fields.\\\"\\\"\\\"\\n        result = IntentResult(translation=\\\"hello world\\\", intent=\\\"question\\\")\\n        assert result.translation == \\\"hello world\\\"\\n        assert result.intent == \\\"question\\\"\\n\\n    def test_should_support_generate_component_intent(self):\\n        \\\"\\\"\\\"Should support generate_component as valid intent value.\\\"\\\"\\\"\\n        result = IntentResult(translation=\\\"create a component\\\", intent=\\\"generate_component\\\")\\n        assert result.intent == \\\"generate_component\\\"\\n\\n    def test_should_be_equality_comparable(self):\\n        \\\"\\\"\\\"Should support equality comparison.\\\"\\\"\\\"\\n        result1 = IntentResult(translation=\\\"test\\\", intent=\\\"question\\\")\\n        result2 = IntentResult(translation=\\\"test\\\", intent=\\\"question\\\")\\n        result3 = IntentResult(translation=\\\"test\\\", intent=\\\"generate_component\\\")\\n        assert result1 == result2\\n        assert result1 != result3\\n\\n    def test_should_allow_empty_translation(self):\\n        \\\"\\\"\\\"Should allow empty string as translation.\\\"\\\"\\\"\\n        result = IntentResult(translation=\\\"\\\", intent=\\\"question\\\")\\n        assert result.translation == \\\"\\\"\\n\\n\\nclass TestConstants:\\n    \\\"\\\"\\\"Tests for module constants.\\\"\\\"\\\"\\n\\n    def test_flows_base_path_should_exist(self):\\n        \\\"\\\"\\\"FLOWS_BASE_PATH should be a valid path to flows directory.\\\"\\\"\\\"\\n        assert isinstance(FLOWS_BASE_PATH, Path)\\n        assert FLOWS_BASE_PATH.name == \\\"flows\\\"\\n\\n    def test_flows_base_path_parent_should_be_agentic(self):\\n        \\\"\\\"\\\"FLOWS_BASE_PATH parent should be agentic directory.\\\"\\\"\\\"\\n        assert FLOWS_BASE_PATH.parent.name == \\\"agentic\\\"\\n\\n    def test_streaming_queue_max_size_should_be_positive(self):\\n        \\\"\\\"\\\"STREAMING_QUEUE_MAX_SIZE should be a positive integer.\\\"\\\"\\\"\\n        assert isinstance(STREAMING_QUEUE_MAX_SIZE, int)\\n        assert STREAMING_QUEUE_MAX_SIZE > 0\\n\\n    def test_streaming_queue_max_size_should_be_reasonable(self):\\n        \\\"\\\"\\\"STREAMING_QUEUE_MAX_SIZE should be within reasonable bounds.\\\"\\\"\\\"\\n        assert STREAMING_QUEUE_MAX_SIZE >= 100\\n        assert STREAMING_QUEUE_MAX_SIZE <= 10000\\n\\n    def test_streaming_timeout_should_be_positive(self):\\n        \\\"\\\"\\\"STREAMING_EVENT_TIMEOUT_SECONDS should be positive.\\\"\\\"\\\"\\n        assert isinstance(STREAMING_EVENT_TIMEOUT_SECONDS, float)\\n        assert STREAMING_EVENT_TIMEOUT_SECONDS > 0\\n\\n    def test_streaming_timeout_should_be_reasonable(self):\\n        \\\"\\\"\\\"STREAMING_EVENT_TIMEOUT_SECONDS should be within reasonable bounds.\\\"\\\"\\\"\\n        assert STREAMING_EVENT_TIMEOUT_SECONDS >= 30\\n        assert STREAMING_EVENT_TIMEOUT_SECONDS <= 600\\n\\n    def test_max_validation_retries_should_be_positive(self):\\n        \\\"\\\"\\\"MAX_VALIDATION_RETRIES should be a positive integer.\\\"\\\"\\\"\\n        assert isinstance(MAX_VALIDATION_RETRIES, int)\\n        assert MAX_VALIDATION_RETRIES > 0\\n\\n    def test_max_validation_retries_should_be_reasonable(self):\\n        \\\"\\\"\\\"MAX_VALIDATION_RETRIES should be within reasonable bounds.\\\"\\\"\\\"\\n        assert MAX_VALIDATION_RETRIES >= 1\\n        assert MAX_VALIDATION_RETRIES <= 10\\n\\n    def test_validation_ui_delay_should_be_small(self):\\n        \\\"\\\"\\\"VALIDATION_UI_DELAY_SECONDS should be a small positive value.\\\"\\\"\\\"\\n        assert isinstance(VALIDATION_UI_DELAY_SECONDS, float)\\n        assert VALIDATION_UI_DELAY_SECONDS > 0\\n        assert VALIDATION_UI_DELAY_SECONDS < 2\\n\\n    def test_langflow_assistant_flow_should_be_string(self):\\n        \\\"\\\"\\\"LANGFLOW_ASSISTANT_FLOW should be a non-empty string.\\\"\\\"\\\"\\n        assert isinstance(LANGFLOW_ASSISTANT_FLOW, str)\\n        assert len(LANGFLOW_ASSISTANT_FLOW) > 0\\n\\n    def test_translation_flow_should_be_string(self):\\n        \\\"\\\"\\\"TRANSLATION_FLOW should be a non-empty string.\\\"\\\"\\\"\\n        assert isinstance(TRANSLATION_FLOW, str)\\n        assert len(TRANSLATION_FLOW) > 0\\n\\n\\nclass TestValidationRetryTemplate:\\n    \\\"\\\"\\\"Tests for VALIDATION_RETRY_TEMPLATE constant.\\\"\\\"\\\"\\n\\n    def test_should_be_formattable_string(self):\\n        \\\"\\\"\\\"Should be a string template with format placeholders.\\\"\\\"\\\"\\n        assert isinstance(VALIDATION_RETRY_TEMPLATE, str)\\n        assert \\\"{error}\\\" in VALIDATION_RETRY_TEMPLATE\\n        assert \\\"{code}\\\" in VALIDATION_RETRY_TEMPLATE\\n\\n    def test_should_format_with_error_and_code(self):\\n        \\\"\\\"\\\"Should format correctly with error and code values.\\\"\\\"\\\"\\n        error = \\\"SyntaxError: invalid syntax\\\"\\n        code = \\\"def broken():\\\"\\n        result = VALIDATION_RETRY_TEMPLATE.format(error=error, code=code)\\n        assert error in result\\n        assert code in result\\n\\n    def test_should_include_fix_instruction(self):\\n        \\\"\\\"\\\"Should include instruction to fix the error.\\\"\\\"\\\"\\n        template_lower = VALIDATION_RETRY_TEMPLATE.lower()\\n        assert \\\"fix\\\" in template_lower or \\\"correct\\\" in template_lower\\n\\n    def test_should_reference_error(self):\\n        \\\"\\\"\\\"Should reference the error in the template.\\\"\\\"\\\"\\n        template_lower = VALIDATION_RETRY_TEMPLATE.lower()\\n        assert \\\"error\\\" in template_lower\\n\\n    def test_should_reference_code(self):\\n        \\\"\\\"\\\"Should reference the code in the template.\\\"\\\"\\\"\\n        template_lower = VALIDATION_RETRY_TEMPLATE.lower()\\n        assert \\\"code\\\" in template_lower\\n\\n    def test_should_format_with_multiline_code(self):\\n        \\\"\\\"\\\"Should format correctly with multiline code.\\\"\\\"\\\"\\n        error = \\\"IndentationError: unexpected indent\\\"\\n        code = \\\"\\\"\\\"def example():\\n    if True:\\n    print(\\\"wrong indent\\\")\\\"\\\"\\\"\\n        result = VALIDATION_RETRY_TEMPLATE.format(error=error, code=code)\\n        assert error in result\\n        assert \\\"def example():\\\" in result\\n        assert 'print(\\\"wrong indent\\\")' in result\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/agentic/services/test_flow_update_reconciliation.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"fc7d1af20804f7f6931d919defe19e8a84a748a61234cf79d0c42cfa1ff7593a\",\"content\":\"\\\"\\\"\\\"Deterministic build+run canvas-application rule (the \\\"diz que fez e n\u00e3o fez\\\" bug).\\n\\nBug shape (recurring, screenshots): the user asks to build a flow AND run\\nit (\\\"crie um flow ... rode ele\\\"). The agent builds (``set_flow``) and runs\\nit (``run_flow`` \u2192 result reported), then says \\\"criei e rodei NO CANVAS\\\" \u2014\\nbut the flow is only a *proposal* card (Add/Replace/Dismiss); the canvas\\nnever changed. Root cause: auto-apply was decided by a regex on the user's\\nwording (``_looks_like_run_request``) which misses paraphrases (\\\"rode ele\\\",\\n\\\"run it\\\", any language) \u2192 no auto-apply \u2192 gated \u2192 the agent's claim is a lie.\\n\\nFix shape (LLM/language-agnostic, deterministic): RunFlow emits a\\n``flow_ran`` signal when it ACTUALLY runs the flow. ``_reconcile_flow_updates``\\nturns \\\"the agent built AND ran the flow this turn\\\" into \\\"apply it to the\\ncanvas\\\" \u2014 never inferred from the prompt text. Running a flow the user\\ncannot see is contradictory, so build+run MUST apply.\\n\\nThese tests pin the invariant for EVERY ordering permutation so it can\\nnever silently regress: same-batch, set_flow-then-later-run, run-only,\\ncompound, incremental-only, idempotency.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom langflow.agentic.services.assistant_service import _reconcile_flow_updates\\n\\n\\ndef _reconcile(updates, **state):\\n    \\\"\\\"\\\"Call with sane defaults; return the full result tuple.\\\"\\\"\\\"\\n    base = {\\n        \\\"auto_apply_flow\\\": False,\\n        \\\"saw_set_flow\\\": False,\\n        \\\"saw_run\\\": False,\\n        \\\"last_set_flow\\\": None,\\n        \\\"set_flow_applied\\\": False,\\n    }\\n    base.update(state)\\n    return _reconcile_flow_updates(updates, **base)\\n\\n\\nSET_FLOW = {\\\"action\\\": \\\"set_flow\\\", \\\"flow\\\": {\\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}}}\\nFLOW_RAN = {\\\"action\\\": \\\"flow_ran\\\", \\\"flow_id\\\": \\\"f-1\\\"}\\nADD = {\\\"action\\\": \\\"add_component\\\", \\\"node\\\": {\\\"id\\\": \\\"n1\\\"}}\\n\\n\\nclass TestSameBatchBuildAndRun:\\n    \\\"\\\"\\\"set_flow and flow_ran drained together \u2192 set_flow auto-applies.\\\"\\\"\\\"\\n\\n    def test_set_flow_then_flow_ran_same_batch_auto_applies(self):\\n        events, auto_apply, saw_set_flow, saw_run, _last, applied = _reconcile([dict(SET_FLOW), dict(FLOW_RAN)])\\n        set_flow_events = [e for e in events if e.get(\\\"action\\\") == \\\"set_flow\\\"]\\n        assert len(set_flow_events) == 1\\n        assert set_flow_events[0][\\\"auto_apply\\\"] is True\\n        assert auto_apply is True\\n        assert saw_set_flow is True\\n        assert saw_run is True\\n        assert applied is True\\n\\n    def test_flow_ran_before_set_flow_in_same_batch_still_auto_applies(self):\\n        # Two-pass: a flow_ran anywhere in the batch must apply the set_flow,\\n        # even if it is listed BEFORE the set_flow.\\n        events, *_ = _reconcile([dict(FLOW_RAN), dict(SET_FLOW)])\\n        set_flow_events = [e for e in events if e.get(\\\"action\\\") == \\\"set_flow\\\"]\\n        assert len(set_flow_events) == 1\\n        assert set_flow_events[0][\\\"auto_apply\\\"] is True\\n\\n    def test_flow_ran_is_internal_and_never_forwarded(self):\\n        events, *_ = _reconcile([dict(SET_FLOW), dict(FLOW_RAN)])\\n        assert not any(e.get(\\\"action\\\") == \\\"flow_ran\\\" for e in events), (\\n            \\\"flow_ran is an internal signal; the frontend has no reducer for it\\\"\\n        )\\n\\n\\nclass TestLateRunReconciliation:\\n    \\\"\\\"\\\"set_flow proposed in an earlier batch, run happens later \u2192 re-apply.\\\"\\\"\\\"\\n\\n    def test_set_flow_proposed_then_run_in_later_batch_reemits_with_auto_apply(self):\\n        # Batch 1: build only (no run known yet) \u2192 proposal, NOT applied.\\n        ev1, auto1, saw_sf1, saw_run1, last1, applied1 = _reconcile([dict(SET_FLOW)])\\n        assert ev1[0].get(\\\"auto_apply\\\") is not True, \\\"no run yet \u2192 must be a proposal\\\"\\n        assert applied1 is False\\n        assert saw_sf1 is True\\n\\n        # Batch 2: the agent ran it. Must re-emit the remembered set_flow\\n        # with auto_apply so the canvas ends in the reported state.\\n        ev2, _auto2, _saw_sf2, saw_run2, _last2, applied2 = _reconcile(\\n            [dict(FLOW_RAN)],\\n            auto_apply_flow=auto1,\\n            saw_set_flow=saw_sf1,\\n            saw_run=saw_run1,\\n            last_set_flow=last1,\\n            set_flow_applied=applied1,\\n        )\\n        reapplied = [e for e in ev2 if e.get(\\\"action\\\") == \\\"set_flow\\\"]\\n        assert len(reapplied) == 1, \\\"must re-emit the set_flow to apply it\\\"\\n        assert reapplied[0][\\\"auto_apply\\\"] is True\\n        assert saw_run2 is True\\n        assert applied2 is True\\n\\n    def test_late_reconciliation_is_idempotent_across_batches(self):\\n        _ev1, a1, s1, r1, l1, ap1 = _reconcile([dict(SET_FLOW)])\\n        _ev2, a2, s2, r2, l2, ap2 = _reconcile(\\n            [dict(FLOW_RAN)],\\n            auto_apply_flow=a1,\\n            saw_set_flow=s1,\\n            saw_run=r1,\\n            last_set_flow=l1,\\n            set_flow_applied=ap1,\\n        )\\n        # A THIRD drain (empty / trailing) must NOT re-emit set_flow again.\\n        ev3, *_ = _reconcile(\\n            [],\\n            auto_apply_flow=a2,\\n            saw_set_flow=s2,\\n            saw_run=r2,\\n            last_set_flow=l2,\\n            set_flow_applied=ap2,\\n        )\\n        assert not [e for e in ev3 if e.get(\\\"action\\\") == \\\"set_flow\\\"], (\\n            \\\"set_flow must be applied exactly once, never duplicated\\\"\\n        )\\n\\n\\nclass TestNoRegression:\\n    \\\"\\\"\\\"The fix is strictly additive \u2014 existing behaviour is untouched.\\\"\\\"\\\"\\n\\n    def test_build_only_no_run_stays_a_proposal(self):\\n        events, auto_apply, _saw_set_flow, saw_run, _l, applied = _reconcile([dict(SET_FLOW)])\\n        assert events[0].get(\\\"auto_apply\\\") is not True\\n        assert auto_apply is False\\n        assert saw_run is False\\n        assert applied is False\\n\\n    def test_compound_auto_apply_unchanged(self):\\n        # Compound already sets auto_apply_flow=True up front; behaviour\\n        # must be identical (set_flow applied, single emit).\\n        events, *_, applied = _reconcile([dict(SET_FLOW)], auto_apply_flow=True)\\n        set_flow_events = [e for e in events if e.get(\\\"action\\\") == \\\"set_flow\\\"]\\n        assert len(set_flow_events) == 1\\n        assert set_flow_events[0][\\\"auto_apply\\\"] is True\\n        assert applied is True\\n\\n    def test_compound_with_run_does_not_double_emit_set_flow(self):\\n        events, *_ = _reconcile([dict(SET_FLOW), dict(FLOW_RAN)], auto_apply_flow=True)\\n        assert len([e for e in events if e.get(\\\"action\\\") == \\\"set_flow\\\"]) == 1\\n\\n    def test_incremental_edits_pass_through_untouched(self):\\n        events, _a, saw_set_flow, _r, _l, _ap = _reconcile([dict(ADD)])\\n        assert events == [ADD]\\n        assert saw_set_flow is False\\n\\n    def test_incremental_edits_plus_run_no_spurious_set_flow(self):\\n        # Run after incremental edits (no set_flow) must NOT synthesize a\\n        # set_flow re-emit (nothing remembered to apply).\\n        events, _a, saw_set_flow, saw_run, _l, _ap = _reconcile([dict(ADD), dict(FLOW_RAN)])\\n        assert events == [ADD]\\n        assert saw_set_flow is False\\n        assert saw_run is True\\n\\n    def test_run_only_batch_emits_no_events(self):\\n        # Pure \\\"run the existing flow\\\" \u2014 no canvas mutation at all. The\\n        # caller relies on an empty event list to keep has_flow_updates\\n        # unchanged so the run-only path is not rerouted (regression).\\n        events, _a, saw_set_flow, saw_run, _l, _ap = _reconcile([dict(FLOW_RAN)])\\n        assert events == []\\n        assert saw_set_flow is False\\n        assert saw_run is True\\n\\n\\nclass TestLanguageAndWordingAgnostic:\\n    \\\"\\\"\\\"The decision must NOT depend on the prompt text in any way.\\\"\\\"\\\"\\n\\n    def test_function_signature_takes_no_prompt(self):\\n        import inspect\\n\\n        params = set(inspect.signature(_reconcile_flow_updates).parameters)\\n        forbidden = {\\\"prompt\\\", \\\"user_input\\\", \\\"original_user_input\\\", \\\"text\\\", \\\"message\\\"}\\n        assert not (params & forbidden), (\\n            \\\"reconciliation must be driven by the real run action, never by \\\"\\n            f\\\"parsing the user's wording. Params: {params}\\\"\\n        )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/agentic/services/test_flow_validation.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"111da10ab5d46b63b1b74e1acc4614bad963d29feeedbf2da3cd3bbc74c5cc1a\",\"content\":\"\\\"\\\"\\\"verify_flow \u2014 the Tier-1+Tier-2 validation loop (deps injected).\\n\\nOrchestrates: ensure-agent-model (deterministic, never looped on) \u2192\\nTier-1 static \u2192 Tier-2 graph build. A fixable deterministic error is fed\\nback to the agent and re-validated, bounded by a hard attempt cap. A\\nflow that is valid + builds but whose Agent has no usable model is\\ndelivered with an honest caveat (NEEDS_CAVEAT), never looped. Never\\nsilently delivers a broken flow; never leaks secrets in the caveat.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport pytest\\nfrom langflow.agentic.services.flow_agent_model import AgentModelOutcome\\nfrom langflow.agentic.services.flow_graph_build_check import BuildCheckResult\\nfrom langflow.agentic.services.flow_static_validation import FlowValidationReport\\nfrom langflow.agentic.services.flow_validation import (\\n    FlowVerifyStatus,\\n    verify_flow,\\n)\\n\\n\\ndef _flow():\\n    return {\\\"id\\\": \\\"f\\\", \\\"name\\\": \\\"f\\\", \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}}\\n\\n\\ndef _ok_report():\\n    return FlowValidationReport(ok=True)\\n\\n\\ndef _bad_report(msg):\\n    return FlowValidationReport(ok=False, errors=[msg])\\n\\n\\nasync def _build_ok(**_kw):\\n    return BuildCheckResult(ok=True)\\n\\n\\nasync def _verify(**kw):\\n    base = {\\n        \\\"flow\\\": _flow(),\\n        \\\"flow_id\\\": \\\"flow-1\\\",\\n        \\\"user_id\\\": \\\"u1\\\",\\n        \\\"agent_model_fn\\\": lambda _f: AgentModelOutcome.NONE_NEEDED,\\n        \\\"static_fn\\\": lambda _f: _ok_report(),\\n        \\\"build_fn\\\": _build_ok,\\n        \\\"fix_fn\\\": None,\\n    }\\n    base.update(kw)\\n    if base[\\\"fix_fn\\\"] is None:\\n\\n        async def _no_fix(_err):\\n            return None\\n\\n        base[\\\"fix_fn\\\"] = _no_fix\\n    return await verify_flow(**base)\\n\\n\\nclass TestVerifyFlow:\\n    @pytest.mark.asyncio\\n    async def test_should_pass_when_static_and_build_ok_and_no_agent_needs_a_model(self):\\n        result = await _verify()\\n        assert result.status is FlowVerifyStatus.PASSED\\n        assert result.attempts == 1\\n        assert result.caveat is None\\n\\n    @pytest.mark.asyncio\\n    async def test_should_pass_silently_when_agent_model_was_auto_assigned(self):\\n        result = await _verify(agent_model_fn=lambda _f: AgentModelOutcome.ASSIGNED)\\n        assert result.status is FlowVerifyStatus.PASSED\\n        assert result.caveat is None  # auto-assign is invisible, no caveat\\n\\n    @pytest.mark.asyncio\\n    async def test_should_caveat_without_looping_when_no_provider_for_agent(self):\\n        fix_calls = []\\n\\n        async def fix(err):\\n            fix_calls.append(err)\\n            return _flow()\\n\\n        result = await _verify(\\n            agent_model_fn=lambda _f: AgentModelOutcome.NO_PROVIDER,\\n            fix_fn=fix,\\n        )\\n        assert result.status is FlowVerifyStatus.NEEDS_CAVEAT\\n        assert fix_calls == []  # NEVER loop on the no-model case\\n        assert result.caveat is not None\\n        assert \\\"model\\\" in result.caveat.lower()\\n\\n    @pytest.mark.asyncio\\n    async def test_should_retry_then_pass_when_a_tier1_error_is_fixed(self):\\n        reports = [_bad_report(\\\"Edge type mismatch on Agent-1\\\"), _ok_report()]\\n\\n        async def fix(_err):\\n            return _flow()\\n\\n        result = await _verify(static_fn=lambda _f: reports.pop(0), fix_fn=fix)\\n        assert result.status is FlowVerifyStatus.PASSED\\n        assert result.attempts == 2\\n\\n    @pytest.mark.asyncio\\n    async def test_should_retry_then_pass_when_a_tier2_build_error_is_fixed(self):\\n        builds = [BuildCheckResult(ok=False, error=\\\"Attribute build_output not found\\\"), BuildCheckResult(ok=True)]\\n\\n        async def build_fn(**_kw):\\n            return builds.pop(0)\\n\\n        async def fix(_err):\\n            return _flow()\\n\\n        result = await _verify(build_fn=build_fn, fix_fn=fix)\\n        assert result.status is FlowVerifyStatus.PASSED\\n        assert result.attempts == 2\\n\\n    @pytest.mark.asyncio\\n    async def test_should_fail_after_exhausting_attempts_on_a_persistent_error(self):\\n        calls = {\\\"n\\\": 0}\\n\\n        async def fix(_err):\\n            calls[\\\"n\\\"] += 1\\n            return _flow()\\n\\n        result = await _verify(\\n            static_fn=lambda _f: _bad_report(\\\"still broken\\\"),\\n            fix_fn=fix,\\n            max_attempts=3,\\n        )\\n        assert result.status is FlowVerifyStatus.FAILED\\n        assert result.attempts == 3\\n        assert calls[\\\"n\\\"] == 2  # fix between attempts: 3 attempts \u2192 2 fixes (cost ceiling)\\n        assert result.caveat is not None\\n        assert \\\"3\\\" in result.caveat\\n\\n    @pytest.mark.asyncio\\n    async def test_should_fail_immediately_when_the_agent_cannot_fix(self):\\n        result = await _verify(static_fn=lambda _f: _bad_report(\\\"broken\\\"))\\n        assert result.status is FlowVerifyStatus.FAILED\\n        assert result.attempts == 1\\n\\n    @pytest.mark.asyncio\\n    async def test_should_not_leak_a_secret_in_the_caveat(self):\\n        async def build_fn(**_kw):\\n            return BuildCheckResult(ok=False, error=\\\"auth failed api key sk-LEAKME1234567890SECRET\\\")\\n\\n        result = await _verify(build_fn=build_fn)\\n        assert \\\"sk-LEAKME1234567890SECRET\\\" not in (result.caveat or \\\"\\\")\\n\\n    @pytest.mark.asyncio\\n    async def test_should_respect_a_custom_max_attempts_of_one(self):\\n        calls = {\\\"n\\\": 0}\\n\\n        async def fix(_err):\\n            calls[\\\"n\\\"] += 1\\n            return _flow()\\n\\n        result = await _verify(\\n            static_fn=lambda _f: _bad_report(\\\"broken\\\"),\\n            fix_fn=fix,\\n            max_attempts=1,\\n        )\\n        assert result.status is FlowVerifyStatus.FAILED\\n        assert result.attempts == 1\\n        assert calls[\\\"n\\\"] == 0  # no fix turn when cap is 1\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/agentic/services/test_flow_verification.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d98c481508f3ac20888e9fda384b57d88527dd66162aa6371c4cf9e5520e9a3e\",\"content\":\"\\\"\\\"\\\"verify_built_flow \u2014 the run\u2192classify\u2192fix\u2192retry loop (deps injected).\\n\\nThe real graph run and the LLM fix are injected so the loop's decision\\nlogic is unit-testable in isolation: pass on success, retry fixable\\nbugs up to the cap, STOP immediately (no token burn) on external /\\ntimeout errors, fail honestly when attempts are exhausted, and never\\nleak secrets in the caveat.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport pytest\\nfrom langflow.agentic.services.flow_probe_input import PROBE_INPUT_TEXT\\nfrom langflow.agentic.services.flow_verification import (\\n    FlowVerificationStatus,\\n    verify_built_flow,\\n    verify_loop_structure,\\n)\\n\\n\\ndef _flow_with_chat_input(value=\\\"\\\"):\\n    return {\\n        \\\"name\\\": \\\"f\\\",\\n        \\\"data\\\": {\\n            \\\"nodes\\\": [\\n                {\\n                    \\\"id\\\": \\\"ChatInput-1\\\",\\n                    \\\"data\\\": {\\\"type\\\": \\\"ChatInput\\\", \\\"node\\\": {\\\"template\\\": {\\\"input_value\\\": {\\\"value\\\": value}}}},\\n                }\\n            ],\\n            \\\"edges\\\": [],\\n        },\\n    }\\n\\n\\ndef _ok(_flow):\\n    return {\\\"result\\\": \\\"it worked\\\", \\\"metrics\\\": {\\\"duration_seconds\\\": 1.0}}\\n\\n\\nclass TestVerifyBuiltFlow:\\n    @pytest.mark.asyncio\\n    async def test_should_return_passed_when_first_run_succeeds(self):\\n        fix_calls = []\\n\\n        async def run_fn(_flow):\\n            return _ok(_flow)\\n\\n        async def fix_fn(err):\\n            fix_calls.append(err)\\n\\n        result = await verify_built_flow(flow=_flow_with_chat_input(), run_fn=run_fn, fix_fn=fix_fn)\\n\\n        assert result.status is FlowVerificationStatus.PASSED\\n        assert result.attempts == 1\\n        assert fix_calls == []  # never asked the agent to fix a working flow\\n\\n    @pytest.mark.asyncio\\n    async def test_should_retry_then_pass_when_a_fixable_error_is_fixed(self):\\n        runs = []\\n\\n        async def run_fn(flow):\\n            runs.append(flow)\\n            if len(runs) == 1:\\n                return {\\\"error\\\": \\\"AttributeError: 'NoneType' object has no attribute 'text'\\\"}\\n            return _ok(flow)\\n\\n        async def fix_fn(_err):\\n            return _flow_with_chat_input(\\\"fixed\\\")\\n\\n        result = await verify_built_flow(flow=_flow_with_chat_input(), run_fn=run_fn, fix_fn=fix_fn)\\n\\n        assert result.status is FlowVerificationStatus.PASSED\\n        assert result.attempts == 2\\n\\n    @pytest.mark.asyncio\\n    async def test_should_stop_and_caveat_on_external_resource_error_without_retrying(self):\\n        fix_calls = []\\n\\n        async def run_fn(_flow):\\n            return {\\\"error\\\": \\\"Incorrect API key provided\\\"}\\n\\n        async def fix_fn(err):\\n            fix_calls.append(err)\\n            return _flow_with_chat_input()\\n\\n        result = await verify_built_flow(flow=_flow_with_chat_input(), run_fn=run_fn, fix_fn=fix_fn)\\n\\n        assert result.status is FlowVerificationStatus.NEEDS_CAVEAT\\n        assert result.attempts == 1\\n        assert fix_calls == []  # did NOT burn an LLM attempt on an unfixable error\\n        assert result.caveat is not None\\n        assert \\\"couldn't\\\" in result.caveat.lower()\\n\\n    @pytest.mark.asyncio\\n    async def test_should_stop_and_caveat_on_timeout_without_retrying(self):\\n        async def run_fn(_flow):\\n            return {\\\"error\\\": \\\"The flow run timed out after 120s.\\\"}\\n\\n        async def fix_fn(_err):\\n            msg = \\\"fix_fn must not be called on timeout\\\"\\n            raise AssertionError(msg)\\n\\n        result = await verify_built_flow(flow=_flow_with_chat_input(), run_fn=run_fn, fix_fn=fix_fn)\\n\\n        assert result.status is FlowVerificationStatus.NEEDS_CAVEAT\\n        assert result.attempts == 1\\n\\n    @pytest.mark.asyncio\\n    async def test_should_fail_after_exhausting_attempts_on_a_persistent_fixable_error(self):\\n        runs = []\\n\\n        async def run_fn(flow):\\n            runs.append(flow)\\n            return {\\\"error\\\": \\\"ValidationError: still broken\\\"}\\n\\n        # A distinct attempt each time: repeating the SAME flow is a no-op the\\n        # loop now short-circuits, which would test the guard, not the budget.\\n        async def fix_fn(_err):\\n            return _flow_with_chat_input(f\\\"attempted fix {len(runs)}\\\")\\n\\n        result = await verify_built_flow(flow=_flow_with_chat_input(), run_fn=run_fn, fix_fn=fix_fn, max_attempts=3)\\n\\n        assert result.status is FlowVerificationStatus.FAILED\\n        assert result.attempts == 3\\n        assert len(runs) == 3  # hard cost ceiling enforced\\n        assert result.caveat is not None\\n        assert \\\"3\\\" in result.caveat\\n\\n    @pytest.mark.asyncio\\n    async def test_should_stop_when_the_agent_cannot_produce_a_fix(self):\\n        runs = []\\n\\n        async def run_fn(flow):\\n            runs.append(flow)\\n            return {\\\"error\\\": \\\"KeyError: 'message'\\\"}\\n\\n        async def fix_fn(_err):\\n            return None  # agent gave up\\n\\n        result = await verify_built_flow(flow=_flow_with_chat_input(), run_fn=run_fn, fix_fn=fix_fn)\\n\\n        assert result.status is FlowVerificationStatus.FAILED\\n        assert len(runs) == 1  # no infinite loop when no fix is produced\\n\\n    @pytest.mark.asyncio\\n    async def test_should_not_leak_a_secret_in_the_caveat(self):\\n        async def run_fn(_flow):\\n            return {\\\"error\\\": \\\"Auth failed using api key sk-ABCD1234SECRETTOKEN5678\\\"}\\n\\n        async def fix_fn(_err): ...\\n\\n        result = await verify_built_flow(flow=_flow_with_chat_input(), run_fn=run_fn, fix_fn=fix_fn)\\n\\n        assert \\\"sk-ABCD1234SECRETTOKEN5678\\\" not in (result.caveat or \\\"\\\")\\n\\n    @pytest.mark.asyncio\\n    async def test_should_apply_probe_input_before_running(self):\\n        seen = {}\\n\\n        async def run_fn(flow):\\n            seen[\\\"value\\\"] = flow[\\\"data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"input_value\\\"][\\\"value\\\"]\\n            return _ok(flow)\\n\\n        async def fix_fn(_err): ...\\n\\n        await verify_built_flow(flow=_flow_with_chat_input(\\\"\\\"), run_fn=run_fn, fix_fn=fix_fn)\\n\\n        assert seen[\\\"value\\\"] == PROBE_INPUT_TEXT\\n\\n    @pytest.mark.asyncio\\n    async def test_should_respect_a_custom_max_attempts_of_one(self):\\n        runs = []\\n\\n        async def run_fn(flow):\\n            runs.append(flow)\\n            return {\\\"error\\\": \\\"TypeError: broken\\\"}\\n\\n        async def fix_fn(_err):\\n            return _flow_with_chat_input()\\n\\n        result = await verify_built_flow(flow=_flow_with_chat_input(), run_fn=run_fn, fix_fn=fix_fn, max_attempts=1)\\n\\n        assert result.status is FlowVerificationStatus.FAILED\\n        assert len(runs) == 1\\n\\n\\nclass TestVerifyLoopStructure:\\n    @pytest.mark.asyncio\\n    async def test_should_pass_immediately_when_structure_is_sound(self):\\n        fixes = []\\n\\n        async def fix_fn(_err):\\n            fixes.append(_err)\\n\\n        result = await verify_loop_structure(flow={\\\"a\\\": 1}, validate_fn=lambda _f: [], fix_fn=fix_fn)\\n\\n        assert result.status is FlowVerificationStatus.PASSED\\n        assert result.caveat is None\\n        assert fixes == []  # a sound loop is never sent for a fix turn\\n\\n    @pytest.mark.asyncio\\n    async def test_should_retry_then_pass_when_the_fix_repairs_the_wiring(self):\\n        state = {\\\"fixed\\\": False}\\n\\n        def validate_fn(_flow):\\n            return [] if state[\\\"fixed\\\"] else [\\\"Loop has no data source\\\"]\\n\\n        async def fix_fn(_err):\\n            state[\\\"fixed\\\"] = True\\n            return {\\\"repaired\\\": True}\\n\\n        result = await verify_loop_structure(flow={\\\"broken\\\": True}, validate_fn=validate_fn, fix_fn=fix_fn)\\n\\n        assert result.status is FlowVerificationStatus.PASSED\\n        assert result.flow == {\\\"repaired\\\": True}\\n\\n    @pytest.mark.asyncio\\n    async def test_should_caveat_incomplete_when_wiring_stays_broken(self):\\n        async def fix_fn(_err):\\n            return {\\\"still\\\": \\\"broken\\\"}\\n\\n        result = await verify_loop_structure(\\n            flow={\\\"broken\\\": True},\\n            validate_fn=lambda _f: [\\\"Loop has no data source\\\"],\\n            fix_fn=fix_fn,\\n            max_attempts=3,\\n        )\\n\\n        assert result.status is FlowVerificationStatus.NEEDS_CAVEAT\\n        assert \\\"loop\\\" in result.caveat.lower()\\n        assert \\\"incomplete\\\" in result.caveat.lower()\\n\\n    @pytest.mark.asyncio\\n    async def test_should_stop_when_the_agent_cannot_produce_a_fix(self):\\n        calls = {\\\"n\\\": 0}\\n\\n        async def fix_fn(_err):\\n            calls[\\\"n\\\"] += 1\\n\\n        result = await verify_loop_structure(\\n            flow={\\\"broken\\\": True},\\n            validate_fn=lambda _f: [\\\"Loop has no data source\\\"],\\n            fix_fn=fix_fn,\\n            max_attempts=3,\\n        )\\n\\n        assert result.status is FlowVerificationStatus.NEEDS_CAVEAT\\n        assert calls[\\\"n\\\"] == 1  # gave up after the first fix returned nothing\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/agentic/services/test_flow_verification_no_progress.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d86832750f19f00e393a785166c3d616a9992a88328b441bffd70083f1611d87\",\"content\":\"\\\"\\\"\\\"LE-1776 item 1(b) \u2014 verification must not repair away a deliberate incompleteness.\\n\\nThe repair loop used to command the agent to fix the wiring unconditionally, so a\\nuser who explicitly asked for an unconnected component got it silently connected.\\nThe agent holds the user's request in context, so the decision belongs to it \u2014 the\\nretry prompt now lets it decline. Declining means returning the flow unchanged, and\\nthe loop detects that structurally (no keyword matching, works in any language) and\\nstops instead of burning the remaining attempts re-asking.\\n\\nSame guard covers the cost case the ticket raised: an agent that cannot fix a flow\\nused to be asked ``MAX_FLOW_VERIFICATION_ATTEMPTS`` times for the same no-op.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport copy\\n\\nimport pytest\\nfrom langflow.agentic.services.flow_structural_validation import FLOW_STRUCTURE_RETRY_TEMPLATE\\nfrom langflow.agentic.services.flow_verification import (\\n    FlowVerificationStatus,\\n    verify_built_flow,\\n    verify_loop_structure,\\n)\\n\\n\\ndef _flow(n_nodes: int = 1, n_edges: int = 0) -> dict:\\n    return {\\n        \\\"data\\\": {\\n            \\\"nodes\\\": [{\\\"id\\\": f\\\"N{i}\\\", \\\"data\\\": {\\\"id\\\": f\\\"N{i}\\\", \\\"type\\\": \\\"LoopComponent\\\"}} for i in range(n_nodes)],\\n            \\\"edges\\\": [\\n                {\\\"source\\\": f\\\"N{i}\\\", \\\"target\\\": f\\\"N{i + 1}\\\", \\\"data\\\": {\\\"sourceHandle\\\": {}, \\\"targetHandle\\\": {}}}\\n                for i in range(n_edges)\\n            ],\\n        }\\n    }\\n\\n\\nclass TestLoopStructureStopsWhenTheAgentDeclines:\\n    @pytest.mark.asyncio\\n    async def test_should_stop_after_one_no_op_fix_turn(self):\\n        \\\"\\\"\\\"An unchanged flow means \\\"I am not fixing this\\\" \u2014 stop asking.\\\"\\\"\\\"\\n        calls = []\\n\\n        async def fix_fn(error: str):\\n            calls.append(error)\\n            return copy.deepcopy(_flow())  # same structure back\\n\\n        result = await verify_loop_structure(\\n            flow=_flow(),\\n            validate_fn=lambda _f: [\\\"loop has no data source\\\"],\\n            fix_fn=fix_fn,\\n            max_attempts=3,\\n        )\\n\\n        assert len(calls) == 1, f\\\"kept re-asking after a no-op fix: {len(calls)} turns\\\"\\n        assert result.status is FlowVerificationStatus.NEEDS_CAVEAT\\n\\n    @pytest.mark.asyncio\\n    async def test_should_deliver_the_flow_the_user_asked_for_unmodified(self):\\n        original = _flow()\\n\\n        async def fix_fn(_error: str):\\n            return copy.deepcopy(original)\\n\\n        result = await verify_loop_structure(\\n            flow=original,\\n            validate_fn=lambda _f: [\\\"orphan node\\\"],\\n            fix_fn=fix_fn,\\n            max_attempts=3,\\n        )\\n\\n        assert len(result.flow[\\\"data\\\"][\\\"nodes\\\"]) == 1\\n        assert result.flow[\\\"data\\\"][\\\"edges\\\"] == []\\n        assert result.caveat is not None, \\\"an unrepaired flow must still be flagged honestly\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_should_keep_iterating_while_the_agent_makes_progress(self):\\n        \\\"\\\"\\\"Non-regression: a genuine repair sequence must still run to completion.\\\"\\\"\\\"\\n        flows = [_flow(3, 1), _flow(5, 4)]\\n        calls = []\\n\\n        async def fix_fn(_error: str):\\n            calls.append(1)\\n            return flows.pop(0)\\n\\n        result = await verify_loop_structure(\\n            flow=_flow(1),\\n            validate_fn=lambda f: [] if len(f[\\\"data\\\"][\\\"nodes\\\"]) == 5 else [\\\"still incomplete\\\"],\\n            fix_fn=fix_fn,\\n            max_attempts=3,\\n        )\\n\\n        assert len(calls) == 2\\n        assert result.status is FlowVerificationStatus.PASSED\\n        assert len(result.flow[\\\"data\\\"][\\\"nodes\\\"]) == 5\\n\\n\\nclass TestBuiltFlowStopsWhenTheFixIsANoOp:\\n    @pytest.mark.asyncio\\n    async def test_should_not_rerun_an_unchanged_flow(self):\\n        runs, fixes = [], []\\n\\n        async def run_fn(_flow):\\n            runs.append(1)\\n            return {\\\"error\\\": \\\"component X failed\\\"}\\n\\n        async def fix_fn(_error):\\n            fixes.append(1)\\n            return copy.deepcopy(_flow(2, 1))\\n\\n        result = await verify_built_flow(\\n            flow=_flow(2, 1),\\n            run_fn=run_fn,\\n            fix_fn=fix_fn,\\n            max_attempts=3,\\n        )\\n\\n        assert len(fixes) == 1, \\\"re-ran the same flow after a no-op fix\\\"\\n        assert len(runs) == 1, \\\"burned a real run on an unchanged flow\\\"\\n        assert result.status is FlowVerificationStatus.FAILED\\n\\n    @pytest.mark.asyncio\\n    async def test_should_keep_retrying_when_the_fix_changes_the_flow(self):\\n        \\\"\\\"\\\"Non-regression: real repairs still get their full attempt budget.\\\"\\\"\\\"\\n        runs = []\\n\\n        async def run_fn(flow):\\n            runs.append(len(flow[\\\"data\\\"][\\\"nodes\\\"]))\\n            return {} if len(flow[\\\"data\\\"][\\\"nodes\\\"]) == 4 else {\\\"error\\\": \\\"boom\\\"}\\n\\n        async def fix_fn(_error):\\n            return _flow(4, 3)\\n\\n        result = await verify_built_flow(flow=_flow(2, 1), run_fn=run_fn, fix_fn=fix_fn, max_attempts=3)\\n\\n        assert runs == [2, 4]\\n        assert result.status is FlowVerificationStatus.PASSED\\n\\n\\nclass TestRetryPromptOffersAnOptOut:\\n    def test_template_lets_the_agent_honour_a_deliberate_incompleteness(self):\\n        \\\"\\\"\\\"Language-agnostic by construction: the model decides, no keyword match.\\\"\\\"\\\"\\n        lowered = FLOW_STRUCTURE_RETRY_TEMPLATE.lower()\\n\\n        assert \\\"{error}\\\" in FLOW_STRUCTURE_RETRY_TEMPLATE\\n        assert \\\"leave it\\\" in lowered or \\\"leave the flow\\\" in lowered, \\\"no opt-out offered to the agent\\\"\\n        assert \\\"asked\\\" in lowered, \\\"the opt-out must be conditioned on what the user asked for\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/agentic/services/test_run_flow_tool.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"941875f81cb83b81cb7bb60b4c615f74aecb0112917dfd1eacdd8e9c5f6c06c6\",\"content\":\"\\\"\\\"\\\"RunFlow MCP tool \u2014 the agent-facing piece.\\n\\nLives in lfx.mcp.flow_builder_tools but is exercised here (backend tree)\\nbecause it lazily imports langflow.agentic.services.flow_run, which the\\nisolated lfx suite cannot resolve.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\nfrom unittest.mock import AsyncMock, patch\\n\\nfrom lfx.mcp.flow_builder_tools import (\\n    RunFlow,\\n    drain_flow_events,\\n    init_working_flow,\\n    reset_working_flow,\\n)\\n\\nRWF = \\\"langflow.agentic.services.flow_run.run_working_flow\\\"\\n\\n\\ndef _run(tool: RunFlow):\\n    return asyncio.run(tool.run_flow())\\n\\n\\nclass TestRunFlowTool:\\n    def setup_method(self):\\n        reset_working_flow()\\n\\n    def test_returns_result_text_for_the_agent_on_success(self):\\n        init_working_flow(\\n            {\\\"name\\\": \\\"F\\\", \\\"data\\\": {\\\"nodes\\\": [{\\\"id\\\": \\\"ChatInput-1\\\"}], \\\"edges\\\": []}},\\n            \\\"flow-1\\\",\\n        )\\n        with patch(RWF, new_callable=AsyncMock, return_value={\\\"result\\\": \\\"woof\\\"}) as m:\\n            data = _run(RunFlow())\\n\\n        m.assert_awaited_once()\\n        # The LLM reads `text`; it must carry the run result so the agent can\\n        # answer questions about it.\\n        assert data.data[\\\"text\\\"] == \\\"woof\\\"\\n        assert data.data[\\\"result\\\"] == \\\"woof\\\"\\n\\n    def test_exposes_run_metrics_to_the_agent(self):\\n        init_working_flow(\\n            {\\\"name\\\": \\\"F\\\", \\\"data\\\": {\\\"nodes\\\": [{\\\"id\\\": \\\"ChatInput-1\\\"}], \\\"edges\\\": []}},\\n            \\\"flow-1\\\",\\n        )\\n        metrics = {\\n            \\\"duration_seconds\\\": 1.25,\\n            \\\"input_tokens\\\": 7,\\n            \\\"output_tokens\\\": 3,\\n            \\\"total_tokens\\\": 10,\\n        }\\n        with patch(\\n            RWF,\\n            new_callable=AsyncMock,\\n            return_value={\\\"result\\\": \\\"woof\\\", \\\"metrics\\\": metrics},\\n        ):\\n            data = _run(RunFlow())\\n\\n        # Structured for any programmatic use.\\n        assert data.data[\\\"metrics\\\"] == metrics\\n        # The LLM only reads `text`; the performance summary must be in it so\\n        # the agent can actually report time/tokens to the user.\\n        assert \\\"1.25\\\" in data.data[\\\"text\\\"]\\n        assert \\\"10\\\" in data.data[\\\"text\\\"]\\n\\n    def test_refuses_when_canvas_is_empty_without_running(self):\\n        init_working_flow({\\\"name\\\": \\\"F\\\", \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}}, \\\"flow-1\\\")\\n        with patch(RWF, new_callable=AsyncMock) as m:\\n            data = _run(RunFlow())\\n\\n        m.assert_not_awaited()\\n        assert \\\"error\\\" in data.data\\n        assert \\\"no flow\\\" in data.data[\\\"error\\\"].lower() or \\\"empty\\\" in data.data[\\\"error\\\"].lower()\\n\\n    def test_surfaces_run_error_as_data_error_not_exception(self):\\n        init_working_flow(\\n            {\\\"name\\\": \\\"F\\\", \\\"data\\\": {\\\"nodes\\\": [{\\\"id\\\": \\\"Agent-1\\\"}], \\\"edges\\\": []}},\\n            \\\"flow-1\\\",\\n        )\\n        with patch(RWF, new_callable=AsyncMock, return_value={\\\"error\\\": \\\"Rate limit exceeded.\\\"}):\\n            data = _run(RunFlow())\\n\\n        assert data.data[\\\"error\\\"] == \\\"Rate limit exceeded.\\\"\\n        assert data.data[\\\"text\\\"] == \\\"Rate limit exceeded.\\\"\\n\\n    def test_passes_working_flow_and_flow_id_to_orchestration(self):\\n        flow = {\\\"name\\\": \\\"F\\\", \\\"data\\\": {\\\"nodes\\\": [{\\\"id\\\": \\\"ChatInput-1\\\"}], \\\"edges\\\": []}}\\n        init_working_flow(flow, \\\"flow-xyz\\\")\\n        with patch(RWF, new_callable=AsyncMock, return_value={\\\"result\\\": \\\"ok\\\"}) as m:\\n            _run(RunFlow())\\n\\n        kwargs = m.call_args.kwargs\\n        assert kwargs[\\\"flow_id\\\"] == \\\"flow-xyz\\\"\\n        assert kwargs[\\\"flow_data\\\"][\\\"data\\\"][\\\"nodes\\\"][0][\\\"id\\\"] == \\\"ChatInput-1\\\"\\n\\n\\nclass TestRunFlowEmitsRanSignal:\\n    \\\"\\\"\\\"RunFlow must emit a deterministic ``flow_ran`` signal on success.\\n\\n    This is the LLM/language-agnostic anchor for \\\"the agent built AND ran\\n    the flow this turn \u2192 apply it to the canvas\\\". It fires on the REAL\\n    action (a successful run), never inferred from the user's wording, so\\n    paraphrases like \\\"rode ele\\\" / \\\"run it\\\" / any language work identically.\\n    \\\"\\\"\\\"\\n\\n    def setup_method(self):\\n        reset_working_flow()\\n\\n    def test_emits_flow_ran_on_successful_run(self):\\n        init_working_flow(\\n            {\\\"name\\\": \\\"F\\\", \\\"data\\\": {\\\"nodes\\\": [{\\\"id\\\": \\\"ChatInput-1\\\"}], \\\"edges\\\": []}},\\n            \\\"flow-1\\\",\\n        )\\n        with patch(RWF, new_callable=AsyncMock, return_value={\\\"result\\\": \\\"12.0\\\"}):\\n            _run(RunFlow())\\n\\n        events = drain_flow_events()\\n        ran = [e for e in events if e.get(\\\"action\\\") == \\\"flow_ran\\\"]\\n        assert len(ran) == 1, f\\\"expected exactly one flow_ran, got {events}\\\"\\n\\n    def test_does_not_emit_flow_ran_when_run_errors(self):\\n        init_working_flow(\\n            {\\\"name\\\": \\\"F\\\", \\\"data\\\": {\\\"nodes\\\": [{\\\"id\\\": \\\"Agent-1\\\"}], \\\"edges\\\": []}},\\n            \\\"flow-1\\\",\\n        )\\n        with patch(RWF, new_callable=AsyncMock, return_value={\\\"error\\\": \\\"Authentication failed.\\\"}):\\n            _run(RunFlow())\\n\\n        assert not [e for e in drain_flow_events() if e.get(\\\"action\\\") == \\\"flow_ran\\\"], (\\n            \\\"a failed run must NOT claim the flow ran (no false canvas application)\\\"\\n        )\\n\\n    def test_does_not_emit_flow_ran_when_canvas_empty(self):\\n        init_working_flow({\\\"name\\\": \\\"F\\\", \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}}, \\\"flow-1\\\")\\n        with patch(RWF, new_callable=AsyncMock):\\n            _run(RunFlow())\\n\\n        assert not [e for e in drain_flow_events() if e.get(\\\"action\\\") == \\\"flow_ran\\\"]\\n\\n\\nclass TestRunFlowInjectsVerifiedModel:\\n    \\\"\\\"\\\"The assistant-triggered run must use a model that AUTHENTICATES.\\n\\n    Bug (real user): the assistant built ChatInput->Agent->ChatOutput and\\n    ran it; the Agent's model (LLM-chosen / empty) had no configured key\\n    -> \\\"Authentication failed. Check your API key.\\\" The assistant itself\\n    runs with a verified provider/model/api_key (agent_run_context); that\\n    working credential must be injected into the Agent before running so\\n    the user actually gets a result. Deterministic, LLM-agnostic.\\n    \\\"\\\"\\\"\\n\\n    def setup_method(self):\\n        reset_working_flow()\\n\\n    def teardown_method(self):\\n        from langflow.agentic.services.agent_run_context import reset_agent_run_model\\n\\n        reset_working_flow()\\n        reset_agent_run_model()\\n\\n    def _agent_flow(self):\\n        return {\\n            \\\"name\\\": \\\"F\\\",\\n            \\\"data\\\": {\\n                \\\"nodes\\\": [\\n                    {\\n                        \\\"id\\\": \\\"Agent-1\\\",\\n                        \\\"data\\\": {\\\"type\\\": \\\"Agent\\\", \\\"node\\\": {\\\"template\\\": {\\\"model\\\": {\\\"value\\\": \\\"\\\"}}}},\\n                    }\\n                ],\\n                \\\"edges\\\": [],\\n            },\\n        }\\n\\n    def test_injects_the_assistants_verified_model_into_modelless_agent_before_running(self):\\n        from langflow.agentic.services.agent_run_context import set_agent_run_model\\n\\n        set_agent_run_model(\\\"OpenAI\\\", \\\"gpt-4o\\\", \\\"OPENAI_API_KEY\\\")\\n        init_working_flow(self._agent_flow(), \\\"flow-1\\\")\\n\\n        with patch(RWF, new_callable=AsyncMock, return_value={\\\"result\\\": \\\"42 is prime\\\"}) as m:\\n            data = _run(RunFlow())\\n\\n        flow_data = m.await_args.kwargs[\\\"flow_data\\\"]\\n        agent_tmpl = flow_data[\\\"data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"]\\n        model_value = agent_tmpl[\\\"model\\\"][\\\"value\\\"]\\n        # The Agent now carries the assistant's verified model (structured),\\n        # not the empty/LLM-chosen one -> the run can authenticate.\\n        assert isinstance(model_value, list)\\n        assert model_value\\n        assert model_value[0][\\\"name\\\"] == \\\"gpt-4o\\\"\\n        assert model_value[0][\\\"provider\\\"] == \\\"OpenAI\\\"\\n        assert data.data[\\\"result\\\"] == \\\"42 is prime\\\"\\n\\n    def test_runs_normally_when_no_verified_model_is_bound(self):\\n        # No agent_run_context set -> no injection, but the run still works\\n        # (no regression to the existing success path).\\n        init_working_flow(self._agent_flow(), \\\"flow-1\\\")\\n        with patch(RWF, new_callable=AsyncMock, return_value={\\\"result\\\": \\\"ok\\\"}) as m:\\n            data = _run(RunFlow())\\n\\n        m.assert_awaited_once()\\n        assert data.data[\\\"result\\\"] == \\\"ok\\\"\\n\\n    def test_does_not_inject_runtime_model_when_configuration_is_disallowed(self):\\n        from langflow.agentic.services.agent_run_context import set_agent_run_model\\n\\n        set_agent_run_model(\\n            \\\"Anthropic\\\",\\n            \\\"claude-sonnet-4-5\\\",\\n            \\\"ANTHROPIC_API_KEY\\\",\\n            allow_configuration=False,\\n        )\\n        init_working_flow(self._agent_flow(), \\\"flow-1\\\")\\n\\n        with patch(RWF, new_callable=AsyncMock, return_value={\\\"result\\\": \\\"ok\\\"}) as m:\\n            _run(RunFlow())\\n\\n        flow_data = m.await_args.kwargs[\\\"flow_data\\\"]\\n        model_value = flow_data[\\\"data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"model\\\"][\\\"value\\\"]\\n        assert model_value == \\\"\\\"\\n\\n\\nclass TestRunFlowEnforcesRequestedModel:\\n    \\\"\\\"\\\"A model the USER explicitly named must win on the canvas.\\n\\n    Bug (real user): asked for the OpenAI gpt-5.4 model; the assistant's prose\\n    said gpt-5.4 but the canvas Agent showed gpt-5.5 (the assistant's OWN\\n    runtime model). Root cause: the agent left the Agent's model empty/wrong,\\n    and the run-time fill used the assistant's verified runtime model instead\\n    of the model the user asked for. When the request named a model, it must be\\n    ENFORCED on every Agent (overwrite), never the runtime model.\\n    \\\"\\\"\\\"\\n\\n    def setup_method(self):\\n        reset_working_flow()\\n\\n    def teardown_method(self):\\n        from langflow.agentic.services.agent_run_context import (\\n            reset_agent_run_model,\\n            reset_requested_agent_model,\\n        )\\n\\n        reset_working_flow()\\n        reset_agent_run_model()\\n        reset_requested_agent_model()\\n\\n    def _agent_flow(self, existing_model_name: str):\\n        # Simulate what the build produced: an Agent already carrying the\\n        # assistant's runtime model (the wrong one) \u2014 enforcement must replace it.\\n        model_value = [{\\\"provider\\\": \\\"OpenAI\\\", \\\"name\\\": existing_model_name}] if existing_model_name else \\\"\\\"\\n        return {\\n            \\\"name\\\": \\\"F\\\",\\n            \\\"data\\\": {\\n                \\\"nodes\\\": [\\n                    {\\n                        \\\"id\\\": \\\"Agent-1\\\",\\n                        \\\"data\\\": {\\\"type\\\": \\\"Agent\\\", \\\"node\\\": {\\\"template\\\": {\\\"model\\\": {\\\"value\\\": model_value}}}},\\n                    }\\n                ],\\n                \\\"edges\\\": [],\\n            },\\n        }\\n\\n    def test_enforces_the_user_named_model_over_the_runtime_model(self):\\n        from langflow.agentic.services.agent_run_context import (\\n            set_agent_run_model,\\n            set_requested_agent_model,\\n        )\\n\\n        # Assistant's own runtime model (the one that would be wrongly injected).\\n        set_agent_run_model(\\\"OpenAI\\\", \\\"gpt-5.5\\\", \\\"OPENAI_API_KEY\\\")\\n        # The model the user explicitly asked for.\\n        set_requested_agent_model(\\\"OpenAI\\\", \\\"gpt-5.4\\\", \\\"OPENAI_API_KEY\\\")\\n        # Build left the Agent on the assistant's runtime model (the bug).\\n        init_working_flow(self._agent_flow(\\\"gpt-5.5\\\"), \\\"flow-1\\\")\\n\\n        with patch(RWF, new_callable=AsyncMock, return_value={\\\"result\\\": \\\"good morning!\\\"}) as m:\\n            _run(RunFlow())\\n\\n        flow_data = m.await_args.kwargs[\\\"flow_data\\\"]\\n        model_value = flow_data[\\\"data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"model\\\"][\\\"value\\\"]\\n        assert isinstance(model_value, list)\\n        assert model_value\\n        assert model_value[0][\\\"name\\\"] == \\\"gpt-5.4\\\"\\n        assert model_value[0][\\\"provider\\\"] == \\\"OpenAI\\\"\\n\\n    def test_enforces_user_model_even_when_agent_left_it_empty(self):\\n        from langflow.agentic.services.agent_run_context import (\\n            set_agent_run_model,\\n            set_requested_agent_model,\\n        )\\n\\n        set_agent_run_model(\\\"OpenAI\\\", \\\"gpt-5.5\\\", \\\"OPENAI_API_KEY\\\")\\n        set_requested_agent_model(\\\"OpenAI\\\", \\\"gpt-5.4\\\", \\\"OPENAI_API_KEY\\\")\\n        init_working_flow(self._agent_flow(\\\"\\\"), \\\"flow-1\\\")  # empty model\\n\\n        with patch(RWF, new_callable=AsyncMock, return_value={\\\"result\\\": \\\"ok\\\"}) as m:\\n            _run(RunFlow())\\n\\n        flow_data = m.await_args.kwargs[\\\"flow_data\\\"]\\n        model_value = flow_data[\\\"data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"model\\\"][\\\"value\\\"]\\n        assert model_value[0][\\\"name\\\"] == \\\"gpt-5.4\\\"\\n\\n    def test_falls_back_to_runtime_model_when_no_model_was_requested(self):\\n        # Regression guard: with no explicit request, the existing behavior\\n        # (fill an empty model with the verified runtime model) is preserved.\\n        from langflow.agentic.services.agent_run_context import set_agent_run_model\\n\\n        set_agent_run_model(\\\"OpenAI\\\", \\\"gpt-5.5\\\", \\\"OPENAI_API_KEY\\\")\\n        init_working_flow(self._agent_flow(\\\"\\\"), \\\"flow-1\\\")\\n\\n        with patch(RWF, new_callable=AsyncMock, return_value={\\\"result\\\": \\\"ok\\\"}) as m:\\n            _run(RunFlow())\\n\\n        flow_data = m.await_args.kwargs[\\\"flow_data\\\"]\\n        model_value = flow_data[\\\"data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"model\\\"][\\\"value\\\"]\\n        assert model_value[0][\\\"name\\\"] == \\\"gpt-5.5\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/agentic/utils/test_flow_component.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"30b7306a5d464b32e616ea03a8ae812fc7083a67db487d933ee80cc40e76aee1\",\"content\":\"\\\"\\\"\\\"Tests for flow component operations utilities.\\n\\nTests get_component_details, get_component_field_value,\\nupdate_component_field_value, and list_component_fields.\\n\\\"\\\"\\\"\\n\\nfrom contextlib import asynccontextmanager\\nfrom datetime import datetime, timezone\\nfrom unittest.mock import AsyncMock, MagicMock, patch\\nfrom uuid import UUID, uuid4\\n\\nimport pytest\\nfrom langflow.agentic.utils.flow_component import (\\n    get_component_details,\\n    get_component_field_value,\\n    list_component_fields,\\n    update_component_field_value,\\n)\\n\\nMODULE = \\\"langflow.agentic.utils.flow_component\\\"\\n\\nFLOW_ID = str(uuid4())\\nUSER_ID = str(uuid4())\\n\\n\\ndef _mock_logger():\\n    \\\"\\\"\\\"Create a mock async logger.\\\"\\\"\\\"\\n    mock = MagicMock()\\n    mock.aerror = AsyncMock()\\n    mock.ainfo = AsyncMock()\\n    return mock\\n\\n\\ndef _make_flow(*, has_data=True, name=\\\"TestFlow\\\", user_id=None):\\n    \\\"\\\"\\\"Create a mock flow object.\\\"\\\"\\\"\\n    flow = MagicMock()\\n    flow.id = UUID(FLOW_ID)\\n    flow.name = name\\n    flow.user_id = UUID(user_id or USER_ID)\\n    flow.data = (\\n        {\\n            \\\"nodes\\\": [\\n                {\\n                    \\\"id\\\": \\\"comp-1\\\",\\n                    \\\"data\\\": {\\n                        \\\"node\\\": {\\n                            \\\"type\\\": \\\"ChatInput\\\",\\n                            \\\"display_name\\\": \\\"Chat Input\\\",\\n                            \\\"description\\\": \\\"A chat input component\\\",\\n                            \\\"template\\\": {\\n                                \\\"input_value\\\": {\\n                                    \\\"value\\\": \\\"hello\\\",\\n                                    \\\"field_type\\\": \\\"str\\\",\\n                                    \\\"display_name\\\": \\\"Input Value\\\",\\n                                    \\\"required\\\": True,\\n                                    \\\"advanced\\\": False,\\n                                    \\\"show\\\": True,\\n                                },\\n                                \\\"sender_name\\\": {\\n                                    \\\"value\\\": \\\"User\\\",\\n                                    \\\"field_type\\\": \\\"str\\\",\\n                                    \\\"display_name\\\": \\\"Sender Name\\\",\\n                                    \\\"required\\\": False,\\n                                    \\\"advanced\\\": True,\\n                                    \\\"show\\\": True,\\n                                },\\n                            },\\n                            \\\"outputs\\\": [{\\\"name\\\": \\\"message\\\"}],\\n                        },\\n                    },\\n                }\\n            ],\\n        }\\n        if has_data\\n        else None\\n    )\\n    return flow\\n\\n\\ndef _make_vertex():\\n    \\\"\\\"\\\"Create a mock vertex (graph node).\\\"\\\"\\\"\\n    vertex = MagicMock()\\n    vertex.id = \\\"comp-1\\\"\\n    vertex.edges = []\\n    vertex.to_data.return_value = _make_flow().data[\\\"nodes\\\"][0]\\n    return vertex\\n\\n\\ndef _make_graph(vertex=None):\\n    \\\"\\\"\\\"Create a mock graph with a vertex.\\\"\\\"\\\"\\n    graph = MagicMock()\\n    v = vertex or _make_vertex()\\n    graph.get_vertex.return_value = v\\n    graph.vertices = [v]\\n    graph.edges = []\\n    return graph\\n\\n\\nclass TestGetComponentDetails:\\n    \\\"\\\"\\\"Tests for get_component_details.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_should_return_component_data(self):\\n        \\\"\\\"\\\"Should return component details including type, display_name, template.\\\"\\\"\\\"\\n        flow = _make_flow()\\n        graph = _make_graph()\\n\\n        with (\\n            patch(f\\\"{MODULE}.get_flow_by_id_or_endpoint_name\\\", new_callable=AsyncMock, return_value=flow),\\n            patch(f\\\"{MODULE}.Graph.from_payload\\\", return_value=graph),\\n            patch(f\\\"{MODULE}.logger\\\", _mock_logger()),\\n        ):\\n            result = await get_component_details(\\\"test-flow\\\", \\\"comp-1\\\")\\n\\n        assert result[\\\"component_id\\\"] == \\\"comp-1\\\"\\n        assert result[\\\"component_type\\\"] == \\\"ChatInput\\\"\\n        assert result[\\\"display_name\\\"] == \\\"Chat Input\\\"\\n        assert result[\\\"flow_id\\\"] == FLOW_ID\\n\\n    @pytest.mark.asyncio\\n    async def test_should_return_error_when_flow_not_found(self):\\n        \\\"\\\"\\\"Should return error dict when flow is None.\\\"\\\"\\\"\\n        with (\\n            patch(f\\\"{MODULE}.get_flow_by_id_or_endpoint_name\\\", new_callable=AsyncMock, return_value=None),\\n            patch(f\\\"{MODULE}.logger\\\", _mock_logger()),\\n        ):\\n            result = await get_component_details(\\\"missing-flow\\\", \\\"comp-1\\\")\\n\\n        assert \\\"error\\\" in result\\n        assert \\\"not found\\\" in result[\\\"error\\\"]\\n\\n    @pytest.mark.asyncio\\n    async def test_should_return_error_when_flow_has_no_data(self):\\n        \\\"\\\"\\\"Should return error when flow.data is None.\\\"\\\"\\\"\\n        flow = _make_flow(has_data=False)\\n\\n        with (\\n            patch(f\\\"{MODULE}.get_flow_by_id_or_endpoint_name\\\", new_callable=AsyncMock, return_value=flow),\\n            patch(f\\\"{MODULE}.logger\\\", _mock_logger()),\\n        ):\\n            result = await get_component_details(\\\"test-flow\\\", \\\"comp-1\\\")\\n\\n        assert \\\"error\\\" in result\\n        assert \\\"no data\\\" in result[\\\"error\\\"]\\n\\n    @pytest.mark.asyncio\\n    async def test_should_return_error_when_component_not_found(self):\\n        \\\"\\\"\\\"Should return error when vertex doesn't exist in graph.\\\"\\\"\\\"\\n        flow = _make_flow()\\n        graph = MagicMock()\\n        graph.get_vertex.side_effect = ValueError(\\\"not found\\\")\\n\\n        with (\\n            patch(f\\\"{MODULE}.get_flow_by_id_or_endpoint_name\\\", new_callable=AsyncMock, return_value=flow),\\n            patch(f\\\"{MODULE}.Graph.from_payload\\\", return_value=graph),\\n            patch(f\\\"{MODULE}.logger\\\", _mock_logger()),\\n        ):\\n            result = await get_component_details(\\\"test-flow\\\", \\\"missing-comp\\\")\\n\\n        assert \\\"error\\\" in result\\n        assert \\\"not found\\\" in result[\\\"error\\\"]\\n\\n\\nclass TestGetComponentFieldValue:\\n    \\\"\\\"\\\"Tests for get_component_field_value.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_should_return_field_config(self):\\n        \\\"\\\"\\\"Should return field value and metadata.\\\"\\\"\\\"\\n        flow = _make_flow()\\n        graph = _make_graph()\\n\\n        with (\\n            patch(f\\\"{MODULE}.get_flow_by_id_or_endpoint_name\\\", new_callable=AsyncMock, return_value=flow),\\n            patch(f\\\"{MODULE}.Graph.from_payload\\\", return_value=graph),\\n            patch(f\\\"{MODULE}.logger\\\", _mock_logger()),\\n        ):\\n            result = await get_component_field_value(\\\"test-flow\\\", \\\"comp-1\\\", \\\"input_value\\\")\\n\\n        assert result[\\\"field_name\\\"] == \\\"input_value\\\"\\n        assert result[\\\"value\\\"] == \\\"hello\\\"\\n        assert result[\\\"field_type\\\"] == \\\"str\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_should_return_error_for_missing_field(self):\\n        \\\"\\\"\\\"Should return error with available_fields when field doesn't exist.\\\"\\\"\\\"\\n        flow = _make_flow()\\n        graph = _make_graph()\\n\\n        with (\\n            patch(f\\\"{MODULE}.get_flow_by_id_or_endpoint_name\\\", new_callable=AsyncMock, return_value=flow),\\n            patch(f\\\"{MODULE}.Graph.from_payload\\\", return_value=graph),\\n            patch(f\\\"{MODULE}.logger\\\", _mock_logger()),\\n        ):\\n            result = await get_component_field_value(\\\"test-flow\\\", \\\"comp-1\\\", \\\"nonexistent_field\\\")\\n\\n        assert \\\"error\\\" in result\\n        assert \\\"available_fields\\\" in result\\n\\n\\nclass TestUpdateComponentFieldValue:\\n    \\\"\\\"\\\"Tests for update_component_field_value.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_should_persist_new_value(self):\\n        \\\"\\\"\\\"Should update field in DB and return success=True.\\\"\\\"\\\"\\n        flow = _make_flow()\\n        db_flow = MagicMock()\\n        db_flow.user_id = UUID(USER_ID)\\n        db_flow.data = flow.data.copy()\\n        previous_updated_at = datetime(2024, 1, 1, tzinfo=timezone.utc)\\n        db_flow.updated_at = previous_updated_at\\n\\n        mock_session = AsyncMock()\\n        mock_session.add = MagicMock()\\n        mock_session.get = AsyncMock(return_value=db_flow)\\n        mock_session.commit = AsyncMock()\\n        mock_session.refresh = AsyncMock()\\n\\n        @asynccontextmanager\\n        async def mock_scope():\\n            yield mock_session\\n\\n        with (\\n            patch(f\\\"{MODULE}.get_flow_by_id_or_endpoint_name\\\", new_callable=AsyncMock, return_value=flow),\\n            patch(f\\\"{MODULE}.session_scope\\\", mock_scope),\\n            patch(f\\\"{MODULE}.logger\\\", _mock_logger()),\\n        ):\\n            result = await update_component_field_value(\\n                \\\"test-flow\\\",\\n                \\\"comp-1\\\",\\n                \\\"input_value\\\",\\n                \\\"new_value\\\",\\n                USER_ID,\\n            )\\n\\n        assert result[\\\"success\\\"] is True\\n        assert result[\\\"old_value\\\"] == \\\"hello\\\"\\n        assert result[\\\"new_value\\\"] == \\\"new_value\\\"\\n        assert db_flow.updated_at > previous_updated_at\\n        assert db_flow.updated_at.tzinfo is timezone.utc\\n\\n    @pytest.mark.asyncio\\n    async def test_should_return_error_for_missing_component(self):\\n        \\\"\\\"\\\"Should return success=False when component not found.\\\"\\\"\\\"\\n        flow = _make_flow()\\n\\n        with (\\n            patch(f\\\"{MODULE}.get_flow_by_id_or_endpoint_name\\\", new_callable=AsyncMock, return_value=flow),\\n            patch(f\\\"{MODULE}.logger\\\", _mock_logger()),\\n        ):\\n            result = await update_component_field_value(\\n                \\\"test-flow\\\",\\n                \\\"nonexistent-comp\\\",\\n                \\\"field\\\",\\n                \\\"val\\\",\\n                USER_ID,\\n            )\\n\\n        assert result[\\\"success\\\"] is False\\n        assert \\\"not found\\\" in result[\\\"error\\\"]\\n\\n    @pytest.mark.asyncio\\n    async def test_should_check_user_permission(self):\\n        \\\"\\\"\\\"Should return error when user_id doesn't match flow owner.\\\"\\\"\\\"\\n        flow = _make_flow()\\n        db_flow = MagicMock()\\n        db_flow.user_id = UUID(USER_ID)  # original owner\\n\\n        mock_session = AsyncMock()\\n        mock_session.get = AsyncMock(return_value=db_flow)\\n\\n        @asynccontextmanager\\n        async def mock_scope():\\n            yield mock_session\\n\\n        different_user = str(uuid4())\\n\\n        with (\\n            patch(f\\\"{MODULE}.get_flow_by_id_or_endpoint_name\\\", new_callable=AsyncMock, return_value=flow),\\n            patch(f\\\"{MODULE}.session_scope\\\", mock_scope),\\n            patch(f\\\"{MODULE}.logger\\\", _mock_logger()),\\n        ):\\n            result = await update_component_field_value(\\n                \\\"test-flow\\\",\\n                \\\"comp-1\\\",\\n                \\\"input_value\\\",\\n                \\\"hack\\\",\\n                different_user,\\n            )\\n\\n        assert result[\\\"success\\\"] is False\\n        assert \\\"permission\\\" in result[\\\"error\\\"].lower()\\n\\n    async def test_should_reject_update_when_fresh_database_row_is_locked(self):\\n        \\\"\\\"\\\"The direct MCP DB path must honor a lock acquired after lookup.\\\"\\\"\\\"\\n        flow = _make_flow()\\n        flow.locked = False\\n        db_flow = MagicMock()\\n        db_flow.user_id = UUID(USER_ID)\\n        db_flow.locked = True\\n\\n        mock_session = AsyncMock()\\n        mock_session.get = AsyncMock(return_value=db_flow)\\n\\n        @asynccontextmanager\\n        async def mock_scope():\\n            yield mock_session\\n\\n        with (\\n            patch(f\\\"{MODULE}.get_flow_by_id_or_endpoint_name\\\", new_callable=AsyncMock, return_value=flow),\\n            patch(f\\\"{MODULE}.session_scope\\\", mock_scope),\\n            patch(f\\\"{MODULE}.logger\\\", _mock_logger()),\\n        ):\\n            result = await update_component_field_value(\\n                \\\"test-flow\\\",\\n                \\\"comp-1\\\",\\n                \\\"input_value\\\",\\n                \\\"blocked value\\\",\\n                USER_ID,\\n            )\\n\\n        assert result[\\\"success\\\"] is False\\n        assert result[\\\"error\\\"] == \\\"Flow is locked. Unlock it before making changes.\\\"\\n        mock_session.refresh.assert_awaited_once_with(db_flow, with_for_update=True)\\n        mock_session.commit.assert_not_awaited()\\n\\n\\nclass TestListComponentFields:\\n    \\\"\\\"\\\"Tests for list_component_fields.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_should_return_all_fields(self):\\n        \\\"\\\"\\\"Should return fields_info with value, type, required, etc.\\\"\\\"\\\"\\n        flow = _make_flow()\\n        graph = _make_graph()\\n\\n        with (\\n            patch(f\\\"{MODULE}.get_flow_by_id_or_endpoint_name\\\", new_callable=AsyncMock, return_value=flow),\\n            patch(f\\\"{MODULE}.Graph.from_payload\\\", return_value=graph),\\n            patch(f\\\"{MODULE}.logger\\\", _mock_logger()),\\n        ):\\n            result = await list_component_fields(\\\"test-flow\\\", \\\"comp-1\\\")\\n\\n        assert \\\"fields\\\" in result\\n        assert result[\\\"field_count\\\"] == 2\\n        assert \\\"input_value\\\" in result[\\\"fields\\\"]\\n        assert \\\"sender_name\\\" in result[\\\"fields\\\"]\\n        assert result[\\\"fields\\\"][\\\"input_value\\\"][\\\"value\\\"] == \\\"hello\\\"\\n        assert result[\\\"fields\\\"][\\\"sender_name\\\"][\\\"advanced\\\"] is True\\n\\n    @pytest.mark.asyncio\\n    async def test_should_return_error_when_flow_not_found(self):\\n        \\\"\\\"\\\"Should return error dict for nonexistent flow.\\\"\\\"\\\"\\n        with (\\n            patch(f\\\"{MODULE}.get_flow_by_id_or_endpoint_name\\\", new_callable=AsyncMock, return_value=None),\\n            patch(f\\\"{MODULE}.logger\\\", _mock_logger()),\\n        ):\\n            result = await list_component_fields(\\\"missing-flow\\\", \\\"comp-1\\\")\\n\\n        assert \\\"error\\\" in result\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/agentic/utils/test_flow_graph.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"37e20a16230865737d4425c393d6063346702a83dee8c46cfc2b22f64837134e\",\"content\":\"\\\"\\\"\\\"Tests for flow graph visualization utilities.\\n\\nTests get_flow_graph_representations, get_flow_ascii_graph,\\nget_flow_text_repr, and get_flow_graph_summary.\\n\\\"\\\"\\\"\\n\\nfrom types import SimpleNamespace\\nfrom unittest.mock import AsyncMock, MagicMock, patch\\nfrom uuid import UUID, uuid4\\n\\nimport pytest\\nfrom langflow.agentic.utils.flow_graph import (\\n    get_flow_ascii_graph,\\n    get_flow_graph_representations,\\n    get_flow_graph_summary,\\n    get_flow_text_repr,\\n)\\nfrom lfx.interface.components import component_cache\\n\\nMODULE = \\\"langflow.agentic.utils.flow_graph\\\"\\n\\nFLOW_ID = str(uuid4())\\n\\n\\ndef _mock_logger():\\n    \\\"\\\"\\\"Create a mock async logger.\\\"\\\"\\\"\\n    mock = MagicMock()\\n    mock.aerror = AsyncMock()\\n    mock.ainfo = AsyncMock()\\n    mock.awarning = AsyncMock()\\n    return mock\\n\\n\\ndef _make_flow(*, has_data=True, name=\\\"TestFlow\\\"):\\n    \\\"\\\"\\\"Create a mock flow object.\\\"\\\"\\\"\\n    flow = MagicMock()\\n    flow.id = UUID(FLOW_ID)\\n    flow.name = name\\n    flow.tags = [\\\"test\\\"]\\n    flow.description = \\\"A test flow\\\"\\n    flow.data = {\\\"nodes\\\": [], \\\"edges\\\": []} if has_data else None\\n    return flow\\n\\n\\ndef _make_graph(vertex_ids=None, edge_pairs=None):\\n    \\\"\\\"\\\"Create a mock graph with vertices and edges.\\\"\\\"\\\"\\n    graph = MagicMock()\\n\\n    vertices = []\\n    for vid in [\\\"v1\\\", \\\"v2\\\"] if vertex_ids is None else vertex_ids:\\n        v = MagicMock()\\n        v.id = vid\\n        vertices.append(v)\\n    graph.vertices = vertices\\n\\n    edges = []\\n    for src, tgt in [(\\\"v1\\\", \\\"v2\\\")] if edge_pairs is None else edge_pairs:\\n        e = MagicMock()\\n        e.source_id = src\\n        e.target_id = tgt\\n        edges.append(e)\\n    graph.edges = edges\\n\\n    graph.__repr__ = MagicMock(return_value=\\\"Graph(vertices=2, edges=1)\\\")  # type: ignore[method-assign]\\n    return graph\\n\\n\\n@pytest.mark.asyncio\\nasync def test_get_flow_graph_summary_blocks_custom_components(monkeypatch):\\n    blocked_flow = SimpleNamespace(\\n        id=\\\"flow-1\\\",\\n        name=\\\"Blocked Flow\\\",\\n        tags=[],\\n        description=\\\"Contains blocked custom code\\\",\\n        data={\\n            \\\"nodes\\\": [\\n                {\\n                    \\\"id\\\": \\\"node-1\\\",\\n                    \\\"data\\\": {\\n                        \\\"id\\\": \\\"node-1\\\",\\n                        \\\"type\\\": \\\"TotallyCustom\\\",\\n                        \\\"node\\\": {\\n                            \\\"display_name\\\": \\\"Blocked Node\\\",\\n                            \\\"template\\\": {\\n                                \\\"code\\\": {\\\"value\\\": \\\"print('blocked')\\\"},\\n                            },\\n                        },\\n                    },\\n                }\\n            ],\\n            \\\"edges\\\": [],\\n        },\\n    )\\n\\n    async def _get_flow(*_args, **_kwargs):\\n        return blocked_flow\\n\\n    monkeypatch.setattr(\\\"langflow.agentic.utils.flow_graph.get_flow_by_id_or_endpoint_name\\\", _get_flow)\\n    monkeypatch.setattr(\\n        \\\"lfx.services.deps.get_settings_service\\\",\\n        lambda: SimpleNamespace(settings=SimpleNamespace(allow_custom_components=False)),\\n    )\\n    monkeypatch.setattr(component_cache, \\\"type_to_current_hash\\\", {\\\"ChatInput\\\": \\\"known-hash\\\"})\\n    monkeypatch.setattr(component_cache, \\\"all_types_dict\\\", None)\\n\\n    result = await get_flow_graph_summary(\\\"flow-1\\\")\\n\\n    assert \\\"custom components are not allowed\\\" in result[\\\"error\\\"]\\n\\n\\nclass TestGetFlowGraphRepresentations:\\n    \\\"\\\"\\\"Tests for get_flow_graph_representations.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_should_return_all_data(self):\\n        \\\"\\\"\\\"Should return ascii_graph, text_repr, vertex/edge counts.\\\"\\\"\\\"\\n        flow = _make_flow()\\n        graph = _make_graph()\\n\\n        with (\\n            patch(f\\\"{MODULE}.get_flow_by_id_or_endpoint_name\\\", new_callable=AsyncMock, return_value=flow),\\n            patch(f\\\"{MODULE}.Graph.from_payload\\\", return_value=graph),\\n            patch(f\\\"{MODULE}.draw_graph\\\", return_value=\\\"[v1] -> [v2]\\\"),\\n            patch(f\\\"{MODULE}.logger\\\", _mock_logger()),\\n        ):\\n            result = await get_flow_graph_representations(\\\"test-flow\\\")\\n\\n        assert result[\\\"flow_id\\\"] == FLOW_ID\\n        assert result[\\\"flow_name\\\"] == \\\"TestFlow\\\"\\n        assert result[\\\"ascii_graph\\\"] == \\\"[v1] -> [v2]\\\"\\n        assert result[\\\"vertex_count\\\"] == 2\\n        assert result[\\\"edge_count\\\"] == 1\\n        assert result[\\\"tags\\\"] == [\\\"test\\\"]\\n\\n    @pytest.mark.asyncio\\n    async def test_should_return_error_when_flow_not_found(self):\\n        \\\"\\\"\\\"Should return error dict for nonexistent flow.\\\"\\\"\\\"\\n        with (\\n            patch(f\\\"{MODULE}.get_flow_by_id_or_endpoint_name\\\", new_callable=AsyncMock, return_value=None),\\n            patch(f\\\"{MODULE}.logger\\\", _mock_logger()),\\n        ):\\n            result = await get_flow_graph_representations(\\\"missing-flow\\\")\\n\\n        assert \\\"error\\\" in result\\n        assert \\\"not found\\\" in result[\\\"error\\\"]\\n\\n    @pytest.mark.asyncio\\n    async def test_should_return_error_when_no_data(self):\\n        \\\"\\\"\\\"Should return error for flow with no data.\\\"\\\"\\\"\\n        flow = _make_flow(has_data=False)\\n\\n        with (\\n            patch(f\\\"{MODULE}.get_flow_by_id_or_endpoint_name\\\", new_callable=AsyncMock, return_value=flow),\\n            patch(f\\\"{MODULE}.logger\\\", _mock_logger()),\\n        ):\\n            result = await get_flow_graph_representations(\\\"test-flow\\\")\\n\\n        assert \\\"error\\\" in result\\n        assert \\\"no data\\\" in result[\\\"error\\\"]\\n\\n    @pytest.mark.asyncio\\n    async def test_should_handle_draw_graph_failure(self):\\n        \\\"\\\"\\\"Should return fallback message when draw_graph raises.\\\"\\\"\\\"\\n        flow = _make_flow()\\n        graph = _make_graph()\\n\\n        with (\\n            patch(f\\\"{MODULE}.get_flow_by_id_or_endpoint_name\\\", new_callable=AsyncMock, return_value=flow),\\n            patch(f\\\"{MODULE}.Graph.from_payload\\\", return_value=graph),\\n            patch(f\\\"{MODULE}.draw_graph\\\", side_effect=RuntimeError(\\\"too complex\\\")),\\n            patch(f\\\"{MODULE}.logger\\\", _mock_logger()),\\n        ):\\n            result = await get_flow_graph_representations(\\\"test-flow\\\")\\n\\n        assert \\\"failed\\\" in result[\\\"ascii_graph\\\"].lower()\\n\\n    @pytest.mark.asyncio\\n    async def test_should_return_none_ascii_when_no_vertices(self):\\n        \\\"\\\"\\\"Should return None for ascii_graph when graph has no vertices.\\\"\\\"\\\"\\n        flow = _make_flow()\\n        graph = _make_graph(vertex_ids=[], edge_pairs=[])\\n\\n        with (\\n            patch(f\\\"{MODULE}.get_flow_by_id_or_endpoint_name\\\", new_callable=AsyncMock, return_value=flow),\\n            patch(f\\\"{MODULE}.Graph.from_payload\\\", return_value=graph),\\n            patch(f\\\"{MODULE}.logger\\\", _mock_logger()),\\n        ):\\n            result = await get_flow_graph_representations(\\\"test-flow\\\")\\n\\n        assert result[\\\"ascii_graph\\\"] is None\\n\\n\\nclass TestGetFlowAsciiGraph:\\n    \\\"\\\"\\\"Tests for get_flow_ascii_graph.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_should_return_ascii_string(self):\\n        \\\"\\\"\\\"Should return the ASCII graph string.\\\"\\\"\\\"\\n        flow = _make_flow()\\n        graph = _make_graph()\\n\\n        with (\\n            patch(f\\\"{MODULE}.get_flow_by_id_or_endpoint_name\\\", new_callable=AsyncMock, return_value=flow),\\n            patch(f\\\"{MODULE}.Graph.from_payload\\\", return_value=graph),\\n            patch(f\\\"{MODULE}.draw_graph\\\", return_value=\\\"[v1] -> [v2]\\\"),\\n            patch(f\\\"{MODULE}.logger\\\", _mock_logger()),\\n        ):\\n            result = await get_flow_ascii_graph(\\\"test-flow\\\")\\n\\n        assert result == \\\"[v1] -> [v2]\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_should_return_error_string(self):\\n        \\\"\\\"\\\"Should return 'Error: ...' for nonexistent flow.\\\"\\\"\\\"\\n        with (\\n            patch(f\\\"{MODULE}.get_flow_by_id_or_endpoint_name\\\", new_callable=AsyncMock, return_value=None),\\n            patch(f\\\"{MODULE}.logger\\\", _mock_logger()),\\n        ):\\n            result = await get_flow_ascii_graph(\\\"missing-flow\\\")\\n\\n        assert result.startswith(\\\"Error:\\\")\\n\\n\\nclass TestGetFlowTextRepr:\\n    \\\"\\\"\\\"Tests for get_flow_text_repr.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_should_return_repr_string(self):\\n        \\\"\\\"\\\"Should return the graph's text representation.\\\"\\\"\\\"\\n        flow = _make_flow()\\n        graph = _make_graph()\\n\\n        with (\\n            patch(f\\\"{MODULE}.get_flow_by_id_or_endpoint_name\\\", new_callable=AsyncMock, return_value=flow),\\n            patch(f\\\"{MODULE}.Graph.from_payload\\\", return_value=graph),\\n            patch(f\\\"{MODULE}.draw_graph\\\", return_value=\\\"ascii\\\"),\\n            patch(f\\\"{MODULE}.logger\\\", _mock_logger()),\\n        ):\\n            result = await get_flow_text_repr(\\\"test-flow\\\")\\n\\n        assert isinstance(result, str)\\n\\n\\nclass TestGetFlowGraphSummary:\\n    \\\"\\\"\\\"Tests for get_flow_graph_summary.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_should_return_metadata(self):\\n        \\\"\\\"\\\"Should return flow metadata with counts, vertices, edges.\\\"\\\"\\\"\\n        flow = _make_flow()\\n        graph = _make_graph(vertex_ids=[\\\"a\\\", \\\"b\\\", \\\"c\\\"], edge_pairs=[(\\\"a\\\", \\\"b\\\"), (\\\"b\\\", \\\"c\\\")])\\n\\n        with (\\n            patch(f\\\"{MODULE}.get_flow_by_id_or_endpoint_name\\\", new_callable=AsyncMock, return_value=flow),\\n            patch(f\\\"{MODULE}.Graph.from_payload\\\", return_value=graph),\\n            patch(f\\\"{MODULE}.logger\\\", _mock_logger()),\\n        ):\\n            result = await get_flow_graph_summary(\\\"test-flow\\\")\\n\\n        assert result[\\\"flow_id\\\"] == FLOW_ID\\n        assert result[\\\"vertex_count\\\"] == 3\\n        assert result[\\\"edge_count\\\"] == 2\\n        assert result[\\\"vertices\\\"] == [\\\"a\\\", \\\"b\\\", \\\"c\\\"]\\n        assert (\\\"a\\\", \\\"b\\\") in result[\\\"edges\\\"]\\n\\n    @pytest.mark.asyncio\\n    async def test_should_return_error_when_not_found(self):\\n        \\\"\\\"\\\"Should return error dict for nonexistent flow.\\\"\\\"\\\"\\n        with (\\n            patch(f\\\"{MODULE}.get_flow_by_id_or_endpoint_name\\\", new_callable=AsyncMock, return_value=None),\\n            patch(f\\\"{MODULE}.logger\\\", _mock_logger()),\\n        ):\\n            result = await get_flow_graph_summary(\\\"missing-flow\\\")\\n\\n        assert \\\"error\\\" in result\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/alembic/test_flow_type_migration.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"7bcab15dfa3dad1a935769154e988a78e08fc43b08fe473301d8ab6d5e561cc1\",\"content\":\"\\\"\\\"\\\"Structure tests for the flow_type / a2a columns migration (9f1d1d602aa3).\\n\\nCovers the additive flow.flow_type, flow.a2a_enabled and flow.a2a_card_overrides\\ncolumns: forward to head, then rollback to the prior revision. Runs on sqlite\\nand (when configured) postgres.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom alembic import command\\nfrom sqlalchemy import create_engine, inspect\\n\\nfrom .test_migration_execution import _engine_url, _make_alembic_cfg, db_url  # noqa: F401\\n\\n_PRIOR_REVISION = \\\"a1f4c9d27b30\\\"  # pragma: allowlist secret\\n_A2A_COLUMNS = {\\\"flow_type\\\", \\\"a2a_enabled\\\", \\\"a2a_card_overrides\\\"}\\n\\n\\ndef _flow_columns(db_url: str) -> set[str]:  # noqa: F811\\n    engine = create_engine(_engine_url(db_url))\\n    try:\\n        with engine.connect() as connection:\\n            return {c[\\\"name\\\"] for c in inspect(connection).get_columns(\\\"flow\\\")}\\n    finally:\\n        engine.dispose()\\n\\n\\ndef test_flow_has_flow_type_and_a2a_columns(db_url):  # noqa: F811\\n    alembic_cfg = _make_alembic_cfg(db_url)\\n    command.upgrade(alembic_cfg, \\\"head\\\")\\n\\n    assert _flow_columns(db_url) >= _A2A_COLUMNS\\n\\n\\ndef test_flow_type_columns_dropped_on_downgrade(db_url):  # noqa: F811\\n    alembic_cfg = _make_alembic_cfg(db_url)\\n    command.upgrade(alembic_cfg, \\\"head\\\")\\n    command.downgrade(alembic_cfg, _PRIOR_REVISION)\\n\\n    assert _A2A_COLUMNS.isdisjoint(_flow_columns(db_url))\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/alembic/test_flow_version_check_constraint_naming.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f0f8f46bb6795586e27b6c89b303c0184135d77c133f164252ac21ff4071d970\",\"content\":\"\\\"\\\"\\\"Constraint-name parity for the ``flow_version`` ``version_number >= 1`` CHECK.\\n\\nThe model marks the name with ``conv()`` and the migration with ``op.f()`` so both create paths\\nrender ``ck_flow_version_version_number_positive`` under the ``ck_%(table_name)s_%(constraint_name)s``\\nconvention that ``langflow/alembic/env.py`` installs. Databases created before that fix carry a\\nlegacy name and must be left untouched.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport importlib\\n\\nimport pytest\\nimport sqlalchemy as sa\\nfrom alembic.migration import MigrationContext\\nfrom alembic.operations import Operations\\nfrom langflow.services.database.models.flow_version.model import VERSION_NUMBER_CHECK_NAME, FlowVersion\\n\\nfrom .test_migration_execution import _engine_url, db_url  # noqa: F401\\n\\n_MIGRATION = importlib.import_module(\\\"langflow.alembic.versions.7d327cfafab6_add_flow_history_table\\\")\\nTABLE_NAME = \\\"flow_version\\\"\\n# Mirrors NAMING_CONVENTION in ``langflow/alembic/env.py`` (env.py cannot be imported: it runs migrations on import).\\n_NAMING_CONVENTION = {\\n    \\\"ix\\\": \\\"ix_%(column_0_label)s\\\",\\n    \\\"uq\\\": \\\"uq_%(table_name)s_%(column_0_name)s\\\",\\n    \\\"ck\\\": \\\"ck_%(table_name)s_%(constraint_name)s\\\",\\n    \\\"fk\\\": \\\"fk_%(table_name)s_%(column_0_name)s_%(referred_table_name)s\\\",\\n    \\\"pk\\\": \\\"pk_%(table_name)s\\\",\\n}\\n# Fresh installs created the table via create_all before env.py installed the convention.\\n_LEGACY_PLAIN_NAME = \\\"check_version_number_positive\\\"\\n# Upgraded installs created it via op.create_table, which prefixed the plain string.\\n_LEGACY_DOUBLED_NAME = f\\\"ck_{TABLE_NAME}_{_LEGACY_PLAIN_NAME}\\\"\\n\\n\\ndef _convention_operations(connection: sa.Connection) -> Operations:\\n    \\\"\\\"\\\"Build Operations the way env.py does: create_table inherits the naming convention.\\\"\\\"\\\"\\n    return Operations(\\n        MigrationContext.configure(\\n            connection,\\n            opts={\\\"target_metadata\\\": sa.MetaData(naming_convention=_NAMING_CONVENTION)},\\n        )\\n    )\\n\\n\\ndef _scratch_metadata(*, under_convention: bool) -> sa.MetaData:\\n    \\\"\\\"\\\"Return a MetaData holding stub ``user`` and ``flow`` tables so flow_version's foreign keys resolve.\\\"\\\"\\\"\\n    metadata = sa.MetaData(naming_convention=_NAMING_CONVENTION) if under_convention else sa.MetaData()\\n    sa.Table(\\\"user\\\", metadata, sa.Column(\\\"id\\\", sa.Uuid(), primary_key=True))\\n    sa.Table(\\\"flow\\\", metadata, sa.Column(\\\"id\\\", sa.Uuid(), primary_key=True))\\n    return metadata\\n\\n\\ndef _pre_fix_flow_version_table(metadata: sa.MetaData) -> sa.Table:\\n    \\\"\\\"\\\"Rebuild flow_version as the pre-fix model and migration declared it: a plain-string CHECK name.\\\"\\\"\\\"\\n    return sa.Table(\\n        TABLE_NAME,\\n        metadata,\\n        sa.Column(\\\"id\\\", sa.Uuid(), primary_key=True),\\n        sa.Column(\\\"flow_id\\\", sa.Uuid(), sa.ForeignKey(\\\"flow.id\\\", ondelete=\\\"CASCADE\\\"), nullable=False),\\n        sa.Column(\\\"user_id\\\", sa.Uuid(), sa.ForeignKey(\\\"user.id\\\", ondelete=\\\"SET NULL\\\"), nullable=True),\\n        sa.Column(\\\"data\\\", sa.JSON(), nullable=True),\\n        sa.Column(\\\"version_number\\\", sa.Integer(), nullable=False),\\n        sa.Column(\\\"description\\\", sa.String(), nullable=True),\\n        sa.Column(\\\"created_at\\\", sa.DateTime(timezone=True), server_default=sa.func.now(), nullable=False),\\n        sa.UniqueConstraint(\\\"flow_id\\\", \\\"version_number\\\", name=\\\"unique_flow_version_number\\\"),\\n        sa.CheckConstraint(\\\"version_number >= 1\\\", name=_LEGACY_PLAIN_NAME),\\n    )\\n\\n\\ndef _reflected_check_names(connection: sa.Connection) -> set[str]:\\n    return {constraint[\\\"name\\\"] for constraint in sa.inspect(connection).get_check_constraints(TABLE_NAME)}\\n\\n\\n@pytest.mark.parametrize(\\\"create_path\\\", [\\\"migration\\\", \\\"model_without_convention\\\", \\\"model_under_convention\\\"])\\ndef test_flow_version_check_name_is_identical_across_create_paths(db_url, create_path, monkeypatch):  # noqa: F811\\n    \\\"\\\"\\\"Every way the table gets created must emit the one canonical CHECK name.\\\"\\\"\\\"\\n    engine = sa.create_engine(_engine_url(db_url))\\n    try:\\n        if create_path == \\\"migration\\\":\\n            _scratch_metadata(under_convention=False).create_all(engine)\\n            with engine.begin() as connection:\\n                monkeypatch.setattr(_MIGRATION, \\\"op\\\", _convention_operations(connection))\\n                _MIGRATION.upgrade()\\n        else:\\n            metadata = _scratch_metadata(under_convention=create_path == \\\"model_under_convention\\\")\\n            FlowVersion.__table__.to_metadata(metadata)\\n            metadata.create_all(engine)\\n\\n        with engine.connect() as connection:\\n            assert _reflected_check_names(connection) == {VERSION_NUMBER_CHECK_NAME}\\n    finally:\\n        engine.dispose()\\n\\n\\n@pytest.mark.parametrize(\\\"legacy_name\\\", [_LEGACY_PLAIN_NAME, _LEGACY_DOUBLED_NAME])\\ndef test_migration_leaves_legacy_check_names_untouched(db_url, legacy_name, monkeypatch):  # noqa: F811\\n    \\\"\\\"\\\"Existing databases keep whichever legacy name they were created with; nothing renames or duplicates it.\\\"\\\"\\\"\\n    engine = sa.create_engine(_engine_url(db_url))\\n    try:\\n        metadata = _scratch_metadata(under_convention=legacy_name == _LEGACY_DOUBLED_NAME)\\n        _pre_fix_flow_version_table(metadata)\\n        metadata.create_all(engine)\\n\\n        with engine.begin() as connection:\\n            assert _reflected_check_names(connection) == {legacy_name}\\n\\n            monkeypatch.setattr(_MIGRATION, \\\"op\\\", _convention_operations(connection))\\n            _MIGRATION.upgrade()\\n            _MIGRATION.upgrade()\\n\\n            assert _reflected_check_names(connection) == {legacy_name}\\n    finally:\\n        engine.dispose()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/alembic/test_flow_workspace_sync_migration.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"ffce6e665cf6743171813690dd5806a380961b23a0547cec821cdbec843325aa\",\"content\":\"\\\"\\\"\\\"Data-repair contract for project-scoped flow workspace ids.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport importlib\\nfrom uuid import uuid4\\n\\nimport sqlalchemy as sa\\nfrom alembic.migration import MigrationContext\\nfrom alembic.operations import Operations\\n\\n_MIGRATION = importlib.import_module(\\\"langflow.alembic.versions.b7d5f9a3c2e4_sync_flow_workspace_from_project\\\")\\n\\n\\ndef test_workspace_sync_uses_folder_for_project_scoped_rows_and_preserves_unscoped_rows(monkeypatch):\\n    engine = sa.create_engine(\\\"sqlite://\\\")\\n    metadata = sa.MetaData()\\n    folder = sa.Table(\\n        \\\"folder\\\",\\n        metadata,\\n        sa.Column(\\\"id\\\", sa.Uuid(), primary_key=True),\\n        sa.Column(\\\"workspace_id\\\", sa.Uuid(), nullable=True),\\n    )\\n    flow = sa.Table(\\n        \\\"flow\\\",\\n        metadata,\\n        sa.Column(\\\"id\\\", sa.Uuid(), primary_key=True),\\n        sa.Column(\\\"folder_id\\\", sa.Uuid(), nullable=True),\\n        sa.Column(\\\"workspace_id\\\", sa.Uuid(), nullable=True),\\n    )\\n    metadata.create_all(engine)\\n    project_id = uuid4()\\n    canonical_workspace = uuid4()\\n    spoofed_workspace = uuid4()\\n    project_flow_id = uuid4()\\n    unscoped_flow_id = uuid4()\\n\\n    with engine.begin() as connection:\\n        connection.execute(folder.insert(), {\\\"id\\\": project_id, \\\"workspace_id\\\": canonical_workspace})\\n        connection.execute(\\n            flow.insert(),\\n            [\\n                {\\n                    \\\"id\\\": project_flow_id,\\n                    \\\"folder_id\\\": project_id,\\n                    \\\"workspace_id\\\": spoofed_workspace,\\n                },\\n                {\\n                    \\\"id\\\": unscoped_flow_id,\\n                    \\\"folder_id\\\": None,\\n                    \\\"workspace_id\\\": spoofed_workspace,\\n                },\\n            ],\\n        )\\n        monkeypatch.setattr(_MIGRATION, \\\"op\\\", Operations(MigrationContext.configure(connection)))\\n\\n        _MIGRATION.upgrade()\\n\\n        rows = dict(connection.execute(sa.select(flow.c.id, flow.c.workspace_id)).all())\\n        assert rows[project_flow_id] == canonical_workspace\\n        assert rows[unscoped_flow_id] == spoofed_workspace\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/api/test_build_flow_span.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1f1453c277fc91879a3c2f9012707aab71ec8204ed6b539ac9ffed47e12e3819\",\"content\":\"\\\"\\\"\\\"The /build driver's application span, exercised through the real HTTP route.\\n\\nNote on naming: this drives POST /api/v1/build, which the canvas no longer calls (the frontend\\nmoved to POST /api/v2/workflows). The driver underneath is shared, so this still covers it for\\nevery surface that reaches it, but the protocol here is v1.build rather than playground. The\\nplayground label is asserted on the v2 stream, where the IDE actually is.\\n\\nThe build driver walks the vertices itself and never enters ``Graph.arun`` / ``async_start`` /\\n``process``, so it did not inherit the flow span those three carry. That made the busiest\\nsurfaces in the product \u2014 the v2 stream the canvas uses, v2 background, voice \u2014 the ones the\\noperator's APM could not see. (v2 sync goes through ``arun`` and always had one.)\\n\\nThese tests drive the actual route so both halves are covered: the span the build loop opens,\\nand the protocol the route binds around it.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport json\\n\\nimport pytest\\nfrom lfx.observability import APPLICATION_TRACER_NAME\\n\\nfrom tests.unit.build_utils import build_flow, consume_and_assert_stream, create_flow, get_build_events\\n\\npytestmark = pytest.mark.usefixtures(\\\"client\\\")\\n\\n\\n@pytest.fixture(scope=\\\"module\\\")\\ndef span_exporter():\\n    \\\"\\\"\\\"Install a provider for this module and hand back its exporter.\\n\\n    The sibling OTel tests run their provider in a subprocess because it is process-global.\\n    That is not available here: the point of these tests is the real HTTP route, which needs\\n    the app, the DB and the auth fixtures, so the provider has to go into the test process.\\n\\n    Two consequences are handled rather than ignored. ``set_tracer_provider`` is\\n    first-write-wins, so the assert is what stops this file from passing vacuously if anything\\n    else in the worker installs one first. And the provider cannot be uninstalled, so the\\n    teardown shuts it down instead \u2014 otherwise every later test in this worker that runs a\\n    flow would keep appending spans to an exporter nobody reads.\\n    \\\"\\\"\\\"\\n    from opentelemetry import trace\\n    from opentelemetry.sdk.trace import TracerProvider\\n    from opentelemetry.sdk.trace.export import SimpleSpanProcessor\\n    from opentelemetry.sdk.trace.export.in_memory_span_exporter import InMemorySpanExporter\\n\\n    exporter = InMemorySpanExporter()\\n    provider = TracerProvider()\\n    provider.add_span_processor(SimpleSpanProcessor(exporter))\\n    trace.set_tracer_provider(provider)\\n    assert trace.get_tracer_provider() is provider, (\\n        \\\"another test installed a tracer provider first; these assertions would be vacuous\\\"\\n    )\\n    yield exporter\\n    provider.shutdown()\\n    exporter.clear()\\n\\n\\ndef _flow_spans(exporter):\\n    return [span for span in exporter.get_finished_spans() if span.name == \\\"flow.execute\\\"]\\n\\n\\nasync def _run_a_v1_build(client, flow_data, headers) -> None:\\n    flow_id = await create_flow(client, flow_data, headers)\\n    build_response = await build_flow(client, flow_id, headers)\\n    job_id = build_response[\\\"job_id\\\"]\\n    events_response = await get_build_events(client, job_id, headers)\\n    await consume_and_assert_stream(events_response, job_id)\\n\\n\\nasync def test_the_v1_build_path_emits_exactly_one_flow_span(\\n    client, json_memory_chatbot_no_llm, logged_in_headers, span_exporter\\n):\\n    span_exporter.clear()\\n\\n    await _run_a_v1_build(client, json_memory_chatbot_no_llm, logged_in_headers)\\n\\n    spans = _flow_spans(span_exporter)\\n    assert len(spans) == 1, f\\\"expected one flow span for one build, got {len(spans)}\\\"\\n    span = spans[0]\\n    assert span.instrumentation_scope.name == APPLICATION_TRACER_NAME\\n    assert span.attributes[\\\"flow_id\\\"]\\n    assert span.attributes[\\\"run_id\\\"]\\n    assert span.attributes[\\\"status\\\"] == \\\"ok\\\"\\n\\n\\nasync def test_the_build_route_labels_the_run_as_v1_build(\\n    client, json_memory_chatbot_no_llm, logged_in_headers, span_exporter\\n):\\n    \\\"\\\"\\\"The protocol is bound by the route, not the driver, so only a real request proves it.\\\"\\\"\\\"\\n    span_exporter.clear()\\n\\n    await _run_a_v1_build(client, json_memory_chatbot_no_llm, logged_in_headers)\\n\\n    spans = _flow_spans(span_exporter)\\n    assert len(spans) == 1\\n    assert spans[0].attributes[\\\"protocol\\\"] == \\\"v1.build\\\"\\n\\n\\nasync def test_no_component_spans_reach_the_operators_apm(\\n    client, json_memory_chatbot_no_llm, logged_in_headers, span_exporter\\n):\\n    \\\"\\\"\\\"One unit of work per run. A per-component span here would also carry component payloads.\\\"\\\"\\\"\\n    span_exporter.clear()\\n\\n    await _run_a_v1_build(client, json_memory_chatbot_no_llm, logged_in_headers)\\n\\n    application_spans = [\\n        span\\n        for span in span_exporter.get_finished_spans()\\n        if span.instrumentation_scope.name == APPLICATION_TRACER_NAME\\n    ]\\n    assert [span.name for span in application_spans] == [\\\"flow.execute\\\"]\\n\\n\\n# The build driver catches a component failure, turns it into an error output and stops walking,\\n# rather than raising. So the span sees a clean exit unless the driver tells it, and a failed run\\n# would report \\\"ok\\\" while the same flow through Graph.arun reports \\\"error\\\".\\nSENTINEL = \\\"component-detail-that-must-not-be-exported\\\"\\n\\nFAILING_COMPONENT_CODE = f\\\"\\\"\\\"\\nfrom lfx.custom import Component\\nfrom lfx.io import HandleInput, Output, TabInput\\nfrom lfx.schema import Message\\n\\n\\nclass TypeConverterComponent(Component):\\n    display_name = \\\"Type Convert\\\"\\n    description = \\\"converts\\\"\\n    name = \\\"TypeConverterComponent\\\"\\n    inputs = [\\n        HandleInput(name=\\\"input_data\\\", display_name=\\\"Input\\\", input_types=[\\\"Message\\\", \\\"Data\\\", \\\"DataFrame\\\"]),\\n        TabInput(name=\\\"output_type\\\", display_name=\\\"Output Type\\\", options=[\\\"Message\\\"], value=\\\"Message\\\"),\\n    ]\\n    outputs = [Output(display_name=\\\"Message Output\\\", name=\\\"message_output\\\", method=\\\"convert_to_message\\\")]\\n\\n    def convert_to_message(self) -> Message:\\n        raise RuntimeError(\\\"{SENTINEL}\\\")\\n\\\"\\\"\\\"\\n\\n\\ndef _flow_with_a_failing_component(flow_data: str) -> str:\\n    payload = json.loads(flow_data)\\n    for node in payload[\\\"data\\\"][\\\"nodes\\\"]:\\n        if node[\\\"id\\\"] == \\\"TypeConverterComponent-koSIz\\\":\\n            node[\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"code\\\"][\\\"value\\\"] = FAILING_COMPONENT_CODE\\n    return json.dumps(payload)\\n\\n\\nasync def test_a_failed_build_is_not_reported_as_a_successful_run(\\n    client, json_memory_chatbot_no_llm, logged_in_headers, span_exporter\\n):\\n    span_exporter.clear()\\n\\n    flow_id = await create_flow(client, _flow_with_a_failing_component(json_memory_chatbot_no_llm), logged_in_headers)\\n    build_response = await build_flow(client, flow_id, logged_in_headers)\\n    events = await get_build_events(client, build_response[\\\"job_id\\\"], logged_in_headers)\\n    body = \\\"\\\".join([line async for line in events.aiter_lines()])\\n    assert SENTINEL in body, \\\"the component was supposed to fail this build\\\"\\n\\n    spans = _flow_spans(span_exporter)\\n    assert len(spans) == 1\\n    span = spans[0]\\n    assert span.attributes[\\\"status\\\"] == \\\"error\\\"\\n    # The driver wraps the component's own exception, so this is the type an operator sees.\\n    assert span.attributes[\\\"error.type\\\"] == \\\"ComponentBuildError\\\"\\n    # The wrapped message embeds component output, so only the type may reach the APM.\\n    assert SENTINEL not in json.dumps(dict(span.attributes))\\n\\n\\nasync def test_a_declared_client_reaches_the_span(client, json_memory_chatbot_no_llm, logged_in_headers, span_exporter):\\n    span_exporter.clear()\\n    flow_id = await create_flow(client, json_memory_chatbot_no_llm, logged_in_headers)\\n    build_response = await build_flow(client, flow_id, {**logged_in_headers, \\\"x-langflow-client\\\": \\\"playground\\\"})\\n    events = await get_build_events(client, build_response[\\\"job_id\\\"], logged_in_headers)\\n    await consume_and_assert_stream(events, build_response[\\\"job_id\\\"])\\n\\n    spans = _flow_spans(span_exporter)\\n    assert len(spans) == 1\\n    assert spans[0].attributes[\\\"client\\\"] == \\\"playground\\\"\\n\\n\\nasync def test_an_unknown_client_is_dropped_rather_than_recorded(\\n    client, json_memory_chatbot_no_llm, logged_in_headers, span_exporter\\n):\\n    \\\"\\\"\\\"A caller must not be able to mint span attribute values.\\\"\\\"\\\"\\n    span_exporter.clear()\\n    flow_id = await create_flow(client, json_memory_chatbot_no_llm, logged_in_headers)\\n    build_response = await build_flow(client, flow_id, {**logged_in_headers, \\\"x-langflow-client\\\": \\\"not-a-real-client\\\"})\\n    events = await get_build_events(client, build_response[\\\"job_id\\\"], logged_in_headers)\\n    await consume_and_assert_stream(events, build_response[\\\"job_id\\\"])\\n\\n    spans = _flow_spans(span_exporter)\\n    assert len(spans) == 1\\n    assert \\\"client\\\" not in spans[0].attributes\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/api/test_build_source_flow_provenance.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"5b25310898f8a12b01fc2cc8864e32b83b74e725a96834fcc0b9d70017505386\",\"content\":\"\\\"\\\"\\\"Tests for server-provenanced public-flow storage scopes.\\\"\\\"\\\"\\n\\nimport asyncio\\nimport uuid\\nfrom contextlib import asynccontextmanager\\nfrom types import SimpleNamespace\\nfrom unittest.mock import AsyncMock, MagicMock\\n\\nimport pytest\\nfrom fastapi import BackgroundTasks, HTTPException\\nfrom langflow.api.v1.schemas import FlowDataRequest\\nfrom lfx.events.event_manager import create_default_event_manager\\nfrom lfx.graph.vertex.base import Vertex\\nfrom lfx.utils.file_path_security import LocalFileAccessError\\n\\n\\n@pytest.mark.parametrize(\\\"use_sanitized_data\\\", [False, True])\\nasync def test_generate_flow_events_sets_source_flow_provenance_for_public_graph(monkeypatch, use_sanitized_data):\\n    import langflow.api.build as build_module\\n\\n    virtual_flow_id = uuid.uuid4()\\n    source_flow_id = uuid.uuid4()\\n    user_id = uuid.uuid4()\\n    graph = MagicMock()\\n    graph.source_flow_id = None\\n    graph.flow_id = str(source_flow_id)\\n    graph.session_id = str(virtual_flow_id)\\n    graph.run_id = None\\n    graph.vertices = []\\n    graph.vertices_to_run = set()\\n    graph.sort_vertices.return_value = []\\n    graph.set_run_id.side_effect = lambda value: setattr(graph, \\\"run_id\\\", value)\\n    graph.end_all_traces = AsyncMock()\\n\\n    chat_service = MagicMock()\\n    chat_service.set_cache = AsyncMock()\\n    telemetry_service = MagicMock()\\n\\n    @asynccontextmanager\\n    async def fake_session_scope():\\n        yield MagicMock()\\n\\n    build_from_db = AsyncMock(return_value=graph)\\n    build_from_data = AsyncMock(return_value=graph)\\n    monkeypatch.setattr(build_module, \\\"get_chat_service\\\", lambda: chat_service)\\n    monkeypatch.setattr(build_module, \\\"get_telemetry_service\\\", lambda: telemetry_service)\\n    monkeypatch.setattr(build_module, \\\"session_scope\\\", fake_session_scope)\\n    monkeypatch.setattr(build_module, \\\"build_graph_from_db\\\", build_from_db)\\n    monkeypatch.setattr(build_module, \\\"build_graph_from_data\\\", build_from_data)\\n\\n    data = FlowDataRequest(nodes=[], edges=[]) if use_sanitized_data else None\\n    await build_module.generate_flow_events(\\n        flow_id=virtual_flow_id,\\n        source_flow_id=source_flow_id,\\n        background_tasks=BackgroundTasks(),\\n        event_manager=create_default_event_manager(asyncio.Queue()),\\n        inputs=None,\\n        data=data,\\n        files=None,\\n        stop_component_id=None,\\n        start_component_id=None,\\n        log_builds=False,\\n        current_user=SimpleNamespace(id=user_id),\\n        flow_name=\\\"public-flow\\\",\\n        track_job_status=False,\\n        expose_error_details=False,\\n    )\\n\\n    assert graph.source_flow_id == str(source_flow_id)\\n    assert graph.flow_id == str(virtual_flow_id)\\n    if use_sanitized_data:\\n        build_from_data.assert_awaited_once()\\n        assert build_from_data.await_args.kwargs[\\\"flow_id\\\"] == str(source_flow_id)\\n        build_from_db.assert_not_awaited()\\n    else:\\n        build_from_db.assert_awaited_once()\\n        build_from_data.assert_not_awaited()\\n\\n\\nasync def test_generate_flow_events_maps_rejected_file_tweaks_to_bad_request(monkeypatch):\\n    import langflow.api.build as build_module\\n\\n    flow_id = uuid.uuid4()\\n    user_id = uuid.uuid4()\\n    vertex = MagicMock(spec=Vertex)\\n    vertex.id = \\\"file-node\\\"\\n    # The tweak only reaches update_raw_params if the template declares the\\n    # field, so the stand-in needs a real node payload rather than bare mocks.\\n    vertex.data = {\\\"node\\\": {\\\"template\\\": {\\\"file\\\": {\\\"type\\\": \\\"file\\\", \\\"value\\\": \\\"\\\"}}}}\\n    vertex.params = {}\\n    vertex.load_from_db_fields = []\\n    rejection = \\\"FileInput path is outside the authenticated user's storage scope.\\\"\\n    vertex.update_raw_params.side_effect = LocalFileAccessError(rejection)\\n    graph = MagicMock()\\n    graph.vertices = [vertex]\\n\\n    chat_service = MagicMock()\\n    telemetry_service = MagicMock()\\n\\n    @asynccontextmanager\\n    async def fake_session_scope():\\n        yield MagicMock()\\n\\n    monkeypatch.setattr(build_module, \\\"get_chat_service\\\", lambda: chat_service)\\n    monkeypatch.setattr(build_module, \\\"get_telemetry_service\\\", lambda: telemetry_service)\\n    monkeypatch.setattr(build_module, \\\"session_scope\\\", fake_session_scope)\\n    monkeypatch.setattr(build_module, \\\"build_graph_from_db\\\", AsyncMock(return_value=graph))\\n    unexpected_log = AsyncMock()\\n    monkeypatch.setattr(build_module.logger, \\\"aexception\\\", unexpected_log)\\n\\n    with pytest.raises(HTTPException) as exc_info:\\n        await build_module.generate_flow_events(\\n            flow_id=flow_id,\\n            background_tasks=BackgroundTasks(),\\n            event_manager=create_default_event_manager(asyncio.Queue()),\\n            inputs=None,\\n            data=None,\\n            files=None,\\n            stop_component_id=None,\\n            start_component_id=None,\\n            log_builds=False,\\n            current_user=SimpleNamespace(id=user_id),\\n            tweaks={\\\"file-node\\\": {\\\"file\\\": \\\"other-flow/secret.txt\\\"}},\\n            track_job_status=False,\\n            expose_error_details=True,\\n        )\\n\\n    assert exc_info.value.status_code == 400\\n    assert exc_info.value.detail == rejection\\n    unexpected_log.assert_not_awaited()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/api/test_warm_graph_execution.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e74559ef03f43fbff5932d8d6df3148afe67e117992a1fc65797365ab0bd3e32\",\"content\":\"\\\"\\\"\\\"Focused import and execution-mode contracts for warm graph copies.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport os\\nimport subprocess\\nimport sys\\nfrom copy import deepcopy\\nfrom datetime import datetime, timezone\\nfrom pathlib import Path\\nfrom types import SimpleNamespace\\nfrom unittest.mock import AsyncMock, Mock\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom langflow.api import warm_graph\\nfrom langflow.processing.process import process_tweaks\\nfrom langflow.services.warm_registry.service import flow_version\\n\\n\\nclass _FakeVertex:\\n    def __init__(self, raw_params: dict, *, load_from_db_fields: list[str] | None = None) -> None:\\n        self.raw_params = raw_params.copy()\\n        self.params = raw_params.copy()\\n        template = {key: {\\\"value\\\": value} for key, value in raw_params.items()}\\n        for field_name in load_from_db_fields or []:\\n            template[field_name][\\\"load_from_db\\\"] = True\\n        self.full_data = {\\n            \\\"data\\\": {\\n                \\\"node\\\": {\\n                    \\\"template\\\": template,\\n                }\\n            }\\n        }\\n        self.load_from_db_fields = list(load_from_db_fields or [])\\n        self.updated_raw_params = False\\n\\n    def update_raw_params(self, new_params: dict, *, overwrite: bool = False) -> None:\\n        assert overwrite is True\\n        self.raw_params.update(new_params)\\n        self.params = self.raw_params.copy()\\n        self.updated_raw_params = True\\n\\n\\nclass _FakeGraph:\\n    def __init__(self, vertices: list[_FakeVertex]) -> None:\\n        self.vertices = vertices\\n        self.user_id = None\\n        self.session_id = None\\n        self.constructor_stream: bool | None = None\\n        self.constructor_template_stream: dict | None = None\\n        self.has_session_id_vertices: list[str] = []\\n\\n    def get_vertex(self, _vertex_id: str):\\n        return None\\n\\n    def copy_for_run(self, *, user_id: str | None, before_instantiate=None):\\n        copied = deepcopy(self)\\n        copied.user_id = user_id\\n        if before_instantiate is not None:\\n            before_instantiate(copied)\\n        copied.constructor_stream = copied.vertices[0].params.get(\\\"stream\\\") if copied.vertices else None\\n        if copied.vertices:\\n            copied.constructor_template_stream = copied.vertices[0].full_data[\\\"data\\\"][\\\"node\\\"][\\\"template\\\"].get(\\\"stream\\\")\\n        return copied\\n\\n\\ndef _grouped_stream_graph(*, expose_stream: bool):\\n    from lfx.graph import Graph\\n\\n    stream_field = {\\n        \\\"name\\\": \\\"stream\\\",\\n        \\\"type\\\": \\\"bool\\\",\\n        \\\"value\\\": True,\\n        \\\"list\\\": False,\\n        \\\"show\\\": True,\\n        \\\"advanced\\\": False,\\n    }\\n    child = {\\n        \\\"id\\\": \\\"child-1\\\",\\n        \\\"type\\\": \\\"genericNode\\\",\\n        \\\"data\\\": {\\n            \\\"id\\\": \\\"child-1\\\",\\n            \\\"type\\\": \\\"Generic\\\",\\n            \\\"node\\\": {\\n                \\\"template\\\": {\\\"_type\\\": \\\"Generic\\\", \\\"stream\\\": stream_field},\\n                \\\"base_classes\\\": [],\\n                \\\"display_name\\\": \\\"Child\\\",\\n                \\\"outputs\\\": [],\\n            },\\n        },\\n    }\\n    group_template = {}\\n    if expose_stream:\\n        group_template[\\\"stream\\\"] = {\\n            **stream_field,\\n            \\\"proxy\\\": {\\\"field\\\": \\\"stream\\\", \\\"id\\\": \\\"child-1\\\"},\\n        }\\n    group = {\\n        \\\"id\\\": \\\"group-1\\\",\\n        \\\"type\\\": \\\"genericNode\\\",\\n        \\\"data\\\": {\\n            \\\"id\\\": \\\"group-1\\\",\\n            \\\"type\\\": \\\"Group\\\",\\n            \\\"node\\\": {\\n                \\\"template\\\": group_template,\\n                \\\"flow\\\": {\\\"data\\\": {\\\"nodes\\\": [child], \\\"edges\\\": []}},\\n            },\\n        },\\n    }\\n    graph = Graph(flow_id=\\\"flow-id\\\", instantiate_components=False)\\n    graph.add_nodes_and_edges([group], [])\\n    return graph\\n\\n\\ndef test_warm_graph_has_a_clean_import_path() -> None:\\n    \\\"\\\"\\\"Importing the low-level helper must not initialize the v1 router package.\\\"\\\"\\\"\\n    repo_root = Path(__file__).resolve().parents[5]\\n    python_path = os.pathsep.join(\\n        [\\n            str(repo_root / \\\"src\\\" / \\\"backend\\\" / \\\"base\\\"),\\n            str(repo_root / \\\"src\\\" / \\\"lfx\\\" / \\\"src\\\"),\\n            os.environ.get(\\\"PYTHONPATH\\\", \\\"\\\"),\\n        ]\\n    )\\n    env = {**os.environ, \\\"PYTHONPATH\\\": python_path}\\n    result = subprocess.run(  # noqa: S603\\n        [\\n            sys.executable,\\n            \\\"-c\\\",\\n            (\\\"import sys; import langflow.api.warm_graph; assert 'langflow.api.v1' not in sys.modules; print('clean')\\\"),\\n        ],\\n        cwd=repo_root,\\n        env=env,\\n        check=False,\\n        capture_output=True,\\n        text=True,\\n    )\\n\\n    assert result.returncode == 0, result.stderr\\n    assert result.stdout.strip() == \\\"clean\\\"\\n\\n\\n@pytest.mark.parametrize((\\\"stream\\\", \\\"stored_value\\\"), [(True, False), (False, True)])\\nasync def test_warm_deepcopy_matches_cold_implicit_stream_tweak_without_mutating_template(\\n    monkeypatch: pytest.MonkeyPatch,\\n    stream,\\n    stored_value,\\n) -> None:\\n    \\\"\\\"\\\"Warm copies force the run mode just as ``process_tweaks`` does cold.\\\"\\\"\\\"\\n    from langflow.services import deps\\n    from langflow.services.warm_registry import service as registry_service\\n\\n    template = _FakeGraph(\\n        [\\n            _FakeVertex({\\\"stream\\\": stored_value}, load_from_db_fields=[\\\"stream\\\"]),\\n            _FakeVertex({\\\"temperature\\\": 0.2}),\\n            _FakeVertex({\\\"stream\\\": stored_value}),\\n        ]\\n    )\\n    registry = SimpleNamespace(get=lambda _flow_id: (template, \\\"v1\\\"))\\n    monkeypatch.setattr(warm_graph, \\\"is_warm_registry_enabled\\\", lambda _settings: True)\\n    monkeypatch.setattr(deps, \\\"get_settings_service\\\", lambda: SimpleNamespace(settings=SimpleNamespace()))\\n    monkeypatch.setattr(registry_service, \\\"get_warm_registry\\\", lambda: registry)\\n\\n    graph = await warm_graph.warm_deepcopy(\\n        \\\"flow-id\\\",\\n        expected_version=\\\"v1\\\",\\n        user_id=\\\"user-id\\\",\\n        session_id=\\\"session-id\\\",\\n        stream=stream,\\n    )\\n\\n    cold_payload = {\\n        \\\"nodes\\\": [\\n            {\\n                \\\"id\\\": \\\"model\\\",\\n                \\\"data\\\": {\\n                    \\\"node\\\": {\\n                        \\\"display_name\\\": \\\"Model\\\",\\n                        \\\"template\\\": {\\n                            \\\"stream\\\": {\\n                                \\\"type\\\": \\\"bool\\\",\\n                                \\\"show\\\": True,\\n                                \\\"value\\\": stored_value,\\n                                \\\"load_from_db\\\": True,\\n                            }\\n                        },\\n                    }\\n                },\\n            }\\n        ],\\n        \\\"edges\\\": [],\\n    }\\n    cold_result = process_tweaks(deepcopy(cold_payload), {}, stream=stream)\\n    cold_stream_field = cold_result[\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"stream\\\"]\\n\\n    assert graph is not None\\n    assert graph is not template\\n    assert graph.vertices[0].params[\\\"stream\\\"] is cold_stream_field[\\\"value\\\"] is stream\\n    assert graph.constructor_stream is stream\\n    assert graph.constructor_template_stream[\\\"value\\\"] is cold_stream_field[\\\"value\\\"] is stream\\n    assert graph.constructor_template_stream[\\\"load_from_db\\\"] is cold_stream_field[\\\"load_from_db\\\"] is False\\n    assert \\\"stream\\\" not in graph.vertices[0].load_from_db_fields\\n    assert graph.vertices[0].updated_raw_params is True\\n    assert graph.vertices[1].params == {\\\"temperature\\\": 0.2}\\n    assert \\\"load_from_db\\\" not in graph.vertices[2].full_data[\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"stream\\\"]\\n    assert graph.user_id == \\\"user-id\\\"\\n    assert graph.session_id == \\\"session-id\\\"\\n\\n    # Only the request-local deepcopy changes; the shared registry template stays pristine.\\n    assert template.vertices[0].params[\\\"stream\\\"] is stored_value\\n    assert template.vertices[0].load_from_db_fields == [\\\"stream\\\"]\\n    assert template.vertices[0].updated_raw_params is False\\n\\n\\n@pytest.mark.parametrize((\\\"expose_stream\\\", \\\"expected\\\"), [(False, True), (True, False)])\\ndef test_warm_stream_tweak_matches_cold_group_proxy_scope(monkeypatch, expose_stream, expected) -> None:\\n    \\\"\\\"\\\"Hidden grouped fields stay persisted; exposed proxies receive the tweak.\\\"\\\"\\\"\\n    from lfx.graph import Graph\\n\\n    monkeypatch.setattr(Graph, \\\"_instantiate_components_in_vertices\\\", lambda _graph: None)\\n    template = _grouped_stream_graph(expose_stream=expose_stream)\\n    run_graph = template.copy_for_run(\\n        user_id=\\\"caller-id\\\",\\n        before_instantiate=lambda graph: warm_graph._apply_implicit_stream_tweak(graph, stream=False),\\n    )\\n\\n    assert run_graph.get_vertex(\\\"child-1\\\").raw_params[\\\"stream\\\"] is expected\\n    assert template.get_vertex(\\\"child-1\\\").raw_params[\\\"stream\\\"] is True\\n\\n\\nasync def test_warm_deepcopy_rejects_a_graph_from_another_flow_revision(monkeypatch) -> None:\\n    \\\"\\\"\\\"Execution must cold-fallback when the authorized FlowRead revision differs.\\\"\\\"\\\"\\n    from langflow.services import deps\\n    from langflow.services.warm_registry import service as registry_service\\n\\n    template = _FakeGraph([_FakeVertex({\\\"stream\\\": False})])\\n    registry = SimpleNamespace(get=lambda _flow_id: (template, \\\"cached-version\\\"))\\n    monkeypatch.setattr(warm_graph, \\\"is_warm_registry_enabled\\\", lambda _settings: True)\\n    monkeypatch.setattr(deps, \\\"get_settings_service\\\", lambda: SimpleNamespace(settings=SimpleNamespace()))\\n    monkeypatch.setattr(registry_service, \\\"get_warm_registry\\\", lambda: registry)\\n\\n    graph = await warm_graph.warm_deepcopy(\\n        \\\"flow-id\\\",\\n        expected_version=\\\"authorized-version\\\",\\n        user_id=\\\"user-id\\\",\\n        session_id=None,\\n    )\\n\\n    assert graph is None\\n\\n\\nasync def test_warm_deepcopy_cold_falls_back_when_extension_events_need_user_keyspace(monkeypatch) -> None:\\n    \\\"\\\"\\\"Migrated/error-bearing templates must replay parsing under the caller.\\\"\\\"\\\"\\n    from langflow.services import deps\\n    from langflow.services.warm_registry import service as registry_service\\n\\n    template = _FakeGraph([_FakeVertex({\\\"stream\\\": False})])\\n    template.requires_extension_event_replay = True\\n    template.copy_for_run = Mock(side_effect=AssertionError(\\\"extension-event graph was copied\\\"))\\n    registry = SimpleNamespace(get=lambda _flow_id: (template, \\\"v1\\\"))\\n    monkeypatch.setattr(warm_graph, \\\"is_warm_registry_enabled\\\", lambda _settings: True)\\n    monkeypatch.setattr(deps, \\\"get_settings_service\\\", lambda: SimpleNamespace(settings=SimpleNamespace()))\\n    monkeypatch.setattr(registry_service, \\\"get_warm_registry\\\", lambda: registry)\\n\\n    graph = await warm_graph.warm_deepcopy(\\n        \\\"flow-id\\\",\\n        expected_version=\\\"v1\\\",\\n        user_id=\\\"user-id\\\",\\n        session_id=None,\\n    )\\n\\n    assert graph is None\\n    template.copy_for_run.assert_not_called()\\n\\n\\nasync def test_warm_deepcopy_revalidates_current_component_policy(monkeypatch) -> None:\\n    \\\"\\\"\\\"A policy change after preload must reject the cached graph before copying it.\\\"\\\"\\\"\\n    from langflow.services import deps\\n    from langflow.services.warm_registry import service as registry_service\\n    from lfx.utils import flow_validation\\n\\n    template = _FakeGraph([_FakeVertex({\\\"stream\\\": False})])\\n    template.copy_for_run = Mock(side_effect=AssertionError(\\\"blocked graph was copied\\\"))\\n    registry = SimpleNamespace(get=lambda _flow_id: (template, \\\"v1\\\"))\\n    monkeypatch.setattr(warm_graph, \\\"is_warm_registry_enabled\\\", lambda _settings: True)\\n    monkeypatch.setattr(deps, \\\"get_settings_service\\\", lambda: SimpleNamespace(settings=SimpleNamespace()))\\n    monkeypatch.setattr(registry_service, \\\"get_warm_registry\\\", lambda: registry)\\n\\n    class PolicyChangedError(ValueError):\\n        pass\\n\\n    def _reject(_target) -> None:\\n        message = \\\"component is now blocked\\\"\\n        raise PolicyChangedError(message)\\n\\n    monkeypatch.setattr(flow_validation, \\\"validate_flow_for_current_settings\\\", _reject)\\n\\n    with pytest.raises(PolicyChangedError, match=\\\"now blocked\\\"):\\n        await warm_graph.warm_deepcopy(\\n            \\\"flow-id\\\",\\n            expected_version=\\\"v1\\\",\\n            user_id=\\\"user-id\\\",\\n            session_id=None,\\n        )\\n\\n    template.copy_for_run.assert_not_called()\\n\\n\\nasync def test_v1_streaming_run_requests_a_streaming_warm_copy(monkeypatch: pytest.MonkeyPatch) -> None:\\n    \\\"\\\"\\\"The V1 streaming flag reaches the warm-copy stream-mode override.\\\"\\\"\\\"\\n    from langflow.api.v1 import endpoints\\n    from langflow.api.v1.schemas import SimplifiedAPIRequest\\n\\n    captured: dict = {}\\n    graph = SimpleNamespace(vertices=[], run_id=None)\\n\\n    def set_run_id(run_id) -> None:\\n        graph.run_id = str(run_id)\\n\\n    graph.set_run_id = set_run_id\\n\\n    async def fake_warm_deepcopy(flow_id, *, expected_version, user_id, session_id, stream=False):\\n        captured.update(\\n            flow_id=flow_id,\\n            expected_version=expected_version,\\n            user_id=user_id,\\n            session_id=session_id,\\n            stream=stream,\\n        )\\n        return graph\\n\\n    job_service = SimpleNamespace(\\n        create_job=AsyncMock(),\\n        execute_with_status=AsyncMock(return_value=([], \\\"effective-session\\\")),\\n    )\\n    monkeypatch.setattr(warm_graph, \\\"warm_deepcopy\\\", fake_warm_deepcopy)\\n    monkeypatch.setattr(endpoints, \\\"get_job_service\\\", lambda: job_service)\\n    monkeypatch.setattr(\\n        endpoints,\\n        \\\"get_task_service\\\",\\n        lambda: SimpleNamespace(fire_and_forget_task=AsyncMock()),\\n    )\\n    monkeypatch.setattr(endpoints, \\\"get_memory_base_service\\\", lambda: SimpleNamespace(on_flow_output=AsyncMock()))\\n    monkeypatch.setattr(endpoints, \\\"process_tweaks\\\", Mock(side_effect=AssertionError(\\\"cold path used\\\")))\\n\\n    flow_id = uuid4()\\n    user_id = uuid4()\\n    updated_at = datetime(2026, 8, 5, 12, tzinfo=timezone.utc)\\n    result = await endpoints.simple_run_flow(\\n        flow=SimpleNamespace(\\n            id=flow_id,\\n            user_id=user_id,\\n            name=\\\"warm\\\",\\n            data={\\\"nodes\\\": [], \\\"edges\\\": []},\\n            updated_at=updated_at,\\n        ),\\n        input_request=SimplifiedAPIRequest(session_id=\\\"v1-session\\\"),\\n        stream=True,\\n        api_key_user=SimpleNamespace(id=user_id, is_superuser=False),\\n    )\\n\\n    assert result.session_id == \\\"effective-session\\\"\\n    assert captured == {\\n        \\\"flow_id\\\": str(flow_id),\\n        \\\"expected_version\\\": flow_version(updated_at),\\n        \\\"user_id\\\": user_id,\\n        \\\"session_id\\\": \\\"v1-session\\\",\\n        \\\"stream\\\": True,\\n    }\\n\\n\\nasync def test_v2_sync_run_requests_a_non_streaming_warm_copy(monkeypatch: pytest.MonkeyPatch) -> None:\\n    \\\"\\\"\\\"The V2 sync warm path explicitly overrides persisted streaming defaults.\\\"\\\"\\\"\\n    from langflow.api.v2 import workflow_execution\\n    from lfx.workflow.converters import ParsedWorkflowRun\\n\\n    captured: dict = {}\\n    graph = SimpleNamespace(vertices=[], run_id=None, get_terminal_nodes=list)\\n\\n    def set_run_id(run_id) -> None:\\n        graph.run_id = str(run_id)\\n\\n    graph.set_run_id = set_run_id\\n\\n    async def fake_warm_deepcopy(flow_id, *, expected_version, user_id, session_id, stream=False):\\n        captured.update(\\n            flow_id=flow_id,\\n            expected_version=expected_version,\\n            user_id=user_id,\\n            session_id=session_id,\\n            stream=stream,\\n        )\\n        return graph\\n\\n    job_service = SimpleNamespace(\\n        create_job=AsyncMock(),\\n        execute_with_status=AsyncMock(return_value=([], \\\"effective-session\\\")),\\n    )\\n    expected = object()\\n    monkeypatch.setattr(workflow_execution, \\\"warm_deepcopy\\\", fake_warm_deepcopy)\\n    monkeypatch.setattr(workflow_execution, \\\"get_job_service\\\", lambda: job_service)\\n    monkeypatch.setattr(\\n        workflow_execution,\\n        \\\"get_task_service\\\",\\n        lambda: SimpleNamespace(fire_and_forget_task=AsyncMock()),\\n    )\\n    monkeypatch.setattr(\\n        workflow_execution,\\n        \\\"get_memory_base_service\\\",\\n        lambda: SimpleNamespace(on_flow_output=AsyncMock()),\\n    )\\n    monkeypatch.setattr(workflow_execution, \\\"run_response_to_workflow_response\\\", Mock(return_value=expected))\\n    monkeypatch.setattr(workflow_execution, \\\"process_tweaks\\\", Mock(side_effect=AssertionError(\\\"cold path used\\\")))\\n\\n    flow_id = uuid4()\\n    user_id = uuid4()\\n    updated_at = datetime(2026, 8, 5, 12, tzinfo=timezone.utc)\\n    result = await workflow_execution.execute_sync_workflow(\\n        parsed=ParsedWorkflowRun(flow_id=str(flow_id), session_id=\\\"v2-session\\\", mode=\\\"sync\\\"),\\n        flow=SimpleNamespace(\\n            id=flow_id,\\n            user_id=user_id,\\n            name=\\\"warm\\\",\\n            data={\\\"nodes\\\": [], \\\"edges\\\": []},\\n            updated_at=updated_at,\\n        ),\\n        job_id=uuid4(),\\n        current_user=SimpleNamespace(id=user_id),\\n        background_tasks=SimpleNamespace(),\\n        http_request=None,\\n    )\\n\\n    assert result is expected\\n    assert captured == {\\n        \\\"flow_id\\\": str(flow_id),\\n        \\\"expected_version\\\": flow_version(updated_at),\\n        \\\"user_id\\\": str(user_id),\\n        \\\"session_id\\\": \\\"v2-session\\\",\\n        \\\"stream\\\": False,\\n    }\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/api/utils/mcp/test_flow_secrets.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"447af4d61e5d9b523eea64e2d9c4cdaccee69998cd9b9fff373948f16c353a04\",\"content\":\"\\\"\\\"\\\"The credential scrub must not fail open on the shape of the secret.\\n\\n``strip_config_secrets`` decides what to rewrite. Two ways it can hand a credential\\nback to the caller: recognising a literal as an already-substituted reference, and\\ngenerating a name that collides with a different server's, since an existing global\\nvariable is deliberately never overwritten.\\n\\\"\\\"\\\"\\n\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom fastapi import HTTPException\\nfrom langflow.api.utils.mcp.flow_secrets import strip_config_secrets, variable_name_for\\n\\nAWS_ACCESS_KEY_ID = \\\"AKIAIOSFODNN7EXAMPLE\\\"\\nUPPERCASE_HEX_TOKEN = \\\"A3F5C9D2E1B8074F\\\"  # noqa: S105\\n\\n\\nclass TestSecretsThatLookLikeIdentifiers:\\n    \\\"\\\"\\\"A value is not a reference just because it is spelled in capitals.\\\"\\\"\\\"\\n\\n    def test_should_rewrite_an_aws_access_key_id(self):\\n        config = {\\\"url\\\": \\\"https://a.example/mcp\\\", \\\"headers\\\": {\\\"x-api-key\\\": AWS_ACCESS_KEY_ID}}\\n\\n        stripped, variables, found = strip_config_secrets(config, \\\"billing\\\")\\n\\n        assert found is True\\n        assert stripped[\\\"headers\\\"][\\\"x-api-key\\\"] != AWS_ACCESS_KEY_ID\\n        assert AWS_ACCESS_KEY_ID in variables.values()\\n\\n    def test_should_rewrite_an_uppercase_hex_token(self):\\n        config = {\\\"url\\\": \\\"https://a.example/mcp\\\", \\\"headers\\\": {\\\"authorization\\\": UPPERCASE_HEX_TOKEN}}\\n\\n        stripped, variables, found = strip_config_secrets(config, \\\"billing\\\")\\n\\n        assert found is True\\n        assert stripped[\\\"headers\\\"][\\\"authorization\\\"] != UPPERCASE_HEX_TOKEN\\n        assert UPPERCASE_HEX_TOKEN in variables.values()\\n\\n    def test_should_leave_a_name_this_module_generated(self):\\n        \\\"\\\"\\\"A re-save must not wrap its own reference a second time.\\\"\\\"\\\"\\n        reference = variable_name_for(\\\"billing\\\", \\\"x-api-key\\\")\\n        config = {\\\"url\\\": \\\"https://a.example/mcp\\\", \\\"headers\\\": {\\\"x-api-key\\\": reference}}\\n\\n        stripped, variables, found = strip_config_secrets(config, \\\"billing\\\")\\n\\n        assert found is False\\n        assert stripped[\\\"headers\\\"][\\\"x-api-key\\\"] == reference\\n        assert variables == {}\\n\\n    def test_should_leave_an_explicit_placeholder(self):\\n        config = {\\\"url\\\": \\\"https://a.example/mcp\\\", \\\"headers\\\": {\\\"x-api-key\\\": \\\"{{MY_KEY}}\\\"}}\\n\\n        stripped, variables, found = strip_config_secrets(config, \\\"billing\\\")\\n\\n        assert found is False\\n        assert stripped[\\\"headers\\\"][\\\"x-api-key\\\"] == \\\"{{MY_KEY}}\\\"\\n        assert variables == {}\\n\\n\\nclass TestVariableNameIsInjective:\\n    \\\"\\\"\\\"Distinct servers must never be pointed at one another's credential.\\n\\n    ``_ensure_variables`` leaves an existing variable alone, so two servers that\\n    generate the same name means the second silently authenticates with the first\\n    server's key \u2014 against a different target.\\n    \\\"\\\"\\\"\\n\\n    def test_should_not_collide_across_separator_spellings(self):\\n        names = {\\n            variable_name_for(\\\"billing-mcp\\\", \\\"x-api-key\\\"),\\n            variable_name_for(\\\"billing_mcp\\\", \\\"x-api-key\\\"),\\n            variable_name_for(\\\"billing.mcp\\\", \\\"x-api-key\\\"),\\n        }\\n\\n        assert len(names) == 3, f\\\"names collapsed to {names}\\\"\\n\\n    def test_should_not_collide_across_header_spellings(self):\\n        names = {\\n            variable_name_for(\\\"billing\\\", \\\"x-api-key\\\"),\\n            variable_name_for(\\\"billing\\\", \\\"x_api_key\\\"),\\n            variable_name_for(\\\"billing\\\", \\\"X-API-KEY\\\"),\\n        }\\n\\n        assert len(names) == 3, f\\\"names collapsed to {names}\\\"\\n\\n    def test_should_be_stable_for_the_same_pair(self):\\n        \\\"\\\"\\\"A re-save has to land on the variable the previous save created.\\\"\\\"\\\"\\n        first = variable_name_for(\\\"billing-mcp\\\", \\\"x-api-key\\\")\\n        second = variable_name_for(\\\"billing-mcp\\\", \\\"x-api-key\\\")\\n\\n        assert first == second\\n\\n    def test_should_stay_readable_and_prefixed(self):\\n        name = variable_name_for(\\\"billing-mcp\\\", \\\"x-api-key\\\")\\n\\n        assert name.startswith(\\\"MCP_\\\")\\n        assert \\\"BILLING_MCP\\\" in name\\n\\n\\nclass TestUnstorableCredentialFailsTheWrite:\\n    \\\"\\\"\\\"Putting the literal back reported success while writing the secret in clear text.\\n\\n    Restoring traded a leak for a working flow, but the caller was told the save succeeded\\n    and never learned the credential had landed in an unencrypted column that travels\\n    through export, share and version history. A control that silently turns itself off is\\n    worse than one that fails, so the write is refused instead.\\n    \\\"\\\"\\\"\\n\\n    async def test_should_raise_when_a_variable_cannot_be_created(self, monkeypatch):\\n        import langflow.api.utils.mcp.flow_secrets as module\\n\\n        async def failing_ensure(variables, user_id, session):  # noqa: ARG001\\n            return set(variables)\\n\\n        monkeypatch.setattr(module, \\\"_ensure_variables\\\", failing_ensure)\\n\\n        name = variable_name_for(\\\"billing\\\", \\\"x-api-key\\\")\\n        with pytest.raises(HTTPException) as exc_info:\\n            await module.stage_mcp_secrets([], {name: \\\"sk-secret\\\"}, uuid4(), session=None)\\n\\n        assert exc_info.value.status_code == 500\\n        assert \\\"sk-secret\\\" not in str(exc_info.value.detail)\\n\\n    async def test_should_not_raise_when_every_variable_was_stored(self, monkeypatch):\\n        import langflow.api.utils.mcp.flow_secrets as module\\n\\n        async def clean_ensure(variables, user_id, session):  # noqa: ARG001\\n            return set()\\n\\n        monkeypatch.setattr(module, \\\"_ensure_variables\\\", clean_ensure)\\n\\n        name = variable_name_for(\\\"billing\\\", \\\"x-api-key\\\")\\n\\n        await module.stage_mcp_secrets([], {name: \\\"sk-secret\\\"}, uuid4(), session=None)\\n\\n\\ndef test_should_not_commit_inside_the_helper():\\n    \\\"\\\"\\\"The batch write path documents itself as all-or-nothing; a commit here breaks it.\\\"\\\"\\\"\\n    from pathlib import Path\\n\\n    from langflow.api.utils.mcp import flow_secrets as flow_secrets_module\\n\\n    module = Path(flow_secrets_module.__file__)\\n    source = module.read_text(encoding=\\\"utf-8\\\")\\n\\n    assert \\\"session.commit()\\\" not in source\\n\\n\\nclass TestStagingSurvivesARetry:\\n    \\\"\\\"\\\"A rollback discards the staged rows; the in-place rewrite of the flow survives it.\\n\\n    Re-extracting on the second attempt would find only the reference the first attempt\\n    wrote, stage nothing, and let the flow commit pointing at a variable that was never\\n    created. Extraction therefore happens once and staging happens per attempt.\\n    \\\"\\\"\\\"\\n\\n    def test_should_find_nothing_on_a_second_extraction(self):\\n        \\\"\\\"\\\"Documents why re-extracting per attempt cannot work.\\\"\\\"\\\"\\n        from langflow.api.utils.mcp.flow_secrets import extract_and_strip_mcp_secrets\\n\\n        flow_data = {\\n            \\\"nodes\\\": [\\n                {\\n                    \\\"data\\\": {\\n                        \\\"node\\\": {\\n                            \\\"template\\\": {\\n                                \\\"mcp_server\\\": {\\n                                    \\\"value\\\": {\\n                                        \\\"name\\\": \\\"billing\\\",\\n                                        \\\"config\\\": {\\\"headers\\\": {\\\"x-api-key\\\": \\\"sk-real-secret\\\"}},\\n                                    }\\n                                }\\n                            }\\n                        }\\n                    }\\n                }\\n            ]\\n        }\\n\\n        first_carried, first_variables = extract_and_strip_mcp_secrets(flow_data)\\n        second_carried, second_variables = extract_and_strip_mcp_secrets(flow_data)\\n\\n        assert first_carried\\n        assert first_variables\\n        assert second_carried == [], \\\"a retry would stage nothing\\\"\\n        assert second_variables == {}, \\\"a retry would stage nothing\\\"\\n\\n    def test_should_expose_staging_separately_from_extraction(self):\\n        from langflow.api.utils.mcp import flow_secrets\\n\\n        assert hasattr(flow_secrets, \\\"stage_mcp_secrets\\\")\\n        assert hasattr(flow_secrets, \\\"extract_and_strip_mcp_secrets\\\")\\n\\n\\nclass TestNonSecretHeadersAreLeftAlone:\\n    \\\"\\\"\\\"Turning ``accept: application/json`` into a Credential variable is noise.\\n\\n    The list is an allowlist of headers that are never secrets, not a guess at which\\n    values look secret: failing open on a heuristic would leak, while failing open on\\n    these specific names cannot.\\n    \\\"\\\"\\\"\\n\\n    def test_should_not_capture_content_negotiation_headers(self):\\n        config = {\\n            \\\"url\\\": \\\"https://a.example/mcp\\\",\\n            \\\"headers\\\": {\\\"accept\\\": \\\"application/json\\\", \\\"content-type\\\": \\\"application/json\\\"},\\n        }\\n\\n        stripped, variables, found = strip_config_secrets(config, \\\"billing\\\")\\n\\n        assert found is False\\n        assert variables == {}\\n        assert stripped[\\\"headers\\\"] == config[\\\"headers\\\"]\\n\\n    def test_should_still_capture_a_secret_next_to_them(self):\\n        config = {\\n            \\\"url\\\": \\\"https://a.example/mcp\\\",\\n            \\\"headers\\\": {\\\"accept\\\": \\\"application/json\\\", \\\"x-api-key\\\": \\\"sk-real-secret\\\"},\\n        }\\n\\n        stripped, variables, found = strip_config_secrets(config, \\\"billing\\\")\\n\\n        assert found is True\\n        assert stripped[\\\"headers\\\"][\\\"accept\\\"] == \\\"application/json\\\"\\n        assert stripped[\\\"headers\\\"][\\\"x-api-key\\\"] != \\\"sk-real-secret\\\"\\n        assert \\\"sk-real-secret\\\" in variables.values()\\n\\n    def test_should_match_the_header_name_case_insensitively(self):\\n        config = {\\\"url\\\": \\\"https://a.example/mcp\\\", \\\"headers\\\": {\\\"Accept\\\": \\\"application/json\\\"}}\\n\\n        _, variables, found = strip_config_secrets(config, \\\"billing\\\")\\n\\n        assert found is False\\n        assert variables == {}\\n\\n    def test_should_never_treat_an_env_entry_as_non_secret(self):\\n        \\\"\\\"\\\"The allowlist is about HTTP headers; an env var named accept is not one.\\\"\\\"\\\"\\n        config = {\\\"command\\\": \\\"uvx\\\", \\\"env\\\": {\\\"accept\\\": \\\"something\\\"}}\\n\\n        _, variables, found = strip_config_secrets(config, \\\"billing\\\")\\n\\n        assert found is True\\n        assert \\\"something\\\" in variables.values()\\n\\n\\nclass TestNonMcpFlowsCostNothing:\\n    \\\"\\\"\\\"A flow without an MCP server must not reach the database on the write path.\\n\\n    The scrub runs on every flow write. If it opened a savepoint or issued a query for\\n    flows that carry no credential it would lengthen the write transaction for everyone,\\n    which on SQLite is how unrelated writers start seeing \\\"database is locked\\\".\\n    \\\"\\\"\\\"\\n\\n    def test_should_extract_nothing_from_a_flow_without_an_mcp_server(self):\\n        from langflow.api.utils.mcp.flow_secrets import extract_and_strip_mcp_secrets\\n\\n        flow_data = {\\n            \\\"nodes\\\": [\\n                {\\\"data\\\": {\\\"node\\\": {\\\"template\\\": {\\\"input_value\\\": {\\\"value\\\": \\\"hello\\\"}}}}},\\n                {\\\"data\\\": {\\\"node\\\": {\\\"template\\\": {\\\"path\\\": {\\\"value\\\": \\\"report.txt\\\"}}}}},\\n            ]\\n        }\\n\\n        carried, variables = extract_and_strip_mcp_secrets(flow_data)\\n\\n        assert carried == []\\n        assert variables == {}\\n\\n    async def test_should_not_touch_the_session_when_there_is_nothing_to_stage(self):\\n        from langflow.api.utils.mcp.flow_secrets import stage_mcp_secrets\\n\\n        class ExplodingSession:\\n            def __getattr__(self, name):\\n                msg = f\\\"the write path must not use the session, but it called {name!r}\\\"\\n                raise AssertionError(msg)\\n\\n        await stage_mcp_secrets([], {}, uuid4(), session=ExplodingSession())\\n\\n\\nclass TestRotationIsScopedToAnInteractiveEdit:\\n    \\\"\\\"\\\"An import must not re-point a server every other flow of that user shares.\\n\\n    ``mcp_server`` rows are keyed on (user_id, name), so rotating one on any flow write\\n    let a single import silently hand every flow bound to that name whatever credential\\n    the imported file carried \u2014 and the previous value is unrecoverable, because the\\n    encrypted column is overwritten in place. Rotation only makes sense where the user is\\n    demonstrably editing a server the flow was already bound to.\\n    \\\"\\\"\\\"\\n\\n    @staticmethod\\n    def _stored(name, headers):\\n        from langflow.services.auth.mcp_encryption import encrypt_mcp_config\\n        from langflow.services.database.models import MCPServer\\n\\n        return MCPServer(user_id=uuid4(), name=name, config=encrypt_mcp_config({\\\"headers\\\": headers}))\\n\\n    @staticmethod\\n    def _session_returning(row):\\n        class Result:\\n            def first(self):\\n                return row\\n\\n        class Session:\\n            async def exec(self, _stmt):\\n                return Result()\\n\\n            def add(self, _row):\\n                msg = \\\"must not insert when the row already exists\\\"\\n                raise AssertionError(msg)\\n\\n        return Session()\\n\\n    @staticmethod\\n    def _headers_of(row):\\n        from langflow.services.auth.mcp_encryption import decrypt_mcp_config\\n\\n        return decrypt_mcp_config(row.config or {}).get(\\\"headers\\\")\\n\\n    async def test_should_not_rotate_on_an_import(self, monkeypatch):\\n        import langflow.api.utils.mcp.flow_secrets as module\\n\\n        async def clean_ensure(variables, user_id, session):  # noqa: ARG001\\n            return set()\\n\\n        monkeypatch.setattr(module, \\\"_ensure_variables\\\", clean_ensure)\\n        row = self._stored(\\\"ui_svc\\\", {\\\"Authorization\\\": \\\"Bearer UI-KEY-1\\\"})\\n        carried = [(\\\"ui_svc\\\", {\\\"headers\\\": {\\\"Authorization\\\": \\\"Bearer UI-KEY-2-FROM-LEGACY-EXPORT\\\"}})]\\n\\n        await module.stage_mcp_secrets(carried, {}, uuid4(), self._session_returning(row))\\n\\n        assert self._headers_of(row) == {\\\"Authorization\\\": \\\"Bearer UI-KEY-1\\\"}\\n\\n    async def test_should_rotate_a_server_the_flow_was_already_bound_to(self, monkeypatch):\\n        import langflow.api.utils.mcp.flow_secrets as module\\n\\n        async def clean_ensure(variables, user_id, session):  # noqa: ARG001\\n            return set()\\n\\n        monkeypatch.setattr(module, \\\"_ensure_variables\\\", clean_ensure)\\n        row = self._stored(\\\"ui_svc\\\", {\\\"Authorization\\\": \\\"Bearer OLD\\\"})\\n        carried = [(\\\"ui_svc\\\", {\\\"headers\\\": {\\\"Authorization\\\": \\\"Bearer ROTATED\\\"}})]\\n\\n        await module.stage_mcp_secrets(carried, {}, uuid4(), self._session_returning(row), rotatable_servers={\\\"ui_svc\\\"})\\n\\n        assert self._headers_of(row) == {\\\"Authorization\\\": \\\"Bearer ROTATED\\\"}\\n\\n    async def test_should_not_rotate_a_server_the_flow_was_not_bound_to(self, monkeypatch):\\n        \\\"\\\"\\\"Saving a freshly imported flow must not adopt its credential either.\\\"\\\"\\\"\\n        import langflow.api.utils.mcp.flow_secrets as module\\n\\n        async def clean_ensure(variables, user_id, session):  # noqa: ARG001\\n            return set()\\n\\n        monkeypatch.setattr(module, \\\"_ensure_variables\\\", clean_ensure)\\n        row = self._stored(\\\"ui_svc\\\", {\\\"Authorization\\\": \\\"Bearer UI-KEY-1\\\"})\\n        carried = [(\\\"ui_svc\\\", {\\\"headers\\\": {\\\"Authorization\\\": \\\"Bearer IMPORTED\\\"}})]\\n\\n        await module.stage_mcp_secrets(\\n            carried, {}, uuid4(), self._session_returning(row), rotatable_servers={\\\"other_svc\\\"}\\n        )\\n\\n        assert self._headers_of(row) == {\\\"Authorization\\\": \\\"Bearer UI-KEY-1\\\"}\\n\\n\\nclass TestServerNamesAFlowIsBoundTo:\\n    def test_should_collect_every_referenced_server_name(self):\\n        from langflow.api.utils.mcp.flow_secrets import mcp_server_names\\n\\n        flow_data = {\\n            \\\"nodes\\\": [\\n                {\\\"data\\\": {\\\"node\\\": {\\\"template\\\": {\\\"mcp_server\\\": {\\\"value\\\": {\\\"name\\\": \\\"ui_svc\\\", \\\"config\\\": {}}}}}}},\\n                {\\\"data\\\": {\\\"node\\\": {\\\"template\\\": {\\\"mcp_server\\\": {\\\"value\\\": {\\\"name\\\": \\\"other\\\", \\\"config\\\": {}}}}}}},\\n            ]\\n        }\\n\\n        assert mcp_server_names(flow_data) == {\\\"ui_svc\\\", \\\"other\\\"}\\n\\n    def test_should_be_empty_for_a_flow_without_mcp_servers(self):\\n        from langflow.api.utils.mcp.flow_secrets import mcp_server_names\\n\\n        assert mcp_server_names({\\\"nodes\\\": [{\\\"data\\\": {\\\"node\\\": {\\\"template\\\": {}}}}]}) == set()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/api/utils/test_preserve_flow_id.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a3e47760f52bed1437d9db024d6311cc6ca1ee6f9ead4fcad16cae68b77a05cc\",\"content\":\"\\\"\\\"\\\"Unit tests for stable flow-ID preservation on import/upload.\\n\\nTests cover the FlowCreate schema change and the three upsert branches\\nin the upload endpoint logic.  No database or HTTP server is required\\nfor the schema tests; the endpoint-logic tests use unittest.mock to\\nstand in for the async DB session and storage service.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom unittest.mock import AsyncMock, MagicMock, patch\\nfrom uuid import UUID, uuid4\\n\\nimport pytest\\nfrom langflow.services.database.models.flow.model import FlowCreate\\n\\n# ---------------------------------------------------------------------------\\n# FlowCreate schema\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestFlowCreateSchema:\\n    def test_id_field_is_optional(self):\\n        \\\"\\\"\\\"FlowCreate must accept construction without an id.\\\"\\\"\\\"\\n        flow = FlowCreate(name=\\\"No ID Flow\\\")\\n        assert flow.id is None\\n\\n    def test_id_field_accepts_uuid(self):\\n        \\\"\\\"\\\"FlowCreate must store a provided UUID verbatim.\\\"\\\"\\\"\\n        stable_id = uuid4()\\n        flow = FlowCreate(name=\\\"With ID\\\", id=stable_id)\\n        assert flow.id == stable_id\\n\\n    def test_id_field_accepts_uuid_string(self):\\n        \\\"\\\"\\\"FlowCreate must coerce a UUID string to a UUID object.\\\"\\\"\\\"\\n        stable_id = uuid4()\\n        flow = FlowCreate(name=\\\"With String ID\\\", id=str(stable_id))\\n        assert flow.id == stable_id\\n\\n    def test_id_from_dict_roundtrip(self):\\n        \\\"\\\"\\\"Simulates parsing a downloaded flow JSON that contains an id.\\\"\\\"\\\"\\n        stable_id = uuid4()\\n        raw = {\\n            \\\"id\\\": str(stable_id),\\n            \\\"name\\\": \\\"Exported Flow\\\",\\n            \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []},\\n        }\\n        flow = FlowCreate(**raw)\\n        assert flow.id == stable_id\\n        assert flow.name == \\\"Exported Flow\\\"\\n\\n    def test_no_id_in_dict_gives_none(self):\\n        \\\"\\\"\\\"Existing flow dicts without id must still parse cleanly.\\\"\\\"\\\"\\n        raw = {\\\"name\\\": \\\"Legacy Flow\\\", \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}}\\n        flow = FlowCreate(**raw)\\n        assert flow.id is None\\n\\n\\n# ---------------------------------------------------------------------------\\n# Upload endpoint \u2014 upsert branch selection\\n# ---------------------------------------------------------------------------\\n# We test the branching logic by directly calling the three paths as the\\n# endpoint itself would, verifying correct helper selection without spinning\\n# up a real server or database.\\n\\n\\ndef _make_flow_create(flow_id: UUID | None = None, name: str = \\\"Test Flow\\\") -> FlowCreate:\\n    return FlowCreate(id=flow_id, name=name, data={\\\"nodes\\\": [], \\\"edges\\\": []})\\n\\n\\ndef _make_existing_flow(flow_id: UUID, user_id: UUID) -> MagicMock:\\n    \\\"\\\"\\\"Return a mock Flow ORM object.\\\"\\\"\\\"\\n    m = MagicMock()\\n    m.id = flow_id\\n    m.user_id = user_id\\n    return m\\n\\n\\nclass TestUploadUpsertBranches:\\n    \\\"\\\"\\\"Test the three upsert branches introduced in the upload endpoint.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_no_id_calls_new_flow(self):\\n        \\\"\\\"\\\"Flow without id \u2192 _new_flow called with no flow_id kwarg.\\\"\\\"\\\"\\n        flow = _make_flow_create(flow_id=None)\\n        current_user = MagicMock()\\n        current_user.id = uuid4()\\n\\n        new_flow_mock = AsyncMock(return_value=MagicMock())\\n\\n        # Simulate the branch directly\\n        if flow.id is not None:\\n            pytest.fail(\\\"Should have taken the no-id branch\\\")\\n\\n        with patch(\\\"langflow.api.v1.flows._new_flow\\\", new_flow_mock):\\n            await new_flow_mock(session=None, flow=flow, user_id=current_user.id, storage_service=None)\\n\\n        new_flow_mock.assert_awaited_once()\\n        call_kwargs = new_flow_mock.call_args.kwargs\\n        # No flow_id should be passed (will generate a UUID)\\n        assert \\\"flow_id\\\" not in call_kwargs or call_kwargs[\\\"flow_id\\\"] is None\\n\\n    @pytest.mark.asyncio\\n    async def test_new_id_not_in_db_calls_new_flow_with_id(self):\\n        \\\"\\\"\\\"Flow with id that doesn't exist \u2192 _new_flow called with flow_id.\\\"\\\"\\\"\\n        stable_id = uuid4()\\n        flow = _make_flow_create(flow_id=stable_id)\\n        current_user = MagicMock()\\n        current_user.id = uuid4()\\n\\n        new_flow_mock = AsyncMock(return_value=MagicMock())\\n\\n        # existing = None (not in DB)\\n        existing = None\\n\\n        # Branch: id present, existing is None \u2192 CREATE with stable id\\n        assert flow.id is not None\\n        assert existing is None\\n\\n        with patch(\\\"langflow.api.v1.flows._new_flow\\\", new_flow_mock):\\n            await new_flow_mock(\\n                session=None,\\n                flow=flow,\\n                user_id=current_user.id,\\n                storage_service=None,\\n                flow_id=flow.id,\\n            )\\n\\n        call_kwargs = new_flow_mock.call_args.kwargs\\n        assert call_kwargs[\\\"flow_id\\\"] == stable_id\\n\\n    @pytest.mark.asyncio\\n    async def test_id_owned_by_same_user_calls_update(self):\\n        \\\"\\\"\\\"Flow id exists and belongs to current user \u2192 update path.\\\"\\\"\\\"\\n        stable_id = uuid4()\\n        user_id = uuid4()\\n        flow = _make_flow_create(flow_id=stable_id)\\n        existing = _make_existing_flow(stable_id, user_id)\\n\\n        current_user = MagicMock()\\n        current_user.id = user_id\\n\\n        update_mock = AsyncMock(return_value=MagicMock())\\n\\n        # Branch: id present, existing owned by current user \u2192 UPDATE\\n        assert flow.id is not None\\n        assert existing is not None\\n        assert existing.user_id == current_user.id\\n\\n        with patch(\\\"langflow.api.v1.flows._update_existing_flow\\\", update_mock):\\n            await update_mock(\\n                session=None,\\n                existing_flow=existing,\\n                flow=flow,\\n                current_user=current_user,\\n                storage_service=None,\\n            )\\n\\n        update_mock.assert_awaited_once()\\n\\n    @pytest.mark.asyncio\\n    async def test_id_owned_by_other_user_clears_id(self):\\n        \\\"\\\"\\\"Flow id exists but belongs to another user \u2192 id cleared, new UUID minted.\\\"\\\"\\\"\\n        stable_id = uuid4()\\n        owner_id = uuid4()\\n        requester_id = uuid4()\\n\\n        flow = _make_flow_create(flow_id=stable_id)\\n        existing = _make_existing_flow(stable_id, owner_id)\\n\\n        current_user = MagicMock()\\n        current_user.id = requester_id\\n\\n        # Branch: id present, existing owned by different user \u2192 clear id, new_flow\\n        assert flow.id is not None\\n        assert existing is not None\\n        assert existing.user_id != current_user.id\\n\\n        # Simulate the branch behaviour\\n        flow.id = None  # as the endpoint does\\n\\n        new_flow_mock = AsyncMock(return_value=MagicMock())\\n        with patch(\\\"langflow.api.v1.flows._new_flow\\\", new_flow_mock):\\n            await new_flow_mock(session=None, flow=flow, user_id=current_user.id, storage_service=None)\\n\\n        # After clearing, flow.id must be None so a fresh UUID is generated\\n        assert flow.id is None\\n        call_kwargs = new_flow_mock.call_args.kwargs\\n        assert \\\"flow_id\\\" not in call_kwargs or call_kwargs.get(\\\"flow_id\\\") is None\\n\\n\\n# ---------------------------------------------------------------------------\\n# PUT /flows/{id} endpoint schema visibility\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestUpsertEndpointVisibility:\\n    def test_upsert_route_in_openapi_schema(self):\\n        \\\"\\\"\\\"PUT /flows/{flow_id} must be visible in the OpenAPI schema.\\\"\\\"\\\"\\n        from langflow.api.v1.flows import router\\n\\n        put_routes = [r for r in router.routes if \\\"PUT\\\" in getattr(r, \\\"methods\\\", set())]\\n        upsert_routes = [r for r in put_routes if \\\"{flow_id}\\\" in getattr(r, \\\"path\\\", \\\"\\\")]\\n\\n        assert upsert_routes, \\\"No PUT /{flow_id} route found\\\"\\n        upsert_route = upsert_routes[0]\\n        # include_in_schema defaults to True; check it is not False\\n        assert getattr(upsert_route, \\\"include_in_schema\\\", True) is True\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/api/v1/test_chat_build_flow_authz.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"be2bbba909e089e301b0b3b04402db285677d609d14b8ad3b54b7fda1242c83c\",\"content\":\"\\\"\\\"\\\"Route-level tests for the share-aware load + deny->404 path in ``build_flow``.\\n\\nThe handler was historically owner-OR-public scoped, which silently blocked\\nshared-flow execution by non-owners even when the registered authorization\\nplugin would have allowed it. These tests pin the new behavior:\\n\\n* Non-owner request loaded via the share-aware helper (plugin decides)\\n* Plugin deny translated to 404 so callers can't enumerate UUIDs via 403 vs 404\\n* PUBLIC fallback still works when the share-aware load returns None\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom contextlib import asynccontextmanager\\nfrom types import SimpleNamespace\\nfrom typing import Any\\nfrom unittest.mock import AsyncMock, MagicMock\\nfrom uuid import UUID, uuid4\\n\\nimport pytest\\nfrom fastapi import HTTPException\\n\\n\\nclass _FakeSession:\\n    \\\"\\\"\\\"Minimal async session that returns canned exec results.\\\"\\\"\\\"\\n\\n    def __init__(self, exec_results: list[Any] | None = None) -> None:\\n        self._exec_results = exec_results or []\\n\\n    async def exec(self, _stmt):\\n        rows = self._exec_results.pop(0) if self._exec_results else []\\n        return _ExecResult(rows)\\n\\n\\nclass _ExecResult:\\n    def __init__(self, rows: list[Any]):\\n        self._rows = list(rows)\\n\\n    def first(self):\\n        return self._rows[0] if self._rows else None\\n\\n\\ndef _make_user(*, is_superuser: bool = False) -> SimpleNamespace:\\n    return SimpleNamespace(id=uuid4(), is_superuser=is_superuser, username=\\\"u\\\")\\n\\n\\ndef _make_flow(*, owner_id: UUID, public: bool = False, data: dict[str, Any] | None = None):\\n    \\\"\\\"\\\"Build a flow stub with the attributes build_flow reads.\\\"\\\"\\\"\\n    from langflow.services.database.models.flow.model import AccessTypeEnum\\n\\n    return SimpleNamespace(\\n        id=uuid4(),\\n        user_id=owner_id,\\n        workspace_id=None,\\n        folder_id=None,\\n        data=data,\\n        access_type=AccessTypeEnum.PUBLIC if public else AccessTypeEnum.PRIVATE,\\n    )\\n\\n\\n@pytest.fixture\\ndef patch_build_flow(monkeypatch):\\n    \\\"\\\"\\\"Install fakes for session_scope, _read_flow, ensure_flow_permission, start_flow_build.\\\"\\\"\\\"\\n    from langflow.api.v1 import chat as chat_module\\n\\n    state: dict[str, Any] = {\\n        \\\"session_exec\\\": [],\\n        \\\"read_flow\\\": None,\\n        \\\"ensure_raises\\\": None,\\n        \\\"start_kwargs\\\": None,\\n    }\\n\\n    @asynccontextmanager\\n    async def fake_session_scope():\\n        yield _FakeSession(state[\\\"session_exec\\\"])\\n\\n    async def fake_read_flow(_session, _flow_id, _user_id):\\n        return state[\\\"read_flow\\\"]\\n\\n    async def fake_ensure(*_args, **_kwargs):\\n        if state[\\\"ensure_raises\\\"] is not None:\\n            raise state[\\\"ensure_raises\\\"]\\n\\n    async def fake_start_build(**kwargs):\\n        state[\\\"start_kwargs\\\"] = kwargs\\n        return \\\"fake-job-id\\\"\\n\\n    monkeypatch.setattr(chat_module, \\\"session_scope\\\", fake_session_scope)\\n\\n    # _read_flow is imported lazily inside build_flow; patch the helper module.\\n    from langflow.api.v1 import flows_helpers\\n\\n    monkeypatch.setattr(flows_helpers, \\\"_read_flow\\\", fake_read_flow)\\n    monkeypatch.setattr(chat_module, \\\"ensure_flow_permission\\\", fake_ensure)\\n    monkeypatch.setattr(chat_module, \\\"start_flow_build\\\", fake_start_build)\\n\\n    # validate_flow_for_current_settings is called when flow.data exists; we\\n    # leave flow.data=None so it's not invoked. queue_service.register_job_owner\\n    # is awaited at the end \u2014 provide a stub queue service in the call.\\n\\n    return state\\n\\n\\ndef _make_queue_service():\\n    \\\"\\\"\\\"Stub the queue service object passed via Depends in the real route.\\\"\\\"\\\"\\n\\n    async def register(_job_id, _user_id):\\n        return None\\n\\n    return SimpleNamespace(register_job_owner=register)\\n\\n\\n# --------------------------------------------------------------------- #\\n\\n\\n@pytest.mark.asyncio\\nasync def test_build_flow_owner_succeeds(patch_build_flow):\\n    \\\"\\\"\\\"Owner can build their own private flow \u2014 the historical happy path.\\\"\\\"\\\"\\n    from langflow.api.v1 import chat as chat_module\\n\\n    owner = _make_user()\\n    flow = _make_flow(owner_id=owner.id, public=False)\\n    patch_build_flow[\\\"read_flow\\\"] = flow\\n\\n    result = await chat_module.build_flow(\\n        flow_id=flow.id,\\n        background_tasks=None,\\n        current_user=owner,\\n        queue_service=_make_queue_service(),\\n    )\\n    assert result == {\\\"job_id\\\": \\\"fake-job-id\\\"}\\n\\n\\n@pytest.mark.asyncio\\nasync def test_build_flow_shared_private_non_owner_succeeds(patch_build_flow):\\n    \\\"\\\"\\\"Non-owner can build a private shared flow when the plugin allows execute.\\\"\\\"\\\"\\n    from langflow.api.v1 import chat as chat_module\\n\\n    user = _make_user()\\n    flow = _make_flow(owner_id=uuid4(), public=False)\\n    patch_build_flow[\\\"read_flow\\\"] = flow\\n\\n    result = await chat_module.build_flow(\\n        flow_id=flow.id,\\n        background_tasks=None,\\n        current_user=user,\\n        queue_service=_make_queue_service(),\\n    )\\n    assert result == {\\\"job_id\\\": \\\"fake-job-id\\\"}\\n\\n\\n@pytest.mark.asyncio\\nasync def test_build_flow_non_owner_cannot_override_flow_data(patch_build_flow, monkeypatch):\\n    \\\"\\\"\\\"Non-owner with execute access cannot supply alternate graph data in the body.\\n\\n    This asserted a 404 until LE-1905. Denying the override broke the\\n    Playground, which posts the canvas data on every run: a non-owner with\\n    execute permission was told the flow did not exist. The override is now\\n    gated on ``flow:write``; an execute-only caller has it dropped and runs\\n    the stored graph. The security property is unchanged and still asserted\\n    here: the caller-supplied graph never runs.\\n    \\\"\\\"\\\"\\n    from langflow.api.v1 import chat as chat_module\\n    from langflow.api.v1.schemas import FlowDataRequest\\n    from langflow.services.authorization import flow_data_override\\n\\n    async def _deny_write(*_args, **_kwargs):\\n        raise HTTPException(status_code=403, detail=\\\"forbidden\\\")\\n\\n    # Execute-only caller: the flow:write gate denies the override.\\n    monkeypatch.setattr(flow_data_override, \\\"ensure_flow_permission\\\", _deny_write)\\n\\n    user = _make_user()\\n    flow = _make_flow(owner_id=uuid4(), public=False)\\n    patch_build_flow[\\\"read_flow\\\"] = flow\\n    override = FlowDataRequest(nodes=[{\\\"id\\\": \\\"n1\\\"}], edges=[])\\n\\n    result = await chat_module.build_flow(\\n        flow_id=flow.id,\\n        background_tasks=None,\\n        current_user=user,\\n        queue_service=_make_queue_service(),\\n        data=override,\\n    )\\n    # The run proceeds with the stored graph; the override is dropped.\\n    assert result == {\\\"job_id\\\": \\\"fake-job-id\\\"}\\n    assert patch_build_flow[\\\"start_kwargs\\\"][\\\"data\\\"] is None\\n\\n\\n@pytest.mark.asyncio\\nasync def test_build_flow_write_holder_may_override_someone_elses_flow(patch_build_flow, monkeypatch):\\n    \\\"\\\"\\\"A caller holding ``flow:write`` may run an unsaved graph they cannot save.\\n\\n    Overriding the stored graph is an edit expressed at run time, so it is\\n    gated on ``flow:write`` rather than ownership (LE-1905): a caller who can\\n    persist the graph can already PATCH it and run it, so honoring the unsaved\\n    copy grants nothing new.\\n    \\\"\\\"\\\"\\n    from langflow.api.v1 import chat as chat_module\\n    from langflow.api.v1.schemas import FlowDataRequest\\n    from langflow.services.authorization import flow_data_override\\n\\n    async def _allow_write(*_args, **_kwargs):\\n        return None\\n\\n    # Non-owner, but the flow:write gate allows the override.\\n    monkeypatch.setattr(flow_data_override, \\\"ensure_flow_permission\\\", _allow_write)\\n\\n    async def allow_inline(_data, *, is_superuser):\\n        assert is_superuser is False\\n\\n    monkeypatch.setattr(chat_module, \\\"prepare_flow_build_for_user\\\", allow_inline)\\n\\n    user = _make_user()\\n    flow = _make_flow(owner_id=uuid4(), public=False)\\n    patch_build_flow[\\\"read_flow\\\"] = flow\\n    override = FlowDataRequest(nodes=[{\\\"id\\\": \\\"n1\\\"}], edges=[])\\n\\n    result = await chat_module.build_flow(\\n        flow_id=flow.id,\\n        background_tasks=None,\\n        current_user=user,\\n        queue_service=_make_queue_service(),\\n        data=override,\\n    )\\n    assert result == {\\\"job_id\\\": \\\"fake-job-id\\\"}\\n    # The caller's graph is honored, not the stored one.\\n    assert patch_build_flow[\\\"start_kwargs\\\"][\\\"data\\\"] is override\\n\\n\\n@pytest.mark.asyncio\\nasync def test_build_flow_owner_can_override_flow_data(patch_build_flow, monkeypatch):\\n    \\\"\\\"\\\"Owner may still pass flow data overrides in the build request.\\\"\\\"\\\"\\n    from langflow.api.v1 import chat as chat_module\\n    from langflow.api.v1.schemas import FlowDataRequest\\n\\n    async def allow_inline(_data, *, is_superuser):\\n        assert is_superuser is False\\n\\n    monkeypatch.setattr(chat_module, \\\"prepare_flow_build_for_user\\\", allow_inline)\\n\\n    owner = _make_user()\\n    flow = _make_flow(owner_id=owner.id, public=False)\\n    patch_build_flow[\\\"read_flow\\\"] = flow\\n    override = FlowDataRequest(nodes=[{\\\"id\\\": \\\"n1\\\"}], edges=[])\\n\\n    result = await chat_module.build_flow(\\n        flow_id=flow.id,\\n        background_tasks=None,\\n        current_user=owner,\\n        queue_service=_make_queue_service(),\\n        data=override,\\n    )\\n    assert result == {\\\"job_id\\\": \\\"fake-job-id\\\"}\\n\\n\\n@pytest.mark.asyncio\\nasync def test_build_flow_admin_only_blocks_non_superuser_inline_custom_code(patch_build_flow, monkeypatch):\\n    \\\"\\\"\\\"Admin-only policy is applied before owner-supplied inline graph data reaches the build worker.\\\"\\\"\\\"\\n    from langflow.api.v1 import chat as chat_module\\n    from langflow.api.v1.schemas import FlowDataRequest\\n    from lfx.utils.flow_validation import CustomComponentValidationError\\n\\n    owner = _make_user()\\n    flow = _make_flow(owner_id=owner.id, public=False)\\n    patch_build_flow[\\\"read_flow\\\"] = flow\\n    override = FlowDataRequest(nodes=[{\\\"id\\\": \\\"custom\\\"}], edges=[])\\n\\n    async def reject_custom_code(_data, *, is_superuser):\\n        assert is_superuser is False\\n        message = \\\"custom components are restricted to administrators\\\"\\n        raise CustomComponentValidationError(message)\\n\\n    monkeypatch.setattr(chat_module, \\\"prepare_flow_build_for_user\\\", reject_custom_code)\\n\\n    with pytest.raises(HTTPException) as excinfo:\\n        await chat_module.build_flow(\\n            flow_id=flow.id,\\n            background_tasks=None,\\n            current_user=owner,\\n            queue_service=_make_queue_service(),\\n            data=override,\\n        )\\n\\n    assert excinfo.value.status_code == 400\\n    assert \\\"restricted to administrators\\\" in excinfo.value.detail\\n    assert patch_build_flow[\\\"start_kwargs\\\"] is None\\n\\n\\n@pytest.mark.asyncio\\nasync def test_build_flow_admin_only_passes_sanitized_template_to_worker(patch_build_flow, monkeypatch):\\n    \\\"\\\"\\\"A known template remains usable, but the worker receives the server-trusted payload.\\\"\\\"\\\"\\n    from langflow.api.v1 import chat as chat_module\\n    from langflow.api.v1.schemas import FlowDataRequest\\n\\n    owner = _make_user()\\n    flow = _make_flow(owner_id=owner.id, public=False)\\n    patch_build_flow[\\\"read_flow\\\"] = flow\\n    override = FlowDataRequest(nodes=[{\\\"id\\\": \\\"known\\\", \\\"data\\\": {\\\"source\\\": \\\"request\\\"}}], edges=[])\\n    sanitized = {\\\"nodes\\\": [{\\\"id\\\": \\\"known\\\", \\\"data\\\": {\\\"source\\\": \\\"server\\\"}}], \\\"edges\\\": [], \\\"viewport\\\": None}\\n\\n    async def sanitize(_data, *, is_superuser):\\n        assert is_superuser is False\\n        return sanitized\\n\\n    monkeypatch.setattr(chat_module, \\\"prepare_flow_build_for_user\\\", sanitize)\\n\\n    result = await chat_module.build_flow(\\n        flow_id=flow.id,\\n        background_tasks=None,\\n        current_user=owner,\\n        queue_service=_make_queue_service(),\\n        data=override,\\n    )\\n\\n    assert result == {\\\"job_id\\\": \\\"fake-job-id\\\"}\\n    assert patch_build_flow[\\\"start_kwargs\\\"][\\\"data\\\"].model_dump() == sanitized\\n    assert override.nodes[0][\\\"data\\\"][\\\"source\\\"] == \\\"request\\\"\\n\\n\\n@pytest.mark.asyncio\\nasync def test_build_flow_admin_only_keeps_superuser_inline_custom_code(patch_build_flow, monkeypatch):\\n    \\\"\\\"\\\"The operator's admin-only setting preserves the documented superuser exception.\\\"\\\"\\\"\\n    from langflow.api.v1 import chat as chat_module\\n    from langflow.api.v1.schemas import FlowDataRequest\\n\\n    owner = _make_user(is_superuser=True)\\n    flow = _make_flow(owner_id=owner.id, public=False)\\n    patch_build_flow[\\\"read_flow\\\"] = flow\\n    override = FlowDataRequest(nodes=[{\\\"id\\\": \\\"custom\\\"}], edges=[])\\n    seen: dict[str, Any] = {}\\n\\n    async def preserve_superuser_data(data, *, is_superuser):\\n        assert is_superuser is True\\n        seen[\\\"validated\\\"] = data\\n\\n    monkeypatch.setattr(chat_module, \\\"prepare_flow_build_for_user\\\", preserve_superuser_data)\\n\\n    result = await chat_module.build_flow(\\n        flow_id=flow.id,\\n        background_tasks=None,\\n        current_user=owner,\\n        queue_service=_make_queue_service(),\\n        data=override,\\n    )\\n\\n    assert result == {\\\"job_id\\\": \\\"fake-job-id\\\"}\\n    assert seen[\\\"validated\\\"] == override.model_dump()\\n    assert patch_build_flow[\\\"start_kwargs\\\"][\\\"data\\\"] is override\\n\\n\\ndef _stored_graph(source: str) -> dict[str, Any]:\\n    \\\"\\\"\\\"A stored graph whose single node carries component source in the usual place.\\\"\\\"\\\"\\n    return {\\n        \\\"nodes\\\": [\\n            {\\n                \\\"id\\\": \\\"ChatInput-1\\\",\\n                \\\"data\\\": {\\n                    \\\"id\\\": \\\"ChatInput-1\\\",\\n                    \\\"type\\\": \\\"ChatInput\\\",\\n                    \\\"node\\\": {\\\"template\\\": {\\\"code\\\": {\\\"value\\\": source}}},\\n                },\\n            }\\n        ],\\n        \\\"edges\\\": [],\\n        \\\"viewport\\\": None,\\n    }\\n\\n\\n@pytest.mark.asyncio\\nasync def test_build_flow_admin_only_blocks_non_superuser_stored_custom_code(patch_build_flow, monkeypatch):\\n    \\\"\\\"\\\"Stored graph data must face the same caller-aware policy as inline request data.\\n\\n    A regular user could otherwise persist modified component source through the\\n    ordinary flow-write API and then execute it by building with an empty body,\\n    because the stored branch only ran the caller-agnostic global validator.\\n    \\\"\\\"\\\"\\n    from langflow.api.v1 import chat as chat_module\\n    from lfx.utils.flow_validation import CustomComponentValidationError\\n\\n    owner = _make_user()\\n    flow = _make_flow(owner_id=owner.id, public=False, data=_stored_graph(\\\"# attacker source\\\"))\\n    patch_build_flow[\\\"read_flow\\\"] = flow\\n    seen: dict[str, Any] = {}\\n\\n    async def reject_custom_code(data, *, is_superuser):\\n        seen[\\\"validated\\\"] = data\\n        assert is_superuser is False\\n        message = \\\"custom components are restricted to administrators\\\"\\n        raise CustomComponentValidationError(message)\\n\\n    monkeypatch.setattr(chat_module, \\\"prepare_flow_build_for_user\\\", reject_custom_code)\\n\\n    with pytest.raises(HTTPException) as excinfo:\\n        await chat_module.build_flow(\\n            flow_id=flow.id,\\n            background_tasks=None,\\n            current_user=owner,\\n            queue_service=_make_queue_service(),\\n        )\\n\\n    assert excinfo.value.status_code == 400\\n    assert \\\"restricted to administrators\\\" in excinfo.value.detail\\n    assert seen[\\\"validated\\\"] == flow.data\\n    assert patch_build_flow[\\\"start_kwargs\\\"] is None\\n\\n\\n@pytest.mark.asyncio\\nasync def test_build_flow_admin_only_passes_sanitized_stored_data_to_worker(patch_build_flow, monkeypatch):\\n    \\\"\\\"\\\"The worker must receive the server-trusted copy, not the stored bytes.\\\"\\\"\\\"\\n    from langflow.api.v1 import chat as chat_module\\n\\n    owner = _make_user()\\n    stored = _stored_graph(\\\"# stored source\\\")\\n    flow = _make_flow(owner_id=owner.id, public=False, data=stored)\\n    patch_build_flow[\\\"read_flow\\\"] = flow\\n    sanitized = _stored_graph(\\\"# trusted server source\\\")\\n\\n    async def sanitize(_data, *, is_superuser):\\n        assert is_superuser is False\\n        return sanitized\\n\\n    monkeypatch.setattr(chat_module, \\\"prepare_flow_build_for_user\\\", sanitize)\\n\\n    result = await chat_module.build_flow(\\n        flow_id=flow.id,\\n        background_tasks=None,\\n        current_user=owner,\\n        queue_service=_make_queue_service(),\\n    )\\n\\n    assert result == {\\\"job_id\\\": \\\"fake-job-id\\\"}\\n    forwarded = patch_build_flow[\\\"start_kwargs\\\"][\\\"data\\\"]\\n    assert forwarded is not None\\n    assert forwarded.model_dump()[\\\"nodes\\\"] == sanitized[\\\"nodes\\\"]\\n    # The stored row is never mutated by the sanitizer.\\n    assert flow.data[\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"code\\\"][\\\"value\\\"] == \\\"# stored source\\\"\\n\\n\\n@pytest.mark.asyncio\\nasync def test_build_flow_stored_data_permissive_policy_still_builds_from_db(patch_build_flow, monkeypatch):\\n    \\\"\\\"\\\"When no caller-aware restriction applies the build keeps loading from the DB.\\\"\\\"\\\"\\n    from langflow.api.v1 import chat as chat_module\\n\\n    owner = _make_user()\\n    flow = _make_flow(owner_id=owner.id, public=False, data=_stored_graph(\\\"# stored source\\\"))\\n    patch_build_flow[\\\"read_flow\\\"] = flow\\n    seen: dict[str, Any] = {}\\n\\n    async def permissive(data, *, is_superuser):\\n        seen[\\\"validated\\\"] = data\\n        assert is_superuser is False\\n\\n    monkeypatch.setattr(chat_module, \\\"prepare_flow_build_for_user\\\", permissive)\\n\\n    result = await chat_module.build_flow(\\n        flow_id=flow.id,\\n        background_tasks=None,\\n        current_user=owner,\\n        queue_service=_make_queue_service(),\\n    )\\n\\n    assert result == {\\\"job_id\\\": \\\"fake-job-id\\\"}\\n    assert seen[\\\"validated\\\"] == flow.data\\n    assert patch_build_flow[\\\"start_kwargs\\\"][\\\"data\\\"] is None\\n\\n\\n@pytest.mark.asyncio\\nasync def test_build_flow_admin_only_keeps_superuser_stored_custom_code(patch_build_flow, monkeypatch):\\n    \\\"\\\"\\\"Superusers keep the documented exception on the stored path too.\\\"\\\"\\\"\\n    from langflow.api.v1 import chat as chat_module\\n\\n    owner = _make_user(is_superuser=True)\\n    flow = _make_flow(owner_id=owner.id, public=False, data=_stored_graph(\\\"# admin source\\\"))\\n    patch_build_flow[\\\"read_flow\\\"] = flow\\n    seen: dict[str, Any] = {}\\n\\n    async def preserve_superuser_data(data, *, is_superuser):\\n        seen[\\\"validated\\\"] = data\\n        assert is_superuser is True\\n\\n    monkeypatch.setattr(chat_module, \\\"prepare_flow_build_for_user\\\", preserve_superuser_data)\\n\\n    result = await chat_module.build_flow(\\n        flow_id=flow.id,\\n        background_tasks=None,\\n        current_user=owner,\\n        queue_service=_make_queue_service(),\\n    )\\n\\n    assert result == {\\\"job_id\\\": \\\"fake-job-id\\\"}\\n    assert seen[\\\"validated\\\"] == flow.data\\n    assert patch_build_flow[\\\"start_kwargs\\\"][\\\"data\\\"] is None\\n\\n\\n@pytest.mark.asyncio\\nasync def test_legacy_vertices_route_passes_only_sanitized_inline_data(monkeypatch):\\n    \\\"\\\"\\\"The still-routed legacy graph cache cannot bypass the inline-data policy.\\\"\\\"\\\"\\n    from langflow.api.v1 import chat as chat_module\\n    from langflow.api.v1.schemas import FlowDataRequest\\n\\n    owner = _make_user()\\n    flow = _make_flow(owner_id=owner.id)\\n    original = FlowDataRequest(nodes=[{\\\"id\\\": \\\"known\\\", \\\"data\\\": {\\\"source\\\": \\\"request\\\"}}], edges=[])\\n    sanitized = {\\\"nodes\\\": [{\\\"id\\\": \\\"known\\\", \\\"data\\\": {\\\"source\\\": \\\"server\\\"}}], \\\"edges\\\": [], \\\"viewport\\\": None}\\n    seen: dict[str, Any] = {}\\n\\n    async def ensure_allowed(*_args, **_kwargs):\\n        return None\\n\\n    async def sanitize(_data, *, is_superuser):\\n        assert is_superuser is False\\n        return sanitized\\n\\n    graph = MagicMock()\\n    graph.prepare.return_value = graph\\n    graph.vertices = []\\n    graph.vertices_to_run = set()\\n    graph.first_layer = []\\n    graph.run_id = None\\n    graph.set_run_id.side_effect = lambda value: setattr(graph, \\\"run_id\\\", value)\\n\\n    async def build_from_data(*, graph_data, **_kwargs):\\n        seen[\\\"graph_data\\\"] = graph_data\\n        return graph\\n\\n    chat_service = SimpleNamespace(set_cache=AsyncMock())\\n    monkeypatch.setattr(chat_module, \\\"ensure_flow_permission\\\", ensure_allowed)\\n    monkeypatch.setattr(chat_module, \\\"prepare_flow_build_for_user\\\", sanitize)\\n    monkeypatch.setattr(chat_module, \\\"build_and_cache_graph_from_data\\\", build_from_data)\\n    monkeypatch.setattr(chat_module, \\\"get_chat_service\\\", lambda: chat_service)\\n    monkeypatch.setattr(chat_module, \\\"get_telemetry_service\\\", MagicMock)\\n    monkeypatch.setattr(chat_module, \\\"get_top_level_vertices\\\", lambda *_args: [])\\n\\n    await chat_module.retrieve_vertices_order(\\n        flow_id=flow.id,\\n        background_tasks=SimpleNamespace(add_task=lambda *_args, **_kwargs: None),\\n        data=original,\\n        session=_FakeSession([[flow]]),\\n        current_user=owner,\\n    )\\n\\n    assert seen[\\\"graph_data\\\"] == sanitized\\n    assert original.nodes[0][\\\"data\\\"][\\\"source\\\"] == \\\"request\\\"\\n\\n\\n@pytest.mark.asyncio\\nasync def test_build_flow_plugin_deny_returns_404_not_403(patch_build_flow):\\n    \\\"\\\"\\\"ensure_flow_permission raising 403 must surface as 404 (UUID privacy).\\\"\\\"\\\"\\n    from langflow.api.v1 import chat as chat_module\\n\\n    user = _make_user()\\n    # _read_flow finds the flow (cross-user-fetch enabled in plugin would do this)\\n    flow = _make_flow(owner_id=uuid4(), public=False)  # owned by someone else\\n    patch_build_flow[\\\"read_flow\\\"] = flow\\n    patch_build_flow[\\\"ensure_raises\\\"] = HTTPException(status_code=403, detail=\\\"forbidden\\\")\\n\\n    with pytest.raises(HTTPException) as excinfo:\\n        await chat_module.build_flow(\\n            flow_id=flow.id,\\n            background_tasks=None,\\n            current_user=user,\\n            queue_service=_make_queue_service(),\\n        )\\n    # Must be 404 \u2014 not 403 \u2014 so callers can't probe for resource existence.\\n    assert excinfo.value.status_code == 404\\n    assert f\\\"Flow with id {flow.id} not found\\\" in excinfo.value.detail\\n\\n\\n@pytest.mark.asyncio\\nasync def test_build_flow_unknown_flow_returns_404(patch_build_flow):\\n    \\\"\\\"\\\"Both share-aware and PUBLIC fallback miss \u2192 404 before plugin is consulted.\\\"\\\"\\\"\\n    from langflow.api.v1 import chat as chat_module\\n\\n    user = _make_user()\\n    flow_id = uuid4()\\n    patch_build_flow[\\\"read_flow\\\"] = None\\n    patch_build_flow[\\\"session_exec\\\"] = [[]]  # PUBLIC fallback also empty\\n\\n    with pytest.raises(HTTPException) as excinfo:\\n        await chat_module.build_flow(\\n            flow_id=flow_id,\\n            background_tasks=None,\\n            current_user=user,\\n            queue_service=_make_queue_service(),\\n        )\\n    assert excinfo.value.status_code == 404\\n\\n\\n@pytest.mark.asyncio\\nasync def test_build_flow_public_fallback_when_share_aware_misses(patch_build_flow):\\n    \\\"\\\"\\\"Plugin can't see the flow (returns None), but PUBLIC fallback finds it.\\\"\\\"\\\"\\n    from langflow.api.v1 import chat as chat_module\\n\\n    user = _make_user()\\n    owner_id = uuid4()\\n    public_flow = _make_flow(owner_id=owner_id, public=True)\\n    patch_build_flow[\\\"read_flow\\\"] = None  # share-aware load misses\\n    patch_build_flow[\\\"session_exec\\\"] = [[public_flow]]  # PUBLIC query hits\\n\\n    result = await chat_module.build_flow(\\n        flow_id=public_flow.id,\\n        background_tasks=None,\\n        current_user=user,\\n        queue_service=_make_queue_service(),\\n    )\\n    assert result == {\\\"job_id\\\": \\\"fake-job-id\\\"}\\n\\n\\n@pytest.mark.asyncio\\nasync def test_build_flow_non_403_exception_not_converted(patch_build_flow):\\n    \\\"\\\"\\\"A non-403 exception from ensure_flow_permission (e.g. 500) must pass through.\\\"\\\"\\\"\\n    from langflow.api.v1 import chat as chat_module\\n\\n    user = _make_user()\\n    flow = _make_flow(owner_id=user.id, public=False)\\n    patch_build_flow[\\\"read_flow\\\"] = flow\\n    # 500 from upstream \u2014 deny_to_404 only rewrites 403.\\n    patch_build_flow[\\\"ensure_raises\\\"] = HTTPException(status_code=500, detail=\\\"upstream\\\")\\n\\n    with pytest.raises(HTTPException) as excinfo:\\n        await chat_module.build_flow(\\n            flow_id=flow.id,\\n            background_tasks=None,\\n            current_user=user,\\n            queue_service=_make_queue_service(),\\n        )\\n    # deny_to_404 only converts 403; other status codes preserved (though detail\\n    # is sanitized to the supplied default).\\n    assert excinfo.value.status_code == 500\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/api/v1/test_flow_delete_concurrency.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3e0a94cf4eab14cb0195e3da6122ba5fe79f7d6b2fea63bd19c1fe8735291940\",\"content\":\"\\\"\\\"\\\"Only the request that removes a flow or version should report success.\\\"\\\"\\\"\\n\\nimport asyncio\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom fastapi import status\\nfrom httpx import AsyncClient\\nfrom langflow.api.v1 import flows\\nfrom langflow.services.database.models.flow_version import crud as version_crud\\n\\n\\nasync def test_delete_flow_returns_not_found_when_final_delete_matches_no_row(\\n    client: AsyncClient, logged_in_headers, monkeypatch\\n):\\n    \\\"\\\"\\\"A zero-row delete must return 404 even when the retry read found the flow.\\\"\\\"\\\"\\n    response = await client.post(\\n        \\\"api/v1/flows/\\\",\\n        json={\\\"name\\\": f\\\"delete-zero-rows-{uuid4()}\\\", \\\"data\\\": {}},\\n        headers=logged_in_headers,\\n    )\\n    assert response.status_code == status.HTTP_201_CREATED\\n    flow_id = response.json()[\\\"id\\\"]\\n\\n    async def matched_no_row(_session, _target_flow_id):\\n        # PostgreSQL can wait for a competing delete and then match zero rows\\n        # without the lock error that drives SQLite through a retry read.\\n        return False\\n\\n    monkeypatch.setattr(flows, \\\"cascade_delete_flow\\\", matched_no_row)\\n\\n    response = await client.delete(f\\\"api/v1/flows/{flow_id}\\\", headers=logged_in_headers)\\n\\n    assert response.status_code == status.HTTP_404_NOT_FOUND\\n    assert response.json() == {\\\"detail\\\": \\\"Flow not found\\\"}\\n\\n\\n@pytest.mark.parametrize(\\\"concurrent_deletions\\\", [0, 1, 2])\\nasync def test_bulk_delete_counts_only_rows_it_removes(\\n    client: AsyncClient, logged_in_headers, monkeypatch, concurrent_deletions\\n):\\n    \\\"\\\"\\\"Rows removed after the initial bulk query must not inflate the count.\\\"\\\"\\\"\\n    flow_ids = []\\n    for _ in range(2):\\n        response = await client.post(\\n            \\\"api/v1/flows/\\\",\\n            json={\\\"name\\\": f\\\"bulk-delete-zero-rows-{uuid4()}\\\", \\\"data\\\": {}},\\n            headers=logged_in_headers,\\n        )\\n        assert response.status_code == status.HTTP_201_CREATED\\n        flow_ids.append(response.json()[\\\"id\\\"])\\n    removed_by_competitor = set(flow_ids[:concurrent_deletions])\\n    original_delete = flows.cascade_delete_flow\\n    attempted_ids = []\\n\\n    async def delete_after_competing_requests(session, target_flow_id):\\n        attempted_ids.append(str(target_flow_id))\\n        if str(target_flow_id) in removed_by_competitor:\\n            return False\\n        return await original_delete(session, target_flow_id)\\n\\n    monkeypatch.setattr(flows, \\\"cascade_delete_flow\\\", delete_after_competing_requests)\\n\\n    response = await client.request(\\\"DELETE\\\", \\\"api/v1/flows/\\\", json=flow_ids, headers=logged_in_headers)\\n\\n    assert response.status_code == status.HTTP_200_OK\\n    assert response.json() == {\\\"deleted\\\": len(flow_ids) - concurrent_deletions}\\n    assert sorted(attempted_ids) == sorted(flow_ids)\\n\\n\\ndef _request_barrier(parties: int):\\n    ready = asyncio.Event()\\n    arrivals = 0\\n\\n    async def wait():\\n        nonlocal arrivals\\n        arrivals += 1\\n        if arrivals == parties:\\n            ready.set()\\n        await asyncio.wait_for(ready.wait(), timeout=10)\\n\\n    return wait\\n\\n\\nasync def test_concurrent_flow_deletes_report_one_success(client: AsyncClient, logged_in_headers, monkeypatch):\\n    response = await client.post(\\n        \\\"api/v1/flows/\\\",\\n        json={\\\"name\\\": f\\\"concurrent-delete-{uuid4()}\\\", \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}},\\n        headers=logged_in_headers,\\n    )\\n    assert response.status_code == status.HTTP_201_CREATED\\n    flow_id = response.json()[\\\"id\\\"]\\n    wait_for_requests = _request_barrier(4)\\n    original_read = flows._read_flow\\n\\n    async def read_before_competing_deletes(*args, **kwargs):\\n        flow = await original_read(*args, **kwargs)\\n        # Synchronize the initial reads; retries must read the committed result.\\n        await wait_for_requests()\\n        return flow\\n\\n    monkeypatch.setattr(flows, \\\"_read_flow\\\", read_before_competing_deletes)\\n    responses = await asyncio.gather(\\n        *(client.delete(f\\\"api/v1/flows/{flow_id}\\\", headers=logged_in_headers) for _ in range(4))\\n    )\\n\\n    assert sorted(response.status_code for response in responses) == [200, 404, 404, 404]\\n    for response in responses:\\n        if response.status_code == status.HTTP_200_OK:\\n            assert response.json() == {\\\"message\\\": \\\"Flow deleted successfully\\\"}\\n        else:\\n            assert response.json() == {\\\"detail\\\": \\\"Flow not found\\\"}\\n    assert (await client.get(f\\\"api/v1/flows/{flow_id}\\\", headers=logged_in_headers)).status_code == 404\\n\\n\\nasync def test_concurrent_version_deletes_report_one_success(client: AsyncClient, logged_in_headers, monkeypatch):\\n    response = await client.post(\\n        \\\"api/v1/flows/\\\",\\n        json={\\\"name\\\": f\\\"concurrent-version-delete-{uuid4()}\\\", \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}},\\n        headers=logged_in_headers,\\n    )\\n    assert response.status_code == status.HTTP_201_CREATED\\n    flow_id = response.json()[\\\"id\\\"]\\n    response = await client.post(f\\\"api/v1/flows/{flow_id}/versions/\\\", json={}, headers=logged_in_headers)\\n    assert response.status_code == status.HTTP_201_CREATED\\n    version_id = response.json()[\\\"id\\\"]\\n    wait_for_requests = _request_barrier(4)\\n    original_lock = version_crud.lock_flow_version_entry\\n\\n    async def lock_after_competing_requests_arrive(*args, **kwargs):\\n        # All requests must reach deletion before one acquires the database lock.\\n        await wait_for_requests()\\n        return await original_lock(*args, **kwargs)\\n\\n    monkeypatch.setattr(version_crud, \\\"lock_flow_version_entry\\\", lock_after_competing_requests_arrive)\\n    responses = await asyncio.gather(\\n        *(client.delete(f\\\"api/v1/flows/{flow_id}/versions/{version_id}\\\", headers=logged_in_headers) for _ in range(4))\\n    )\\n\\n    assert sorted(response.status_code for response in responses) == [204, 404, 404, 404]\\n    for response in responses:\\n        if response.status_code == status.HTTP_404_NOT_FOUND:\\n            assert response.json() == {\\\"detail\\\": f\\\"Version entry {version_id} not found\\\"}\\n    response = await client.get(f\\\"api/v1/flows/{flow_id}/versions/\\\", headers=logged_in_headers)\\n    assert response.status_code == status.HTTP_200_OK\\n    assert response.json()[\\\"entries\\\"] == []\\n    assert (await client.get(f\\\"api/v1/flows/{flow_id}\\\", headers=logged_in_headers)).status_code == 200\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/api/v1/test_flow_events.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"01f5d2481b26a4240013611b806cd8184753cf2caf5281c2b20d08397cef761c\",\"content\":\"from httpx import AsyncClient\\nfrom starlette import status\\n\\n\\nasync def _create_flow(client: AsyncClient, headers: dict) -> str:\\n    \\\"\\\"\\\"Create a minimal flow and return its id.\\\"\\\"\\\"\\n    response = await client.post(\\n        \\\"api/v1/flows/\\\",\\n        json={\\\"name\\\": \\\"event-test-flow\\\", \\\"data\\\": {}},\\n        headers=headers,\\n    )\\n    assert response.status_code == status.HTTP_201_CREATED\\n    return response.json()[\\\"id\\\"]\\n\\n\\nasync def test_create_and_get_flow_events(client: AsyncClient, logged_in_headers):\\n    flow_id = await _create_flow(client, logged_in_headers)\\n\\n    response = await client.post(\\n        f\\\"api/v1/flows/{flow_id}/events\\\",\\n        json={\\\"type\\\": \\\"component_added\\\", \\\"summary\\\": \\\"Added OpenAI\\\"},\\n        headers=logged_in_headers,\\n    )\\n    assert response.status_code == status.HTTP_201_CREATED\\n    event = response.json()\\n    assert event[\\\"type\\\"] == \\\"component_added\\\"\\n    assert event[\\\"summary\\\"] == \\\"Added OpenAI\\\"\\n    assert \\\"timestamp\\\" in event\\n\\n    response = await client.get(\\n        f\\\"api/v1/flows/{flow_id}/events\\\",\\n        params={\\\"since\\\": 0.0},\\n        headers=logged_in_headers,\\n    )\\n    assert response.status_code == status.HTTP_200_OK\\n    data = response.json()\\n    assert len(data[\\\"events\\\"]) == 1\\n    assert data[\\\"events\\\"][0][\\\"type\\\"] == \\\"component_added\\\"\\n    assert data[\\\"settled\\\"] is False\\n\\n\\nasync def test_get_events_cursor_based(client: AsyncClient, logged_in_headers):\\n    flow_id = await _create_flow(client, logged_in_headers)\\n\\n    r1 = await client.post(\\n        f\\\"api/v1/flows/{flow_id}/events\\\",\\n        json={\\\"type\\\": \\\"component_added\\\", \\\"summary\\\": \\\"First\\\"},\\n        headers=logged_in_headers,\\n    )\\n    first_ts = r1.json()[\\\"timestamp\\\"]\\n\\n    await client.post(\\n        f\\\"api/v1/flows/{flow_id}/events\\\",\\n        json={\\\"type\\\": \\\"connection_added\\\", \\\"summary\\\": \\\"Second\\\"},\\n        headers=logged_in_headers,\\n    )\\n\\n    response = await client.get(\\n        f\\\"api/v1/flows/{flow_id}/events\\\",\\n        params={\\\"since\\\": first_ts},\\n        headers=logged_in_headers,\\n    )\\n    data = response.json()\\n    assert len(data[\\\"events\\\"]) == 1\\n    assert data[\\\"events\\\"][0][\\\"summary\\\"] == \\\"Second\\\"\\n\\n\\nasync def test_settled_on_flow_settled_event(client: AsyncClient, logged_in_headers):\\n    flow_id = await _create_flow(client, logged_in_headers)\\n\\n    await client.post(\\n        f\\\"api/v1/flows/{flow_id}/events\\\",\\n        json={\\\"type\\\": \\\"component_added\\\", \\\"summary\\\": \\\"Added\\\"},\\n        headers=logged_in_headers,\\n    )\\n    await client.post(\\n        f\\\"api/v1/flows/{flow_id}/events\\\",\\n        json={\\\"type\\\": \\\"flow_settled\\\", \\\"summary\\\": \\\"Done\\\"},\\n        headers=logged_in_headers,\\n    )\\n\\n    response = await client.get(\\n        f\\\"api/v1/flows/{flow_id}/events\\\",\\n        params={\\\"since\\\": 0.0},\\n        headers=logged_in_headers,\\n    )\\n    data = response.json()\\n    assert data[\\\"settled\\\"] is True\\n\\n\\nasync def test_full_event_lifecycle(client: AsyncClient, logged_in_headers):\\n    \\\"\\\"\\\"Simulate: MCP emits events -> frontend polls -> detects settle.\\\"\\\"\\\"\\n    flow_id = await _create_flow(client, logged_in_headers)\\n\\n    await client.post(\\n        f\\\"api/v1/flows/{flow_id}/events\\\",\\n        json={\\\"type\\\": \\\"component_added\\\", \\\"summary\\\": \\\"Added OpenAI\\\"},\\n        headers=logged_in_headers,\\n    )\\n    await client.post(\\n        f\\\"api/v1/flows/{flow_id}/events\\\",\\n        json={\\\"type\\\": \\\"connection_added\\\", \\\"summary\\\": \\\"Connected to Chat Output\\\"},\\n        headers=logged_in_headers,\\n    )\\n\\n    response = await client.get(\\n        f\\\"api/v1/flows/{flow_id}/events\\\",\\n        params={\\\"since\\\": 0.0},\\n        headers=logged_in_headers,\\n    )\\n    data = response.json()\\n    assert len(data[\\\"events\\\"]) == 2\\n    assert data[\\\"settled\\\"] is False\\n\\n    await client.post(\\n        f\\\"api/v1/flows/{flow_id}/events\\\",\\n        json={\\\"type\\\": \\\"flow_settled\\\", \\\"summary\\\": \\\"Built a RAG pipeline\\\"},\\n        headers=logged_in_headers,\\n    )\\n\\n    response = await client.get(\\n        f\\\"api/v1/flows/{flow_id}/events\\\",\\n        params={\\\"since\\\": 0.0},\\n        headers=logged_in_headers,\\n    )\\n    data = response.json()\\n    assert len(data[\\\"events\\\"]) == 3\\n    assert data[\\\"settled\\\"] is True\\n    assert any(e[\\\"type\\\"] == \\\"flow_settled\\\" for e in data[\\\"events\\\"])\\n\\n\\nasync def test_nonexistent_flow_returns_404(client: AsyncClient, logged_in_headers):\\n    fake_id = \\\"00000000-0000-0000-0000-000000000000\\\"\\n\\n    response = await client.get(\\n        f\\\"api/v1/flows/{fake_id}/events\\\",\\n        params={\\\"since\\\": 0.0},\\n        headers=logged_in_headers,\\n    )\\n    assert response.status_code == status.HTTP_404_NOT_FOUND\\n\\n    response = await client.post(\\n        f\\\"api/v1/flows/{fake_id}/events\\\",\\n        json={\\\"type\\\": \\\"component_added\\\", \\\"summary\\\": \\\"Should fail\\\"},\\n        headers=logged_in_headers,\\n    )\\n    assert response.status_code == status.HTTP_404_NOT_FOUND\\n\\n\\nasync def test_invalid_event_type_returns_422(client: AsyncClient, logged_in_headers):\\n    flow_id = await _create_flow(client, logged_in_headers)\\n\\n    response = await client.post(\\n        f\\\"api/v1/flows/{flow_id}/events\\\",\\n        json={\\\"type\\\": \\\"invalid_type\\\", \\\"summary\\\": \\\"bad event\\\"},\\n        headers=logged_in_headers,\\n    )\\n    assert response.status_code == status.HTTP_422_UNPROCESSABLE_CONTENT\\n\\n\\nasync def test_missing_event_type_returns_422(client: AsyncClient, logged_in_headers):\\n    flow_id = await _create_flow(client, logged_in_headers)\\n\\n    response = await client.post(\\n        f\\\"api/v1/flows/{flow_id}/events\\\",\\n        json={\\\"summary\\\": \\\"no type field\\\"},\\n        headers=logged_in_headers,\\n    )\\n    assert response.status_code == status.HTTP_422_UNPROCESSABLE_CONTENT\\n\\n\\nasync def test_summary_max_length_returns_422(client: AsyncClient, logged_in_headers):\\n    flow_id = await _create_flow(client, logged_in_headers)\\n\\n    response = await client.post(\\n        f\\\"api/v1/flows/{flow_id}/events\\\",\\n        json={\\\"type\\\": \\\"component_added\\\", \\\"summary\\\": \\\"x\\\" * 501},\\n        headers=logged_in_headers,\\n    )\\n    assert response.status_code == status.HTTP_422_UNPROCESSABLE_CONTENT\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/api/v1/test_flow_folder_integrity.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b3adbd5db086903620935f70a60ff2bc28fbf0d04e4080244d65bd2a59b6e96f\",\"content\":\"\\\"\\\"\\\"Tests for flow-folder integrity to prevent orphaned flows.\\n\\nThese tests verify the fix for the bug where flows could be created without a valid folder_id\\nwhen all folders were deleted (zero folders scenario), resulting in orphaned flows that were\\nunreachable in the UI.\\n\\nThe fix ensures:\\n1. Flows always have a valid folder_id\\n2. If a non-existent folder_id is provided, the system falls back to the default folder\\n3. If no folders exist, a default folder is auto-created\\n\\\"\\\"\\\"\\n\\nimport json\\nimport uuid\\nfrom unittest.mock import AsyncMock\\n\\nfrom fastapi import status\\nfrom httpx import AsyncClient\\nfrom langflow.api.v1 import authz_route_dependencies, flows\\nfrom langflow.services.database.models.flow.model import Flow\\nfrom langflow.services.database.models.folder.constants import DEFAULT_FOLDER_NAME\\nfrom langflow.services.database.models.folder.model import Folder\\nfrom langflow.services.database.models.folder.utils import create_default_folder_if_it_doesnt_exist\\nfrom langflow.services.deps import session_scope\\nfrom sqlmodel import select\\n\\n\\nasync def test_create_flow_with_nonexistent_folder_id_assigns_default_folder(\\n    client: AsyncClient, logged_in_headers, active_user\\n):\\n    \\\"\\\"\\\"Test that creating a flow with a non-existent folder_id assigns it to the default folder.\\n\\n    This prevents orphaned flows when a folder is deleted between the UI loading and flow creation.\\n    \\\"\\\"\\\"\\n    non_existent_folder_id = str(uuid.uuid4())\\n\\n    flow_data = {\\n        \\\"name\\\": \\\"Test Flow with Bad Folder\\\",\\n        \\\"data\\\": {},\\n        \\\"folder_id\\\": non_existent_folder_id,\\n    }\\n\\n    response = await client.post(\\\"api/v1/flows/\\\", json=flow_data, headers=logged_in_headers)\\n\\n    assert response.status_code == status.HTTP_201_CREATED\\n    result = response.json()\\n\\n    # The flow should have been assigned to a valid folder (not the non-existent one)\\n    assert result[\\\"folder_id\\\"] is not None\\n    assert result[\\\"folder_id\\\"] != non_existent_folder_id\\n\\n    # Verify the folder actually exists\\n    async with session_scope() as session:\\n        folder = await session.get(Folder, uuid.UUID(result[\\\"folder_id\\\"]))\\n        assert folder is not None\\n        assert folder.user_id == active_user.id\\n\\n\\nasync def test_single_create_authorizes_canonical_default_destination(\\n    client: AsyncClient,\\n    logged_in_headers,\\n    active_user,\\n    monkeypatch,\\n):\\n    \\\"\\\"\\\"A stale caller scope cannot authorize one workspace and write another.\\\"\\\"\\\"\\n    guard = AsyncMock()\\n    monkeypatch.setattr(authz_route_dependencies, \\\"ensure_flow_permission\\\", guard)\\n    spoofed_workspace_id = uuid.uuid4()\\n\\n    response = await client.post(\\n        \\\"api/v1/flows/\\\",\\n        json={\\n            \\\"name\\\": \\\"Canonical single create\\\",\\n            \\\"data\\\": {},\\n            \\\"folder_id\\\": str(uuid.uuid4()),\\n            \\\"workspace_id\\\": str(spoofed_workspace_id),\\n        },\\n        headers=logged_in_headers,\\n    )\\n\\n    assert response.status_code == status.HTTP_201_CREATED\\n    created = response.json()\\n    async with session_scope() as session:\\n        folder = await session.get(Folder, uuid.UUID(created[\\\"folder_id\\\"]))\\n    assert folder is not None\\n    assert folder.user_id == active_user.id\\n    assert folder.workspace_id != spoofed_workspace_id\\n    guard.assert_awaited_once()\\n    assert guard.await_args.kwargs[\\\"folder_id\\\"] == folder.id\\n    assert guard.await_args.kwargs[\\\"workspace_id\\\"] == folder.workspace_id\\n\\n\\nasync def test_batch_and_upload_authorize_their_canonical_default_destinations(\\n    client: AsyncClient,\\n    logged_in_headers,\\n    active_user,\\n    monkeypatch,\\n):\\n    \\\"\\\"\\\"Batch and upload checks use the same tuple later persisted.\\\"\\\"\\\"\\n    guard = AsyncMock()\\n    monkeypatch.setattr(flows, \\\"ensure_flow_permission\\\", guard)\\n    spoofed_workspace_id = uuid.uuid4()\\n    stale_folder_id = uuid.uuid4()\\n\\n    batch_response = await client.post(\\n        \\\"api/v1/flows/batch/\\\",\\n        json={\\n            \\\"flows\\\": [\\n                {\\n                    \\\"name\\\": \\\"Canonical batch create\\\",\\n                    \\\"data\\\": {},\\n                    \\\"folder_id\\\": str(stale_folder_id),\\n                    \\\"workspace_id\\\": str(spoofed_workspace_id),\\n                }\\n            ]\\n        },\\n        headers=logged_in_headers,\\n    )\\n    upload_response = await client.post(\\n        \\\"api/v1/flows/upload/\\\",\\n        files={\\n            \\\"file\\\": (\\n                \\\"canonical-upload.json\\\",\\n                json.dumps(\\n                    {\\n                        \\\"name\\\": \\\"Canonical upload create\\\",\\n                        \\\"data\\\": {},\\n                        \\\"folder_id\\\": str(stale_folder_id),\\n                        \\\"workspace_id\\\": str(spoofed_workspace_id),\\n                    }\\n                ),\\n                \\\"application/json\\\",\\n            )\\n        },\\n        headers=logged_in_headers,\\n    )\\n\\n    assert batch_response.status_code == status.HTTP_201_CREATED\\n    assert upload_response.status_code == status.HTTP_201_CREATED\\n    created = [batch_response.json()[0], upload_response.json()[0]]\\n    assert guard.await_count == 2\\n    for item, call in zip(created, guard.await_args_list, strict=True):\\n        async with session_scope() as session:\\n            folder = await session.get(Folder, uuid.UUID(item[\\\"folder_id\\\"]))\\n        assert folder is not None\\n        assert folder.user_id == active_user.id\\n        assert folder.workspace_id != spoofed_workspace_id\\n        assert call.kwargs[\\\"folder_id\\\"] == folder.id\\n        assert call.kwargs[\\\"workspace_id\\\"] == folder.workspace_id\\n\\n\\nasync def test_create_flow_without_folder_id_assigns_default_folder(\\n    client: AsyncClient, logged_in_headers, active_user\\n):\\n    \\\"\\\"\\\"Test that creating a flow without a folder_id assigns it to the default folder.\\\"\\\"\\\"\\n    flow_data = {\\n        \\\"name\\\": \\\"Test Flow without Folder ID\\\",\\n        \\\"data\\\": {},\\n    }\\n\\n    response = await client.post(\\\"api/v1/flows/\\\", json=flow_data, headers=logged_in_headers)\\n\\n    assert response.status_code == status.HTTP_201_CREATED\\n    result = response.json()\\n\\n    # The flow should have been assigned to a valid folder\\n    assert result[\\\"folder_id\\\"] is not None\\n\\n    # Verify the folder actually exists and belongs to the user\\n    async with session_scope() as session:\\n        folder = await session.get(Folder, uuid.UUID(result[\\\"folder_id\\\"]))\\n        assert folder is not None\\n        assert folder.user_id == active_user.id\\n\\n\\nasync def test_create_flow_after_all_folders_deleted_creates_default_folder(\\n    client: AsyncClient, logged_in_headers, active_user\\n):\\n    \\\"\\\"\\\"Test the zero-folder scenario: creating a flow after deleting all folders.\\n\\n    This is the critical bug fix test. When all folders are deleted, creating a new flow\\n    should automatically create a default folder instead of creating an orphaned flow.\\n    \\\"\\\"\\\"\\n    # First, delete all folders for this user\\n    async with session_scope() as session:\\n        stmt = select(Folder).where(Folder.user_id == active_user.id)\\n        folders = (await session.exec(stmt)).all()\\n        for folder in folders:\\n            await session.delete(folder)\\n        await session.commit()\\n\\n    # Verify no folders exist for this user\\n    async with session_scope() as session:\\n        stmt = select(Folder).where(Folder.user_id == active_user.id)\\n        folders = (await session.exec(stmt)).all()\\n        assert len(folders) == 0, \\\"All folders should be deleted\\\"\\n\\n    # Now create a flow - this should auto-create a default folder\\n    flow_data = {\\n        \\\"name\\\": \\\"Flow Created After All Folders Deleted\\\",\\n        \\\"data\\\": {},\\n    }\\n\\n    response = await client.post(\\\"api/v1/flows/\\\", json=flow_data, headers=logged_in_headers)\\n\\n    assert response.status_code == status.HTTP_201_CREATED\\n    result = response.json()\\n\\n    # The flow should NOT be orphaned - it should have a valid folder_id\\n    assert result[\\\"folder_id\\\"] is not None\\n\\n    # Verify the folder was auto-created and exists\\n    async with session_scope() as session:\\n        folder = await session.get(Folder, uuid.UUID(result[\\\"folder_id\\\"]))\\n        assert folder is not None\\n        assert folder.user_id == active_user.id\\n        assert folder.name == DEFAULT_FOLDER_NAME\\n\\n\\nasync def test_default_folder_creation_adopts_existing_orphaned_flow(active_user):\\n    \\\"\\\"\\\"Creating a default folder assigns orphaned flows to that folder.\\\"\\\"\\\"\\n    async with session_scope() as session:\\n        folders = (await session.exec(select(Folder).where(Folder.user_id == active_user.id))).all()\\n        for folder in folders:\\n            await session.delete(folder)\\n        await session.commit()\\n\\n        orphan = Flow(name=\\\"Existing orphaned flow\\\", data={}, user_id=active_user.id)\\n        session.add(orphan)\\n        await session.commit()\\n        await session.refresh(orphan)\\n        orphan_id = orphan.id\\n\\n    async with session_scope() as session:\\n        folder = await create_default_folder_if_it_doesnt_exist(session, active_user.id)\\n        await session.commit()\\n        folder_id = folder.id\\n        workspace_id = folder.workspace_id\\n        adopted_flow = await session.get(Flow, orphan_id)\\n\\n    assert adopted_flow is not None\\n    assert adopted_flow.folder_id == folder_id\\n    assert adopted_flow.workspace_id == workspace_id\\n\\n\\nasync def test_update_flow_with_nonexistent_folder_id_assigns_default_folder(\\n    client: AsyncClient, logged_in_headers, active_user\\n):\\n    \\\"\\\"\\\"Test that updating a flow with a non-existent folder_id falls back to default folder.\\n\\n    This handles the case where a user tries to move a flow to a folder that doesn't exist.\\n    \\\"\\\"\\\"\\n    # Configure client to follow redirects (folders API uses redirects)\\n    client.follow_redirects = True\\n\\n    # Create a flow in the default folder\\n    flow_data = {\\n        \\\"name\\\": \\\"Flow to Update\\\",\\n        \\\"data\\\": {},\\n    }\\n    flow_response = await client.post(\\\"api/v1/flows/\\\", json=flow_data, headers=logged_in_headers)\\n    assert flow_response.status_code == status.HTTP_201_CREATED\\n    flow_id = flow_response.json()[\\\"id\\\"]\\n\\n    # Now try to update the flow with a non-existent folder_id\\n    non_existent_folder_id = str(uuid.uuid4())\\n    update_data = {\\n        \\\"name\\\": \\\"Updated Flow Name\\\",\\n        \\\"folder_id\\\": non_existent_folder_id,  # This folder doesn't exist\\n    }\\n\\n    update_response = await client.patch(f\\\"api/v1/flows/{flow_id}\\\", json=update_data, headers=logged_in_headers)\\n\\n    assert update_response.status_code == status.HTTP_200_OK\\n    result = update_response.json()\\n\\n    # The flow should be reassigned to a valid folder (not the non-existent one)\\n    assert result[\\\"folder_id\\\"] is not None\\n    assert result[\\\"folder_id\\\"] != non_existent_folder_id\\n\\n    # Verify the folder exists\\n    async with session_scope() as session:\\n        folder = await session.get(Folder, uuid.UUID(result[\\\"folder_id\\\"]))\\n        assert folder is not None\\n        assert folder.user_id == active_user.id\\n\\n\\nasync def test_update_authorizes_workspace_derived_from_destination_folder(\\n    client: AsyncClient,\\n    logged_in_headers,\\n    active_user,\\n    monkeypatch,\\n):\\n    \\\"\\\"\\\"A move cannot use a spoofed workspace that disagrees with its project.\\\"\\\"\\\"\\n    flow_response = await client.post(\\n        \\\"api/v1/flows/\\\",\\n        json={\\\"name\\\": \\\"Canonical move source\\\", \\\"data\\\": {}},\\n        headers=logged_in_headers,\\n    )\\n    assert flow_response.status_code == status.HTTP_201_CREATED\\n    target_workspace_id = uuid.uuid4()\\n    spoofed_workspace_id = uuid.uuid4()\\n    async with session_scope() as session:\\n        target_folder = Folder(\\n            name=\\\"Canonical move target\\\",\\n            user_id=active_user.id,\\n            workspace_id=target_workspace_id,\\n        )\\n        session.add(target_folder)\\n        await session.commit()\\n        await session.refresh(target_folder)\\n        target_folder_id = target_folder.id\\n\\n    guard = AsyncMock()\\n    monkeypatch.setattr(flows, \\\"ensure_flow_permission\\\", guard)\\n    update_response = await client.patch(\\n        f\\\"api/v1/flows/{flow_response.json()['id']}\\\",\\n        json={\\n            \\\"folder_id\\\": str(target_folder_id),\\n            \\\"workspace_id\\\": str(spoofed_workspace_id),\\n        },\\n        headers=logged_in_headers,\\n    )\\n\\n    assert update_response.status_code == status.HTTP_200_OK\\n    assert update_response.json()[\\\"folder_id\\\"] == str(target_folder_id)\\n    assert update_response.json()[\\\"workspace_id\\\"] == str(target_workspace_id)\\n    destination_calls = [call for call in guard.await_args_list if call.kwargs.get(\\\"folder_id\\\") == target_folder_id]\\n    assert destination_calls\\n    assert all(call.kwargs[\\\"workspace_id\\\"] == target_workspace_id for call in destination_calls)\\n    assert all(call.kwargs[\\\"workspace_id\\\"] != spoofed_workspace_id for call in destination_calls)\\n\\n\\nasync def test_update_flow_without_folder_id_keeps_existing_folder(client: AsyncClient, logged_in_headers):\\n    \\\"\\\"\\\"Test that updating a flow without specifying folder_id keeps the existing folder assignment.\\\"\\\"\\\"\\n    # Configure client to follow redirects\\n    client.follow_redirects = True\\n\\n    # Create a flow\\n    flow_data = {\\n        \\\"name\\\": \\\"Flow to Update\\\",\\n        \\\"data\\\": {},\\n    }\\n    create_response = await client.post(\\\"api/v1/flows/\\\", json=flow_data, headers=logged_in_headers)\\n    assert create_response.status_code == status.HTTP_201_CREATED\\n    flow_id = create_response.json()[\\\"id\\\"]\\n    original_folder_id = create_response.json()[\\\"folder_id\\\"]\\n\\n    # Update the flow without specifying folder_id (only update name)\\n    update_data = {\\n        \\\"name\\\": \\\"Updated Flow Name\\\",\\n    }\\n\\n    update_response = await client.patch(f\\\"api/v1/flows/{flow_id}\\\", json=update_data, headers=logged_in_headers)\\n\\n    assert update_response.status_code == status.HTTP_200_OK\\n    result = update_response.json()\\n\\n    # The folder_id should remain unchanged\\n    assert result[\\\"folder_id\\\"] == original_folder_id\\n\\n\\nasync def test_upload_flow_with_nonexistent_folder_id_assigns_default(\\n    client: AsyncClient, logged_in_headers, active_user\\n):\\n    \\\"\\\"\\\"Test that uploading a flow with a non-existent folder_id assigns it to the default folder.\\n\\n    The upload endpoint uses _new_flow internally, which includes folder_id validation.\\n    \\\"\\\"\\\"\\n    import json\\n\\n    non_existent_folder_id = str(uuid.uuid4())\\n\\n    flow_data = {\\n        \\\"name\\\": \\\"Uploaded Flow with Bad Folder\\\",\\n        \\\"data\\\": {},\\n        \\\"folder_id\\\": non_existent_folder_id,\\n    }\\n\\n    # Create a JSON file content for upload\\n    file_content = json.dumps(flow_data)\\n\\n    response = await client.post(\\n        \\\"api/v1/flows/upload/\\\",\\n        files={\\\"file\\\": (\\\"flow.json\\\", file_content, \\\"application/json\\\")},\\n        headers=logged_in_headers,\\n    )\\n\\n    assert response.status_code == status.HTTP_201_CREATED\\n    results = response.json()\\n\\n    # The result is a list (even for single flow upload)\\n    assert len(results) == 1\\n    result = results[0]\\n\\n    # The flow should have a valid folder_id (not the non-existent one)\\n    assert result[\\\"folder_id\\\"] is not None\\n    assert result[\\\"folder_id\\\"] != non_existent_folder_id\\n\\n    # Verify the folder exists\\n    async with session_scope() as session:\\n        folder = await session.get(Folder, uuid.UUID(result[\\\"folder_id\\\"]))\\n        assert folder is not None\\n        assert folder.user_id == active_user.id\\n\\n\\nasync def test_flow_created_is_retrievable_in_folder(client: AsyncClient, logged_in_headers):\\n    \\\"\\\"\\\"Test that a created flow can be retrieved by listing flows in its folder.\\n\\n    This verifies the flow is not orphaned and appears in the UI.\\n    \\\"\\\"\\\"\\n    # Configure client to follow redirects\\n    client.follow_redirects = True\\n\\n    # Create a flow\\n    flow_data = {\\n        \\\"name\\\": \\\"Retrievable Flow\\\",\\n        \\\"data\\\": {},\\n    }\\n    create_response = await client.post(\\\"api/v1/flows/\\\", json=flow_data, headers=logged_in_headers)\\n    assert create_response.status_code == status.HTTP_201_CREATED\\n    flow_id = create_response.json()[\\\"id\\\"]\\n    folder_id = create_response.json()[\\\"folder_id\\\"]\\n\\n    # List flows in the folder\\n    response = await client.get(f\\\"api/v1/folders/{folder_id}\\\", headers=logged_in_headers)\\n    assert response.status_code == status.HTTP_200_OK\\n\\n    # Check if the flow is in the folder's flows list\\n    result = response.json()\\n    # Handle different response structures\\n    if \\\"flows\\\" in result:\\n        flows = result[\\\"flows\\\"]\\n    elif \\\"folder\\\" in result and \\\"flows\\\" in result[\\\"folder\\\"]:\\n        flows = result[\\\"folder\\\"][\\\"flows\\\"]\\n    else:\\n        # Response might be paginated or have different structure\\n        flows = result.get(\\\"flows\\\", [])\\n\\n    # Get flow IDs from the response\\n    flow_ids_in_folder = [f[\\\"id\\\"] if isinstance(f, dict) else str(f) for f in flows]\\n\\n    # The created flow should be in the folder's flow list\\n    assert flow_id in flow_ids_in_folder, f\\\"Flow {flow_id} should be retrievable in folder {folder_id}\\\"\\n\\n\\nasync def test_upsert_flow_with_nonexistent_folder_id_on_create(client: AsyncClient, logged_in_headers):\\n    \\\"\\\"\\\"Test that PUT (upsert) with non-existent folder_id creates flow with default folder.\\\"\\\"\\\"\\n    specified_id = str(uuid.uuid4())\\n    non_existent_folder_id = str(uuid.uuid4())\\n\\n    flow_data = {\\n        \\\"name\\\": \\\"Upsert Flow with Bad Folder\\\",\\n        \\\"data\\\": {},\\n        \\\"folder_id\\\": non_existent_folder_id,\\n    }\\n\\n    response = await client.put(f\\\"api/v1/flows/{specified_id}\\\", json=flow_data, headers=logged_in_headers)\\n\\n    # The request should be rejected with 400 Bad Request since folder doesn't exist\\n    # This is the expected behavior based on the existing test_upsert_flow_returns_400_for_invalid_folder_id\\n    assert response.status_code == status.HTTP_400_BAD_REQUEST\\n    assert \\\"folder not found\\\" in response.json()[\\\"detail\\\"].lower()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/api/v1/test_flow_secret_write_refusal.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"cfdad1fd904e067d98c5e7dcd496eda1dfc4adc6241cb456273443f31ef02fb6\",\"content\":\"\\\"\\\"\\\"A credential that cannot be stored securely must fail the flow write, visibly.\\n\\nThe refusal only protects anything if it reaches the caller. Every write path wraps the\\nscrub in broad exception handling, so this drives the real routes over HTTP and asserts\\nboth halves: the request fails, and the secret is not in the flow that came back.\\n\\\"\\\"\\\"\\n\\nimport json\\n\\nimport pytest\\nfrom fastapi import status\\nfrom httpx import AsyncClient\\n\\nSECRET = \\\"sk-must-never-be-persisted\\\"  # noqa: S105\\n\\n\\ndef _flow_with_mcp_secret(name: str) -> dict:\\n    return {\\n        \\\"name\\\": name,\\n        \\\"description\\\": \\\"carries an MCP credential\\\",\\n        \\\"data\\\": {\\n            \\\"nodes\\\": [\\n                {\\n                    \\\"id\\\": \\\"MCPTools-1\\\",\\n                    \\\"data\\\": {\\n                        \\\"id\\\": \\\"MCPTools-1\\\",\\n                        \\\"type\\\": \\\"MCPTools\\\",\\n                        \\\"node\\\": {\\n                            \\\"template\\\": {\\n                                \\\"mcp_server\\\": {\\n                                    \\\"value\\\": {\\n                                        \\\"name\\\": \\\"billing\\\",\\n                                        \\\"config\\\": {\\n                                            \\\"url\\\": \\\"https://billing.example/mcp\\\",\\n                                            \\\"headers\\\": {\\\"x-api-key\\\": SECRET},\\n                                        },\\n                                    }\\n                                }\\n                            }\\n                        },\\n                    },\\n                }\\n            ],\\n            \\\"edges\\\": [],\\n        },\\n    }\\n\\n\\n@pytest.fixture\\ndef unstorable_variables(monkeypatch):\\n    \\\"\\\"\\\"Every generated variable fails for a reason a retry cannot fix.\\\"\\\"\\\"\\n    import langflow.api.utils.mcp.flow_secrets as module\\n\\n    async def failing_ensure(variables, user_id, session):  # noqa: ARG001\\n        return set(variables)\\n\\n    monkeypatch.setattr(module, \\\"_ensure_variables\\\", failing_ensure)\\n\\n\\n@pytest.mark.usefixtures(\\\"unstorable_variables\\\")\\nasync def test_create_flow_should_fail_instead_of_storing_the_secret(client: AsyncClient, logged_in_headers: dict):\\n    response = await client.post(\\n        \\\"api/v1/flows/\\\", json=_flow_with_mcp_secret(\\\"refuse-create\\\"), headers=logged_in_headers\\n    )\\n\\n    assert response.status_code == status.HTTP_500_INTERNAL_SERVER_ERROR\\n    assert SECRET not in response.text\\n\\n\\n@pytest.mark.usefixtures(\\\"unstorable_variables\\\")\\nasync def test_batch_create_should_fail_instead_of_storing_the_secret(client: AsyncClient, logged_in_headers: dict):\\n    payload = {\\\"flows\\\": [_flow_with_mcp_secret(\\\"refuse-batch\\\")]}\\n\\n    response = await client.post(\\\"api/v1/flows/batch/\\\", json=payload, headers=logged_in_headers)\\n\\n    assert response.status_code == status.HTTP_500_INTERNAL_SERVER_ERROR\\n    assert SECRET not in response.text\\n\\n\\nasync def test_create_flow_should_succeed_and_scrub_when_the_variable_is_storable(\\n    client: AsyncClient, logged_in_headers: dict\\n):\\n    \\\"\\\"\\\"The refusal must not fire on the happy path: the secret moves out, the flow saves.\\\"\\\"\\\"\\n    response = await client.post(\\\"api/v1/flows/\\\", json=_flow_with_mcp_secret(\\\"scrub-ok\\\"), headers=logged_in_headers)\\n\\n    assert response.status_code == status.HTTP_201_CREATED\\n    body = response.json()\\n    assert SECRET not in json.dumps(body[\\\"data\\\"])\\n    header_value = body[\\\"data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"mcp_server\\\"][\\\"value\\\"][\\\"config\\\"][\\\"headers\\\"][\\n        \\\"x-api-key\\\"\\n    ]\\n    assert header_value.startswith(\\\"MCP_\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/api/v1/test_flow_version.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"ac5310637cd1f562e593f6315f9062e5ebdf8654583cc2b55598965fdb674cb5\",\"content\":\"\\\"\\\"\\\"Tests for the Flow Versions API endpoints.\\n\\nTests cover:\\n- Creating snapshots\\n- Listing version entries\\n- Getting a single version entry with full data\\n- Activating a version (auto-snapshot, overwrite)\\n- Deleting version entries\\n- Edge cases: empty versions, nonexistent IDs, cross-user isolation\\n- Cascade deletion when the parent flow is deleted\\n- Realistic data payloads using starter project JSON\\n\\\"\\\"\\\"\\n\\nimport json\\nfrom types import SimpleNamespace\\n\\nimport pytest\\nfrom fastapi import status\\nfrom httpx import AsyncClient\\nfrom lfx.services.catalog_policy import CatalogPolicySnapshot\\n\\n# ---------------------------------------------------------------------------\\n# Helpers\\n# ---------------------------------------------------------------------------\\n\\n\\nasync def _create_flow(client: AsyncClient, headers: dict, name: str = \\\"version-test-flow\\\") -> dict:\\n    \\\"\\\"\\\"Create a minimal flow and return the JSON response.\\\"\\\"\\\"\\n    payload = {\\n        \\\"name\\\": name,\\n        \\\"description\\\": \\\"flow for version tests\\\",\\n        \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []},\\n        \\\"is_component\\\": False,\\n    }\\n    resp = await client.post(\\\"api/v1/flows/\\\", json=payload, headers=headers)\\n    assert resp.status_code == status.HTTP_201_CREATED\\n    return resp.json()\\n\\n\\nasync def _create_snapshot(client: AsyncClient, headers: dict, flow_id: str, description: str | None = None) -> dict:\\n    \\\"\\\"\\\"POST a snapshot and return the JSON response.\\\"\\\"\\\"\\n    body = {\\\"description\\\": description} if description else {}\\n    resp = await client.post(f\\\"api/v1/flows/{flow_id}/versions/\\\", json=body, headers=headers)\\n    assert resp.status_code == status.HTTP_201_CREATED\\n    return resp.json()\\n\\n\\nasync def _list_versions(client: AsyncClient, headers: dict, flow_id: str, *, params: dict | None = None) -> list[dict]:\\n    resp = await client.get(f\\\"api/v1/flows/{flow_id}/versions/\\\", headers=headers, params=params)\\n    assert resp.status_code == status.HTTP_200_OK\\n    body = resp.json()\\n    assert \\\"entries\\\" in body\\n    assert \\\"max_entries\\\" in body\\n    return body[\\\"entries\\\"]\\n\\n\\nasync def _patch_flow_data(client: AsyncClient, headers: dict, flow_id: str, data: dict) -> dict:\\n    \\\"\\\"\\\"PATCH the flow to change its data (simulates canvas auto-save).\\\"\\\"\\\"\\n    resp = await client.patch(f\\\"api/v1/flows/{flow_id}\\\", json={\\\"data\\\": data}, headers=headers)\\n    assert resp.status_code == status.HTTP_200_OK\\n    return resp.json()\\n\\n\\ndef _set_deployments_feature_flag(monkeypatch: pytest.MonkeyPatch, *, enabled: bool) -> None:\\n    from lfx.services.settings.feature_flags import FEATURE_FLAGS\\n\\n    monkeypatch.setattr(FEATURE_FLAGS, \\\"wxo_deployments\\\", enabled)\\n\\n\\n# ---------------------------------------------------------------------------\\n# Basic CRUD\\n# ---------------------------------------------------------------------------\\n\\n\\nasync def test_create_snapshot(client: AsyncClient, logged_in_headers):\\n    flow = await _create_flow(client, logged_in_headers)\\n    snap = await _create_snapshot(client, logged_in_headers, flow[\\\"id\\\"], description=\\\"initial save\\\")\\n\\n    assert snap[\\\"flow_id\\\"] == flow[\\\"id\\\"]\\n    assert snap[\\\"version_number\\\"] == 1\\n    assert snap[\\\"version_tag\\\"] == \\\"v1\\\"\\n    assert snap[\\\"description\\\"] == \\\"initial save\\\"\\n    assert \\\"created_at\\\" in snap\\n    # List endpoint should NOT include data\\n    assert \\\"data\\\" not in snap\\n\\n\\nasync def test_create_snapshot_without_description(client: AsyncClient, logged_in_headers):\\n    flow = await _create_flow(client, logged_in_headers)\\n    snap = await _create_snapshot(client, logged_in_headers, flow[\\\"id\\\"])\\n\\n    assert snap[\\\"description\\\"] is None\\n    assert snap[\\\"version_number\\\"] == 1\\n\\n\\nasync def test_list_versions_empty(client: AsyncClient, logged_in_headers):\\n    flow = await _create_flow(client, logged_in_headers)\\n    entries = await _list_versions(client, logged_in_headers, flow[\\\"id\\\"])\\n    assert entries == []\\n\\n\\nasync def test_list_versions_response_includes_max_entries(client: AsyncClient, logged_in_headers, monkeypatch):\\n    \\\"\\\"\\\"The list endpoint should return max_entries from settings.\\\"\\\"\\\"\\n    from langflow.services.deps import get_settings_service\\n\\n    settings = get_settings_service().settings\\n    monkeypatch.setattr(settings, \\\"max_flow_version_entries_per_flow\\\", 25)\\n\\n    flow = await _create_flow(client, logged_in_headers)\\n    await _create_snapshot(client, logged_in_headers, flow[\\\"id\\\"])\\n\\n    resp = await client.get(f\\\"api/v1/flows/{flow['id']}/versions/\\\", headers=logged_in_headers)\\n    assert resp.status_code == status.HTTP_200_OK\\n    body = resp.json()\\n\\n    assert body[\\\"max_entries\\\"] == 25\\n    assert isinstance(body[\\\"entries\\\"], list)\\n    assert len(body[\\\"entries\\\"]) == 1\\n\\n\\nasync def test_list_versions_returns_entries_newest_first(client: AsyncClient, logged_in_headers):\\n    flow = await _create_flow(client, logged_in_headers)\\n\\n    await _create_snapshot(client, logged_in_headers, flow[\\\"id\\\"], description=\\\"first\\\")\\n    await _create_snapshot(client, logged_in_headers, flow[\\\"id\\\"], description=\\\"second\\\")\\n    await _create_snapshot(client, logged_in_headers, flow[\\\"id\\\"], description=\\\"third\\\")\\n\\n    entries = await _list_versions(client, logged_in_headers, flow[\\\"id\\\"])\\n    assert len(entries) == 3\\n    # newest first \u2192 highest version_number first\\n    assert entries[0][\\\"version_number\\\"] == 3\\n    assert entries[1][\\\"version_number\\\"] == 2\\n    assert entries[2][\\\"version_number\\\"] == 1\\n\\n\\nasync def test_version_numbers_auto_increment(client: AsyncClient, logged_in_headers):\\n    flow = await _create_flow(client, logged_in_headers)\\n\\n    s1 = await _create_snapshot(client, logged_in_headers, flow[\\\"id\\\"])\\n    s2 = await _create_snapshot(client, logged_in_headers, flow[\\\"id\\\"])\\n    s3 = await _create_snapshot(client, logged_in_headers, flow[\\\"id\\\"])\\n\\n    assert s1[\\\"version_number\\\"] == 1\\n    assert s2[\\\"version_number\\\"] == 2\\n    assert s3[\\\"version_number\\\"] == 3\\n\\n\\nasync def test_get_single_version_entry_includes_data(client: AsyncClient, logged_in_headers):\\n    flow = await _create_flow(client, logged_in_headers)\\n    snap = await _create_snapshot(client, logged_in_headers, flow[\\\"id\\\"])\\n\\n    resp = await client.get(f\\\"api/v1/flows/{flow['id']}/versions/{snap['id']}\\\", headers=logged_in_headers)\\n    assert resp.status_code == status.HTTP_200_OK\\n    full = resp.json()\\n\\n    assert \\\"data\\\" in full\\n    assert full[\\\"data\\\"] == flow[\\\"data\\\"]  # snapshot captured the flow's data\\n    assert full[\\\"version_tag\\\"] == \\\"v1\\\"\\n\\n\\nasync def test_snapshot_captures_current_flow_data(client: AsyncClient, logged_in_headers):\\n    \\\"\\\"\\\"Snapshot data should be a deep copy of flow.data at the time of snapshot.\\\"\\\"\\\"\\n    flow = await _create_flow(client, logged_in_headers)\\n\\n    # Take snapshot of the initial empty data\\n    s1 = await _create_snapshot(client, logged_in_headers, flow[\\\"id\\\"], description=\\\"empty\\\")\\n\\n    # Modify the flow\\n    new_data = {\\\"nodes\\\": [{\\\"id\\\": \\\"node-1\\\"}], \\\"edges\\\": []}\\n    await _patch_flow_data(client, logged_in_headers, flow[\\\"id\\\"], new_data)\\n\\n    # Take another snapshot\\n    s2 = await _create_snapshot(client, logged_in_headers, flow[\\\"id\\\"], description=\\\"with node\\\")\\n\\n    # Fetch full snapshots and compare\\n    r1 = await client.get(f\\\"api/v1/flows/{flow['id']}/versions/{s1['id']}\\\", headers=logged_in_headers)\\n    r2 = await client.get(f\\\"api/v1/flows/{flow['id']}/versions/{s2['id']}\\\", headers=logged_in_headers)\\n\\n    assert r1.json()[\\\"data\\\"] == {\\\"nodes\\\": [], \\\"edges\\\": []}\\n    assert r2.json()[\\\"data\\\"] == new_data\\n\\n\\nasync def test_delete_version_entry(client: AsyncClient, logged_in_headers):\\n    flow = await _create_flow(client, logged_in_headers)\\n    snap = await _create_snapshot(client, logged_in_headers, flow[\\\"id\\\"])\\n\\n    resp = await client.delete(f\\\"api/v1/flows/{flow['id']}/versions/{snap['id']}\\\", headers=logged_in_headers)\\n    assert resp.status_code == status.HTTP_204_NO_CONTENT\\n\\n    entries = await _list_versions(client, logged_in_headers, flow[\\\"id\\\"])\\n    assert len(entries) == 0\\n\\n\\n# ---------------------------------------------------------------------------\\n# Activate version\\n# ---------------------------------------------------------------------------\\n\\n\\nasync def test_activate_version_overwrites_flow_data(client: AsyncClient, logged_in_headers):\\n    \\\"\\\"\\\"Activating a saved version should replace the current flow.data.\\\"\\\"\\\"\\n    flow = await _create_flow(client, logged_in_headers)\\n    original_data = flow[\\\"data\\\"]  # {\\\"nodes\\\": [], \\\"edges\\\": []}\\n\\n    # Snapshot the original state\\n    snap = await _create_snapshot(client, logged_in_headers, flow[\\\"id\\\"], description=\\\"v1 original\\\")\\n\\n    # Modify the flow\\n    modified_data = {\\\"nodes\\\": [{\\\"id\\\": \\\"added-node\\\"}], \\\"edges\\\": []}\\n    await _patch_flow_data(client, logged_in_headers, flow[\\\"id\\\"], modified_data)\\n\\n    # Activate the old snapshot\\n    resp = await client.post(f\\\"api/v1/flows/{flow['id']}/versions/{snap['id']}/activate\\\", headers=logged_in_headers)\\n    assert resp.status_code == status.HTTP_200_OK\\n    updated_flow = resp.json()\\n\\n    assert updated_flow[\\\"data\\\"] == original_data\\n\\n\\nasync def test_activate_version_rejects_components_blocked_after_snapshot(\\n    client: AsyncClient,\\n    logged_in_headers,\\n    monkeypatch,\\n):\\n    \\\"\\\"\\\"A historical version cannot restore a component blocked after it was saved.\\\"\\\"\\\"\\n    from langflow.api.v1 import flow_version as flow_version_module\\n\\n    blocked_data = {\\n        \\\"nodes\\\": [{\\\"id\\\": \\\"Blocked-1\\\", \\\"data\\\": {\\\"type\\\": \\\"BlockedComponent\\\"}}],\\n        \\\"edges\\\": [],\\n    }\\n    flow = await _create_flow(client, logged_in_headers)\\n    await _patch_flow_data(client, logged_in_headers, flow[\\\"id\\\"], blocked_data)\\n    snap = await _create_snapshot(client, logged_in_headers, flow[\\\"id\\\"], description=\\\"before policy change\\\")\\n    current_data = {\\\"nodes\\\": [], \\\"edges\\\": []}\\n    await _patch_flow_data(client, logged_in_headers, flow[\\\"id\\\"], current_data)\\n\\n    service = SimpleNamespace(snapshot=CatalogPolicySnapshot(blocked_component_keys={\\\"BlockedComponent\\\"}))\\n    monkeypatch.setattr(flow_version_module, \\\"get_catalog_policy_service\\\", lambda: service)\\n\\n    response = await client.post(\\n        f\\\"api/v1/flows/{flow['id']}/versions/{snap['id']}/activate\\\",\\n        headers=logged_in_headers,\\n    )\\n\\n    assert response.status_code == status.HTTP_400_BAD_REQUEST\\n    assert \\\"BlockedComponent\\\" in response.json()[\\\"detail\\\"]\\n    current = await client.get(f\\\"api/v1/flows/{flow['id']}\\\", headers=logged_in_headers)\\n    assert current.status_code == status.HTTP_200_OK\\n    assert current.json()[\\\"data\\\"] == current_data\\n\\n\\nasync def test_activate_creates_auto_snapshot(client: AsyncClient, logged_in_headers):\\n    \\\"\\\"\\\"Activation should auto-snapshot the current draft before overwriting.\\\"\\\"\\\"\\n    flow = await _create_flow(client, logged_in_headers)\\n    snap = await _create_snapshot(client, logged_in_headers, flow[\\\"id\\\"])\\n\\n    # Modify flow so auto-snapshot has different data\\n    await _patch_flow_data(client, logged_in_headers, flow[\\\"id\\\"], {\\\"nodes\\\": [{\\\"id\\\": \\\"x\\\"}], \\\"edges\\\": []})\\n\\n    # Activate \u2014 this should create an auto-snapshot first\\n    await client.post(f\\\"api/v1/flows/{flow['id']}/versions/{snap['id']}/activate\\\", headers=logged_in_headers)\\n\\n    entries = await _list_versions(client, logged_in_headers, flow[\\\"id\\\"])\\n    # 1 manual snapshot + 1 auto-snapshot = 2\\n    assert len(entries) == 2\\n\\n    auto_snap = next(e for e in entries if \\\"Auto-saved\\\" in (e.get(\\\"description\\\") or \\\"\\\"))\\n    assert auto_snap is not None\\n\\n\\nasync def test_activate_skips_auto_snapshot_when_save_draft_false(client: AsyncClient, logged_in_headers):\\n    \\\"\\\"\\\"Activation with save_draft=false should NOT create an auto-snapshot.\\\"\\\"\\\"\\n    flow = await _create_flow(client, logged_in_headers)\\n    snap = await _create_snapshot(client, logged_in_headers, flow[\\\"id\\\"])\\n\\n    # Modify flow so we can verify the draft was NOT saved\\n    await _patch_flow_data(client, logged_in_headers, flow[\\\"id\\\"], {\\\"nodes\\\": [{\\\"id\\\": \\\"x\\\"}], \\\"edges\\\": []})\\n\\n    # Activate with save_draft=false\\n    resp = await client.post(\\n        f\\\"api/v1/flows/{flow['id']}/versions/{snap['id']}/activate\\\",\\n        params={\\\"save_draft\\\": False},\\n        headers=logged_in_headers,\\n    )\\n    assert resp.status_code == status.HTTP_200_OK\\n\\n    entries = await _list_versions(client, logged_in_headers, flow[\\\"id\\\"])\\n    # Only the 1 manual snapshot \u2014 no auto-snapshot created\\n    assert len(entries) == 1\\n    assert not any(\\\"Auto-saved\\\" in (e.get(\\\"description\\\") or \\\"\\\") for e in entries)\\n\\n\\n# ---------------------------------------------------------------------------\\n# Cascade deletion\\n# ---------------------------------------------------------------------------\\n\\n\\nasync def test_deleting_flow_cascades_to_versions(client: AsyncClient, logged_in_headers):\\n    flow = await _create_flow(client, logged_in_headers)\\n    await _create_snapshot(client, logged_in_headers, flow[\\\"id\\\"])\\n\\n    # Delete the flow\\n    resp = await client.delete(f\\\"api/v1/flows/{flow['id']}\\\", headers=logged_in_headers)\\n    assert resp.status_code == status.HTTP_200_OK\\n\\n    # Versions endpoint for the deleted flow should 404\\n    resp = await client.get(f\\\"api/v1/flows/{flow['id']}/versions/\\\", headers=logged_in_headers)\\n    assert resp.status_code == status.HTTP_404_NOT_FOUND\\n\\n\\n# ---------------------------------------------------------------------------\\n# Error / edge cases\\n# ---------------------------------------------------------------------------\\n\\n\\nasync def test_get_versions_for_nonexistent_flow(client: AsyncClient, logged_in_headers):\\n    fake_id = \\\"00000000-0000-0000-0000-000000000000\\\"\\n    resp = await client.get(f\\\"api/v1/flows/{fake_id}/versions/\\\", headers=logged_in_headers)\\n    assert resp.status_code == status.HTTP_404_NOT_FOUND\\n\\n\\nasync def test_get_nonexistent_version_entry(client: AsyncClient, logged_in_headers):\\n    flow = await _create_flow(client, logged_in_headers)\\n    fake_id = \\\"00000000-0000-0000-0000-000000000000\\\"\\n    resp = await client.get(f\\\"api/v1/flows/{flow['id']}/versions/{fake_id}\\\", headers=logged_in_headers)\\n    assert resp.status_code == status.HTTP_404_NOT_FOUND\\n\\n\\nasync def test_activate_nonexistent_version_entry(client: AsyncClient, logged_in_headers):\\n    flow = await _create_flow(client, logged_in_headers)\\n    fake_id = \\\"00000000-0000-0000-0000-000000000000\\\"\\n    resp = await client.post(f\\\"api/v1/flows/{flow['id']}/versions/{fake_id}/activate\\\", headers=logged_in_headers)\\n    assert resp.status_code == status.HTTP_404_NOT_FOUND\\n\\n\\nasync def test_delete_nonexistent_version_entry(client: AsyncClient, logged_in_headers):\\n    flow = await _create_flow(client, logged_in_headers)\\n    fake_id = \\\"00000000-0000-0000-0000-000000000000\\\"\\n    resp = await client.delete(f\\\"api/v1/flows/{flow['id']}/versions/{fake_id}\\\", headers=logged_in_headers)\\n    assert resp.status_code == status.HTTP_404_NOT_FOUND\\n\\n\\nasync def test_activate_entry_belonging_to_different_flow(client: AsyncClient, logged_in_headers):\\n    \\\"\\\"\\\"A version entry from flow A should not be activatable on flow B.\\\"\\\"\\\"\\n    flow_a = await _create_flow(client, logged_in_headers, name=\\\"flow-a\\\")\\n    flow_b = await _create_flow(client, logged_in_headers, name=\\\"flow-b\\\")\\n    snap_a = await _create_snapshot(client, logged_in_headers, flow_a[\\\"id\\\"])\\n\\n    # Try to activate snap_a on flow_b\\n    resp = await client.post(f\\\"api/v1/flows/{flow_b['id']}/versions/{snap_a['id']}/activate\\\", headers=logged_in_headers)\\n    assert resp.status_code == status.HTTP_404_NOT_FOUND\\n\\n\\nasync def test_delete_entry_belonging_to_different_flow(client: AsyncClient, logged_in_headers):\\n    \\\"\\\"\\\"A version entry from flow A should not be deletable via flow B's endpoint.\\\"\\\"\\\"\\n    flow_a = await _create_flow(client, logged_in_headers, name=\\\"flow-a-del\\\")\\n    flow_b = await _create_flow(client, logged_in_headers, name=\\\"flow-b-del\\\")\\n    snap_a = await _create_snapshot(client, logged_in_headers, flow_a[\\\"id\\\"])\\n\\n    resp = await client.delete(f\\\"api/v1/flows/{flow_b['id']}/versions/{snap_a['id']}\\\", headers=logged_in_headers)\\n    assert resp.status_code == status.HTTP_404_NOT_FOUND\\n\\n\\nasync def test_unauthenticated_request_is_rejected(client: AsyncClient):\\n    fake_id = \\\"00000000-0000-0000-0000-000000000000\\\"\\n    resp = await client.get(f\\\"api/v1/flows/{fake_id}/versions/\\\")\\n    assert resp.status_code in (status.HTTP_401_UNAUTHORIZED, status.HTTP_403_FORBIDDEN)\\n\\n\\n# ---------------------------------------------------------------------------\\n# Pagination\\n# ---------------------------------------------------------------------------\\n\\n\\nasync def test_list_versions_pagination(client: AsyncClient, logged_in_headers):\\n    flow = await _create_flow(client, logged_in_headers)\\n\\n    # Create 5 snapshots\\n    for i in range(5):\\n        await _create_snapshot(client, logged_in_headers, flow[\\\"id\\\"], description=f\\\"snap-{i}\\\")\\n\\n    # Fetch with limit=2\\n    resp = await client.get(\\n        f\\\"api/v1/flows/{flow['id']}/versions/\\\",\\n        params={\\\"limit\\\": 2, \\\"offset\\\": 0},\\n        headers=logged_in_headers,\\n    )\\n    assert resp.status_code == status.HTTP_200_OK\\n    page1 = resp.json()[\\\"entries\\\"]\\n    assert len(page1) == 2\\n    assert page1[0][\\\"version_number\\\"] == 5  # newest first\\n    assert page1[1][\\\"version_number\\\"] == 4\\n\\n    # Second page\\n    resp = await client.get(\\n        f\\\"api/v1/flows/{flow['id']}/versions/\\\",\\n        params={\\\"limit\\\": 2, \\\"offset\\\": 2},\\n        headers=logged_in_headers,\\n    )\\n    page2 = resp.json()[\\\"entries\\\"]\\n    assert len(page2) == 2\\n    assert page2[0][\\\"version_number\\\"] == 3\\n\\n\\n# ---------------------------------------------------------------------------\\n# Multi-activate scenario (full lifecycle)\\n# ---------------------------------------------------------------------------\\n\\n\\nasync def test_full_lifecycle(client: AsyncClient, logged_in_headers):\\n    \\\"\\\"\\\"End-to-end: create, snapshot, edit, snapshot, activate old, verify.\\\"\\\"\\\"\\n    # 1. Create flow with initial data\\n    flow = await _create_flow(client, logged_in_headers)\\n    flow_id = flow[\\\"id\\\"]\\n    initial_data = flow[\\\"data\\\"]\\n\\n    # 2. Save v1 snapshot\\n    v1 = await _create_snapshot(client, logged_in_headers, flow_id, description=\\\"version 1\\\")\\n    assert v1[\\\"version_number\\\"] == 1\\n\\n    # 3. Edit the flow\\n    data_v2 = {\\\"nodes\\\": [{\\\"id\\\": \\\"n1\\\"}, {\\\"id\\\": \\\"n2\\\"}], \\\"edges\\\": [{\\\"id\\\": \\\"e1\\\"}]}\\n    await _patch_flow_data(client, logged_in_headers, flow_id, data_v2)\\n\\n    # 4. Save v2 snapshot\\n    v2 = await _create_snapshot(client, logged_in_headers, flow_id, description=\\\"version 2\\\")\\n    assert v2[\\\"version_number\\\"] == 2\\n\\n    # 5. Edit the flow again\\n    data_v3 = {\\\"nodes\\\": [{\\\"id\\\": \\\"n1\\\"}, {\\\"id\\\": \\\"n2\\\"}, {\\\"id\\\": \\\"n3\\\"}], \\\"edges\\\": []}\\n    await _patch_flow_data(client, logged_in_headers, flow_id, data_v3)\\n\\n    # 6. Activate v1 \u2014 should auto-snapshot current state, then revert to v1's data\\n    resp = await client.post(f\\\"api/v1/flows/{flow_id}/versions/{v1['id']}/activate\\\", headers=logged_in_headers)\\n    assert resp.status_code == status.HTTP_200_OK\\n    activated_flow = resp.json()\\n    assert activated_flow[\\\"data\\\"] == initial_data\\n\\n    # 7. Verify versions now has 3 entries: v1, v2, + auto-snapshot (v3)\\n    entries = await _list_versions(client, logged_in_headers, flow_id)\\n    assert len(entries) == 3\\n\\n    # 8. The auto-snapshot should contain data_v3\\n    auto = next(e for e in entries if \\\"Auto-saved\\\" in (e.get(\\\"description\\\") or \\\"\\\"))\\n    auto_full = await client.get(f\\\"api/v1/flows/{flow_id}/versions/{auto['id']}\\\", headers=logged_in_headers)\\n    assert auto_full.json()[\\\"data\\\"] == data_v3\\n\\n    # 9. Activate v2\\n    resp2 = await client.post(f\\\"api/v1/flows/{flow_id}/versions/{v2['id']}/activate\\\", headers=logged_in_headers)\\n    assert resp2.status_code == status.HTTP_200_OK\\n    assert resp2.json()[\\\"data\\\"] == data_v2\\n\\n\\n# ---------------------------------------------------------------------------\\n# Realistic data payloads (starter project)\\n# ---------------------------------------------------------------------------\\n\\n\\nasync def test_snapshot_and_activate_with_complex_flow_data(client: AsyncClient, logged_in_headers):\\n    \\\"\\\"\\\"Snapshot / activate round-trip with a real multi-node flow from test data.\\\"\\\"\\\"\\n    complex_json = json.loads(pytest.COMPLEX_EXAMPLE_PATH.read_text(encoding=\\\"utf-8\\\"))\\n    complex_data = complex_json.get(\\\"data\\\", complex_json)\\n\\n    # Create a flow with the complex data\\n    payload = {\\n        \\\"name\\\": \\\"complex-version-test\\\",\\n        \\\"description\\\": \\\"flow with real nodes\\\",\\n        \\\"data\\\": complex_data,\\n        \\\"is_component\\\": False,\\n    }\\n    resp = await client.post(\\\"api/v1/flows/\\\", json=payload, headers=logged_in_headers)\\n    assert resp.status_code == status.HTTP_201_CREATED\\n    flow = resp.json()\\n    flow_id = flow[\\\"id\\\"]\\n\\n    # Verify the flow has meaningful data\\n    assert len(flow[\\\"data\\\"][\\\"nodes\\\"]) > 1\\n    assert len(flow[\\\"data\\\"][\\\"edges\\\"]) > 0\\n\\n    # Snapshot the complex state\\n    snap = await _create_snapshot(client, logged_in_headers, flow_id, description=\\\"complex v1\\\")\\n\\n    # Overwrite the flow with minimal data\\n    minimal_data = {\\\"nodes\\\": [{\\\"id\\\": \\\"single-node\\\"}], \\\"edges\\\": []}\\n    await _patch_flow_data(client, logged_in_headers, flow_id, minimal_data)\\n\\n    # Verify flow was actually changed\\n    get_resp = await client.get(f\\\"api/v1/flows/{flow_id}\\\", headers=logged_in_headers)\\n    assert len(get_resp.json()[\\\"data\\\"][\\\"nodes\\\"]) == 1\\n\\n    # Activate the complex snapshot \u2014 should restore the full graph\\n    activate_resp = await client.post(\\n        f\\\"api/v1/flows/{flow_id}/versions/{snap['id']}/activate\\\", headers=logged_in_headers\\n    )\\n    assert activate_resp.status_code == status.HTTP_200_OK\\n    restored = activate_resp.json()\\n\\n    assert restored[\\\"data\\\"] == complex_data\\n\\n\\nasync def test_snapshot_preserves_full_node_metadata(client: AsyncClient, logged_in_headers):\\n    \\\"\\\"\\\"Verify that node IDs, positions, and edge handles survive snapshot.\\n\\n    Note: the GET endpoint strips API keys server-side, so template password\\n    field values will be None.  This test focuses on structural preservation\\n    (IDs, positions, edge count) rather than exact template value equality.\\n    \\\"\\\"\\\"\\n    complex_json = json.loads(pytest.COMPLEX_EXAMPLE_PATH.read_text(encoding=\\\"utf-8\\\"))\\n    complex_data = complex_json.get(\\\"data\\\", complex_json)\\n\\n    payload = {\\n        \\\"name\\\": \\\"metadata-preservation-test\\\",\\n        \\\"description\\\": \\\"test\\\",\\n        \\\"data\\\": complex_data,\\n        \\\"is_component\\\": False,\\n    }\\n    resp = await client.post(\\\"api/v1/flows/\\\", json=payload, headers=logged_in_headers)\\n    flow = resp.json()\\n    snap = await _create_snapshot(client, logged_in_headers, flow[\\\"id\\\"])\\n\\n    # Fetch the full snapshot and compare node-by-node\\n    full = await client.get(f\\\"api/v1/flows/{flow['id']}/versions/{snap['id']}\\\", headers=logged_in_headers)\\n    snapshot_data = full.json()[\\\"data\\\"]\\n\\n    assert len(snapshot_data[\\\"nodes\\\"]) == len(complex_data[\\\"nodes\\\"])\\n    assert len(snapshot_data[\\\"edges\\\"]) == len(complex_data[\\\"edges\\\"])\\n\\n    for i, original_node in enumerate(complex_data[\\\"nodes\\\"]):\\n        snap_node = snapshot_data[\\\"nodes\\\"][i]\\n        assert snap_node[\\\"id\\\"] == original_node[\\\"id\\\"]\\n        assert snap_node.get(\\\"position\\\") == original_node.get(\\\"position\\\")\\n\\n\\n# ---------------------------------------------------------------------------\\n# Version limit enforcement\\n# ---------------------------------------------------------------------------\\n\\n\\nasync def test_version_limit_enforcement(client: AsyncClient, logged_in_headers, monkeypatch):\\n    \\\"\\\"\\\"Creating snapshots beyond the configured limit prunes the oldest entries.\\\"\\\"\\\"\\n    # Set a small limit for testing\\n    from langflow.services.deps import get_settings_service\\n\\n    settings = get_settings_service().settings\\n    monkeypatch.setattr(settings, \\\"max_flow_version_entries_per_flow\\\", 3)\\n\\n    flow = await _create_flow(client, logged_in_headers)\\n    flow_id = flow[\\\"id\\\"]\\n\\n    # Create 5 snapshots \u2014 limit is 3, so oldest 2 should be pruned\\n    for i in range(5):\\n        await _create_snapshot(client, logged_in_headers, flow_id, description=f\\\"snap-{i}\\\")\\n\\n    entries = await _list_versions(client, logged_in_headers, flow_id)\\n    assert len(entries) == 3\\n\\n\\nasync def test_version_limit_keeps_newest(client: AsyncClient, logged_in_headers, monkeypatch):\\n    \\\"\\\"\\\"After pruning, the remaining entries should be the most recent by version_number.\\\"\\\"\\\"\\n    from langflow.services.deps import get_settings_service\\n\\n    settings = get_settings_service().settings\\n    monkeypatch.setattr(settings, \\\"max_flow_version_entries_per_flow\\\", 3)\\n\\n    flow = await _create_flow(client, logged_in_headers)\\n    flow_id = flow[\\\"id\\\"]\\n\\n    for i in range(5):\\n        await _create_snapshot(client, logged_in_headers, flow_id, description=f\\\"snap-{i}\\\")\\n\\n    entries = await _list_versions(client, logged_in_headers, flow_id)\\n    version_numbers = [e[\\\"version_number\\\"] for e in entries]\\n    # Should have versions 5, 4, 3 (newest first) \u2014 versions 1 and 2 were pruned\\n    assert version_numbers == [5, 4, 3]\\n\\n\\nasync def test_pruning_deletes_oldest_by_data_content(client: AsyncClient, logged_in_headers, monkeypatch):\\n    \\\"\\\"\\\"Verify that pruned entries are truly the oldest by checking surviving data content.\\\"\\\"\\\"\\n    from langflow.services.deps import get_settings_service\\n\\n    settings = get_settings_service().settings\\n    monkeypatch.setattr(settings, \\\"max_flow_version_entries_per_flow\\\", 2)\\n\\n    flow = await _create_flow(client, logged_in_headers)\\n    flow_id = flow[\\\"id\\\"]\\n\\n    # Create 3 snapshots, each with distinct flow data so we can verify which survived.\\n    for i in range(3):\\n        data = {\\\"nodes\\\": [{\\\"id\\\": f\\\"node-from-snap-{i}\\\"}], \\\"edges\\\": []}\\n        await _patch_flow_data(client, logged_in_headers, flow_id, data)\\n        await _create_snapshot(client, logged_in_headers, flow_id, description=f\\\"snap-{i}\\\")\\n\\n    # Only the 2 newest should survive (snap-1 and snap-2); snap-0 should be pruned.\\n    entries = await _list_versions(client, logged_in_headers, flow_id)\\n    assert len(entries) == 2\\n    assert entries[0][\\\"description\\\"] == \\\"snap-2\\\"\\n    assert entries[1][\\\"description\\\"] == \\\"snap-1\\\"\\n\\n    # Fetch full data for each survivor and confirm it matches the expected snapshot data.\\n    for entry, expected_idx in zip(entries, [2, 1], strict=False):\\n        resp = await client.get(\\n            f\\\"api/v1/flows/{flow_id}/versions/{entry['id']}\\\",\\n            headers=logged_in_headers,\\n        )\\n        assert resp.status_code == 200\\n        assert resp.json()[\\\"data\\\"][\\\"nodes\\\"][0][\\\"id\\\"] == f\\\"node-from-snap-{expected_idx}\\\"\\n\\n\\nasync def test_lowered_limit_prunes_excess_on_next_snapshot(client: AsyncClient, logged_in_headers, monkeypatch):\\n    \\\"\\\"\\\"Lowering the limit after entries exist should prune excess on the next snapshot.\\\"\\\"\\\"\\n    from langflow.services.deps import get_settings_service\\n\\n    settings = get_settings_service().settings\\n\\n    # Start with a generous limit and create 5 snapshots.\\n    monkeypatch.setattr(settings, \\\"max_flow_version_entries_per_flow\\\", 10)\\n    flow = await _create_flow(client, logged_in_headers)\\n    flow_id = flow[\\\"id\\\"]\\n\\n    for i in range(5):\\n        await _create_snapshot(client, logged_in_headers, flow_id, description=f\\\"snap-{i}\\\")\\n\\n    entries = await _list_versions(client, logged_in_headers, flow_id)\\n    assert len(entries) == 5\\n\\n    # Now lower the limit to 2 \u2014 existing entries remain untouched until next snapshot.\\n    monkeypatch.setattr(settings, \\\"max_flow_version_entries_per_flow\\\", 2)\\n\\n    entries_before = await _list_versions(client, logged_in_headers, flow_id)\\n    assert len(entries_before) == 5  # Still 5 \u2014 no pruning yet\\n\\n    # Create one more snapshot \u2014 should trigger pruning down to 2.\\n    await _create_snapshot(client, logged_in_headers, flow_id, description=\\\"after-limit-change\\\")\\n\\n    entries_after = await _list_versions(client, logged_in_headers, flow_id)\\n    assert len(entries_after) == 2\\n\\n    # The two survivors should be the newest: \\\"after-limit-change\\\" and \\\"snap-4\\\"\\n    assert entries_after[0][\\\"description\\\"] == \\\"after-limit-change\\\"\\n    assert entries_after[1][\\\"description\\\"] == \\\"snap-4\\\"\\n\\n\\n# ---------------------------------------------------------------------------\\n# Activate version with null data\\n# ---------------------------------------------------------------------------\\n\\n\\nasync def test_activate_version_with_null_data(client: AsyncClient, logged_in_headers):\\n    \\\"\\\"\\\"Activating a version whose data is None should return 400.\\\"\\\"\\\"\\n    from uuid import UUID\\n\\n    from langflow.services.database.models.flow_version.model import FlowVersion\\n    from langflow.services.deps import session_scope\\n    from sqlmodel import select\\n\\n    flow = await _create_flow(client, logged_in_headers)\\n    flow_id = flow[\\\"id\\\"]\\n\\n    snap = await _create_snapshot(client, logged_in_headers, flow_id)\\n\\n    # Manually set the snapshot's data to None in the DB\\n    async with session_scope() as session:\\n        result = await session.exec(select(FlowVersion).where(FlowVersion.id == UUID(snap[\\\"id\\\"])))\\n        entry = result.first()\\n        if entry:\\n            entry.data = None\\n            session.add(entry)\\n\\n    resp = await client.post(f\\\"api/v1/flows/{flow_id}/versions/{snap['id']}/activate\\\", headers=logged_in_headers)\\n    assert resp.status_code == status.HTTP_400_BAD_REQUEST\\n    assert \\\"no data\\\" in resp.json()[\\\"detail\\\"].lower()\\n\\n\\n# ---------------------------------------------------------------------------\\n# Cross-user isolation\\n# ---------------------------------------------------------------------------\\n\\n\\nasync def test_version_entry_scoped_to_flow(client: AsyncClient, logged_in_headers):\\n    \\\"\\\"\\\"Getting a version entry via the wrong flow's endpoint should 404.\\\"\\\"\\\"\\n    flow_a = await _create_flow(client, logged_in_headers, name=\\\"scope-a\\\")\\n    flow_b = await _create_flow(client, logged_in_headers, name=\\\"scope-b\\\")\\n    snap_a = await _create_snapshot(client, logged_in_headers, flow_a[\\\"id\\\"])\\n\\n    # Try to access snap_a through flow_b's endpoint\\n    resp = await client.get(f\\\"api/v1/flows/{flow_b['id']}/versions/{snap_a['id']}\\\", headers=logged_in_headers)\\n    assert resp.status_code == status.HTTP_404_NOT_FOUND\\n\\n\\n# ---------------------------------------------------------------------------\\n# Edge case: limit boundary values\\n# ---------------------------------------------------------------------------\\n\\n\\nasync def test_list_versions_limit_of_one(client: AsyncClient, logged_in_headers):\\n    \\\"\\\"\\\"Limit=1 should return exactly one entry.\\\"\\\"\\\"\\n    flow = await _create_flow(client, logged_in_headers)\\n    for i in range(3):\\n        await _create_snapshot(client, logged_in_headers, flow[\\\"id\\\"], description=f\\\"s-{i}\\\")\\n\\n    resp = await client.get(\\n        f\\\"api/v1/flows/{flow['id']}/versions/\\\",\\n        params={\\\"limit\\\": 1},\\n        headers=logged_in_headers,\\n    )\\n    assert resp.status_code == status.HTTP_200_OK\\n    assert len(resp.json()[\\\"entries\\\"]) == 1\\n    assert resp.json()[\\\"entries\\\"][0][\\\"version_number\\\"] == 3  # newest\\n\\n\\nasync def test_list_versions_invalid_limit_zero(client: AsyncClient, logged_in_headers):\\n    \\\"\\\"\\\"Limit=0 should be rejected by validation (ge=1).\\\"\\\"\\\"\\n    flow = await _create_flow(client, logged_in_headers)\\n    resp = await client.get(\\n        f\\\"api/v1/flows/{flow['id']}/versions/\\\",\\n        params={\\\"limit\\\": 0},\\n        headers=logged_in_headers,\\n    )\\n    assert resp.status_code == status.HTTP_422_UNPROCESSABLE_CONTENT\\n\\n\\nasync def test_list_versions_limit_exceeds_max(client: AsyncClient, logged_in_headers):\\n    \\\"\\\"\\\"Limit > 100 should be rejected by validation (le=100).\\\"\\\"\\\"\\n    flow = await _create_flow(client, logged_in_headers)\\n    resp = await client.get(\\n        f\\\"api/v1/flows/{flow['id']}/versions/\\\",\\n        params={\\\"limit\\\": 101},\\n        headers=logged_in_headers,\\n    )\\n    assert resp.status_code == status.HTTP_422_UNPROCESSABLE_CONTENT\\n\\n\\nasync def test_get_single_entry_strips_api_keys(client: AsyncClient, logged_in_headers):\\n    \\\"\\\"\\\"GET /versions/{id} should strip API keys from the returned data.\\n\\n    The single-entry endpoint is used by the frontend for previewing and\\n    per-version export. API keys are stripped server-side to prevent leakage\\n    through the preview path, matching the export endpoint's behaviour.\\n    \\\"\\\"\\\"\\n    api_key_data = {\\n        \\\"nodes\\\": [\\n            {\\n                \\\"id\\\": \\\"node-1\\\",\\n                \\\"data\\\": {\\n                    \\\"node\\\": {\\n                        \\\"template\\\": {\\n                            \\\"api_key\\\": {\\n                                \\\"value\\\": \\\"sk-secret-99999\\\",\\n                                \\\"name\\\": \\\"api_key\\\",\\n                                \\\"password\\\": True,\\n                            }\\n                        }\\n                    }\\n                },\\n            }\\n        ],\\n        \\\"edges\\\": [],\\n    }\\n    payload = {\\n        \\\"name\\\": \\\"single-entry-api-key-test\\\",\\n        \\\"description\\\": \\\"test\\\",\\n        \\\"data\\\": api_key_data,\\n        \\\"is_component\\\": False,\\n    }\\n    resp = await client.post(\\\"api/v1/flows/\\\", json=payload, headers=logged_in_headers)\\n    assert resp.status_code == status.HTTP_201_CREATED\\n    flow = resp.json()\\n\\n    snap = await _create_snapshot(client, logged_in_headers, flow[\\\"id\\\"])\\n\\n    # Fetch the single entry \u2014 API key should be stripped (value set to None)\\n    resp = await client.get(\\n        f\\\"api/v1/flows/{flow['id']}/versions/{snap['id']}\\\",\\n        headers=logged_in_headers,\\n    )\\n    assert resp.status_code == status.HTTP_200_OK\\n    entry_data = resp.json()[\\\"data\\\"]\\n    template = entry_data[\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"]\\n    assert template[\\\"api_key\\\"][\\\"value\\\"] is None\\n\\n\\nasync def test_create_snapshot_rejects_long_description(client: AsyncClient, logged_in_headers):\\n    \\\"\\\"\\\"POST with description > 500 chars should be rejected with 422.\\\"\\\"\\\"\\n    flow = await _create_flow(client, logged_in_headers)\\n    long_description = \\\"x\\\" * 501\\n\\n    resp = await client.post(\\n        f\\\"api/v1/flows/{flow['id']}/versions/\\\",\\n        json={\\\"description\\\": long_description},\\n        headers=logged_in_headers,\\n    )\\n    assert resp.status_code == status.HTTP_422_UNPROCESSABLE_CONTENT\\n\\n\\nasync def test_create_snapshot_accepts_max_description(client: AsyncClient, logged_in_headers):\\n    \\\"\\\"\\\"POST with description exactly 500 chars should succeed.\\\"\\\"\\\"\\n    flow = await _create_flow(client, logged_in_headers)\\n    max_description = \\\"x\\\" * 500\\n\\n    snap = await _create_snapshot(client, logged_in_headers, flow[\\\"id\\\"], description=max_description)\\n    assert snap[\\\"description\\\"] == max_description\\n\\n\\nasync def test_activate_with_deeply_nested_data(client: AsyncClient, logged_in_headers):\\n    \\\"\\\"\\\"Activate should work correctly with deeply nested flow data.\\\"\\\"\\\"\\n    # Create deeply nested data\\n    nested = {\\\"level\\\": 0}\\n    current = nested\\n    for i in range(1, 20):\\n        current[\\\"child\\\"] = {\\\"level\\\": i}\\n        current = current[\\\"child\\\"]\\n\\n    deep_data = {\\\"nodes\\\": [{\\\"id\\\": \\\"deep-node\\\", \\\"data\\\": nested}], \\\"edges\\\": []}\\n    payload = {\\n        \\\"name\\\": \\\"deep-nested-test\\\",\\n        \\\"description\\\": \\\"test\\\",\\n        \\\"data\\\": deep_data,\\n        \\\"is_component\\\": False,\\n    }\\n    resp = await client.post(\\\"api/v1/flows/\\\", json=payload, headers=logged_in_headers)\\n    assert resp.status_code == status.HTTP_201_CREATED\\n    flow = resp.json()\\n    flow_id = flow[\\\"id\\\"]\\n\\n    # Snapshot the deeply nested data\\n    snap = await _create_snapshot(client, logged_in_headers, flow_id)\\n\\n    # Modify the flow\\n    await _patch_flow_data(client, logged_in_headers, flow_id, {\\\"nodes\\\": [], \\\"edges\\\": []})\\n\\n    # Activate the old version \u2014 triggers deepcopy of both current and target data\\n    resp = await client.post(\\n        f\\\"api/v1/flows/{flow_id}/versions/{snap['id']}/activate\\\",\\n        headers=logged_in_headers,\\n    )\\n    assert resp.status_code == status.HTTP_200_OK\\n    restored = resp.json()\\n    assert restored[\\\"data\\\"] == deep_data\\n\\n\\nasync def test_version_number_is_always_positive(client: AsyncClient, logged_in_headers):\\n    \\\"\\\"\\\"get_next_version_number always returns >= 1, even for a brand-new flow.\\\"\\\"\\\"\\n    from langflow.services.database.models.flow_version.crud import get_next_version_number\\n    from langflow.services.deps import session_scope\\n\\n    flow = await _create_flow(client, logged_in_headers)\\n\\n    async with session_scope() as session:\\n        from uuid import UUID\\n\\n        next_ver = await get_next_version_number(session, UUID(flow[\\\"id\\\"]))\\n        assert next_ver >= 1\\n\\n    # After creating a snapshot, next version should still be >= 1\\n    await _create_snapshot(client, logged_in_headers, flow[\\\"id\\\"])\\n    async with session_scope() as session:\\n        next_ver = await get_next_version_number(session, UUID(flow[\\\"id\\\"]))\\n        assert next_ver >= 1\\n        assert next_ver == 2\\n\\n\\nasync def test_rapid_snapshots_with_low_limit(client: AsyncClient, logged_in_headers, monkeypatch):\\n    \\\"\\\"\\\"Creating many snapshots rapidly with a low limit should work without errors.\\\"\\\"\\\"\\n    from langflow.services.deps import get_settings_service\\n\\n    settings = get_settings_service().settings\\n    monkeypatch.setattr(settings, \\\"max_flow_version_entries_per_flow\\\", 2)\\n\\n    flow = await _create_flow(client, logged_in_headers)\\n    flow_id = flow[\\\"id\\\"]\\n\\n    # Create 5 snapshots in quick succession\\n    for i in range(5):\\n        resp = await client.post(\\n            f\\\"api/v1/flows/{flow_id}/versions/\\\",\\n            json={\\\"description\\\": f\\\"rapid-{i}\\\"},\\n            headers=logged_in_headers,\\n        )\\n        assert resp.status_code == status.HTTP_201_CREATED\\n\\n    # Should have exactly 2 entries (the limit)\\n    entries = await _list_versions(client, logged_in_headers, flow_id)\\n    assert len(entries) == 2\\n    # The newest ones should survive\\n    assert entries[0][\\\"version_number\\\"] == 5\\n    assert entries[1][\\\"version_number\\\"] == 4\\n\\n\\n# ---------------------------------------------------------------------------\\n# Deployment-aware: provider-scoped is_deployed indicator\\n# ---------------------------------------------------------------------------\\n\\n\\nasync def _attach_version_to_deployment(session, *, user_id, flow_version_id, deployment_id, provider_snapshot_id=None):\\n    \\\"\\\"\\\"Create a FlowVersionDeploymentAttachment row directly in the DB.\\\"\\\"\\\"\\n    from langflow.services.database.models.flow_version_deployment_attachment.crud import (\\n        create_deployment_attachment,\\n    )\\n\\n    return await create_deployment_attachment(\\n        session,\\n        user_id=user_id,\\n        flow_version_id=flow_version_id,\\n        deployment_id=deployment_id,\\n        provider_snapshot_id=provider_snapshot_id or f\\\"snap-{flow_version_id}\\\",\\n    )\\n\\n\\nasync def _create_deployment_row(session, *, user_id, project_id, provider_account_id, name, resource_key):\\n    \\\"\\\"\\\"Create a Deployment row directly in the DB.\\\"\\\"\\\"\\n    from langflow.services.database.models.deployment.crud import create_deployment\\n    from lfx.services.adapters.deployment.schema import DeploymentType\\n\\n    return await create_deployment(\\n        session,\\n        user_id=user_id,\\n        project_id=project_id,\\n        deployment_provider_account_id=provider_account_id,\\n        resource_key=resource_key,\\n        display_name=name,\\n        deployment_type=DeploymentType.AGENT,\\n    )\\n\\n\\nasync def _create_provider_account_row(session, *, user_id):\\n    \\\"\\\"\\\"Create a DeploymentProviderAccount row directly in the DB.\\\"\\\"\\\"\\n    from uuid import uuid4\\n\\n    from langflow.services.database.models.deployment_provider_account.crud import create_provider_account\\n\\n    suffix = uuid4()\\n    return await create_provider_account(\\n        session,\\n        user_id=user_id,\\n        name=f\\\"test-provider-account-{suffix}\\\",\\n        provider_tenant_id=None,\\n        provider_key=\\\"watsonx-orchestrate\\\",\\n        provider_url=f\\\"https://test-{suffix}.example.com\\\",\\n        api_key=\\\"test-key\\\",  # pragma: allowlist secret\\n    )\\n\\n\\nasync def test_list_versions_omits_is_deployed_without_provider_scope(\\n    client: AsyncClient, logged_in_headers, monkeypatch\\n):\\n    \\\"\\\"\\\"Without provider scoping, deployment status is omitted.\\\"\\\"\\\"\\n    _set_deployments_feature_flag(monkeypatch, enabled=True)\\n    flow = await _create_flow(client, logged_in_headers)\\n    await _create_snapshot(client, logged_in_headers, flow[\\\"id\\\"])\\n\\n    entries = await _list_versions(client, logged_in_headers, flow[\\\"id\\\"])\\n    assert len(entries) == 1\\n    assert \\\"is_deployed\\\" not in entries[0]\\n\\n\\nasync def test_list_versions_is_deployed_scoped_to_provider(client: AsyncClient, logged_in_headers, monkeypatch):\\n    \\\"\\\"\\\"Provider-scoped status only reflects deployments under the selected provider.\\\"\\\"\\\"\\n    from uuid import UUID\\n\\n    from langflow.services.deps import session_scope\\n\\n    _set_deployments_feature_flag(monkeypatch, enabled=True)\\n    flow = await _create_flow(client, logged_in_headers)\\n    snap = await _create_snapshot(client, logged_in_headers, flow[\\\"id\\\"])\\n    snap2 = await _create_snapshot(client, logged_in_headers, flow[\\\"id\\\"], description=\\\"undeployed\\\")\\n\\n    async with session_scope() as session:\\n        from langflow.services.database.models.flow.model import Flow\\n        from sqlmodel import select\\n\\n        flow_row = (await session.exec(select(Flow).where(Flow.id == UUID(flow[\\\"id\\\"])))).one()\\n        user_id = flow_row.user_id\\n        project_id = flow_row.folder_id\\n        provider_account_a = await _create_provider_account_row(session, user_id=user_id)\\n        provider_account_b = await _create_provider_account_row(session, user_id=user_id)\\n        provider_account_a_id = str(provider_account_a.id)\\n        provider_account_b_id = str(provider_account_b.id)\\n        deployment = await _create_deployment_row(\\n            session,\\n            user_id=user_id,\\n            project_id=project_id,\\n            provider_account_id=provider_account_a.id,\\n            name=\\\"test-deployment\\\",\\n            resource_key=\\\"rk-1\\\",\\n        )\\n        await _attach_version_to_deployment(\\n            session,\\n            user_id=user_id,\\n            flow_version_id=UUID(snap[\\\"id\\\"]),\\n            deployment_id=deployment.id,\\n        )\\n\\n    entries = await _list_versions(\\n        client,\\n        logged_in_headers,\\n        flow[\\\"id\\\"],\\n        params={\\\"deployment_provider_id\\\": provider_account_a_id},\\n    )\\n    assert len(entries) == 2\\n    deployed_entry = next(e for e in entries if e[\\\"id\\\"] == snap[\\\"id\\\"])\\n    undeployed_entry = next(e for e in entries if e[\\\"id\\\"] == snap2[\\\"id\\\"])\\n    assert deployed_entry[\\\"is_deployed\\\"] is True\\n    assert undeployed_entry[\\\"is_deployed\\\"] is False\\n\\n    entries_other_provider = await _list_versions(\\n        client,\\n        logged_in_headers,\\n        flow[\\\"id\\\"],\\n        params={\\\"deployment_provider_id\\\": provider_account_b_id},\\n    )\\n    assert len(entries_other_provider) == 2\\n    assert all(entry[\\\"is_deployed\\\"] is False for entry in entries_other_provider)\\n\\n\\nasync def test_list_versions_plain_mode_returns_all(client: AsyncClient, logged_in_headers, monkeypatch):\\n    \\\"\\\"\\\"Without provider scoping, all versions are returned without deployment status.\\\"\\\"\\\"\\n    from uuid import UUID\\n\\n    from langflow.services.deps import session_scope\\n\\n    _set_deployments_feature_flag(monkeypatch, enabled=True)\\n    flow = await _create_flow(client, logged_in_headers)\\n    await _create_snapshot(client, logged_in_headers, flow[\\\"id\\\"], description=\\\"deployed\\\")\\n    await _create_snapshot(client, logged_in_headers, flow[\\\"id\\\"], description=\\\"draft\\\")\\n\\n    async with session_scope() as session:\\n        from langflow.services.database.models.flow.model import Flow\\n        from sqlmodel import select\\n\\n        flow_row = (await session.exec(select(Flow).where(Flow.id == UUID(flow[\\\"id\\\"])))).one()\\n        user_id = flow_row.user_id\\n        project_id = flow_row.folder_id\\n        provider_account = await _create_provider_account_row(session, user_id=user_id)\\n        deployment = await _create_deployment_row(\\n            session,\\n            user_id=user_id,\\n            project_id=project_id,\\n            provider_account_id=provider_account.id,\\n            name=\\\"test-no-filter\\\",\\n            resource_key=\\\"rk-no-filter\\\",\\n        )\\n        entries = await _list_versions(client, logged_in_headers, flow[\\\"id\\\"])\\n        snap_deployed = next(e for e in entries if e[\\\"description\\\"] == \\\"deployed\\\")\\n        await _attach_version_to_deployment(\\n            session,\\n            user_id=user_id,\\n            flow_version_id=UUID(snap_deployed[\\\"id\\\"]),\\n            deployment_id=deployment.id,\\n        )\\n\\n    # No filter \u2014 should return both versions\\n    entries = await _list_versions(client, logged_in_headers, flow[\\\"id\\\"])\\n    assert len(entries) == 2\\n    deployed = next(e for e in entries if e[\\\"description\\\"] == \\\"deployed\\\")\\n    draft = next(e for e in entries if e[\\\"description\\\"] == \\\"draft\\\")\\n    assert \\\"is_deployed\\\" not in deployed\\n    assert \\\"is_deployed\\\" not in draft\\n\\n\\nasync def test_create_snapshot_omits_is_deployed(client: AsyncClient, logged_in_headers, monkeypatch):\\n    \\\"\\\"\\\"Create snapshot response should not include deployment status.\\\"\\\"\\\"\\n    _set_deployments_feature_flag(monkeypatch, enabled=True)\\n    flow = await _create_flow(client, logged_in_headers)\\n    snap = await _create_snapshot(client, logged_in_headers, flow[\\\"id\\\"])\\n    assert \\\"is_deployed\\\" not in snap\\n\\n\\nasync def test_list_versions_hides_deployment_state_when_feature_disabled(\\n    client: AsyncClient, logged_in_headers, monkeypatch\\n):\\n    from uuid import UUID\\n\\n    from langflow.services.deps import session_scope\\n\\n    _set_deployments_feature_flag(monkeypatch, enabled=False)\\n    flow = await _create_flow(client, logged_in_headers)\\n    snap = await _create_snapshot(client, logged_in_headers, flow[\\\"id\\\"])\\n\\n    async with session_scope() as session:\\n        from langflow.services.database.models.flow.model import Flow\\n        from sqlmodel import select\\n\\n        flow_row = (await session.exec(select(Flow).where(Flow.id == UUID(flow[\\\"id\\\"])))).one()\\n        user_id = flow_row.user_id\\n        project_id = flow_row.folder_id\\n        provider_account = await _create_provider_account_row(session, user_id=user_id)\\n        deployment = await _create_deployment_row(\\n            session,\\n            user_id=user_id,\\n            project_id=project_id,\\n            provider_account_id=provider_account.id,\\n            name=\\\"disabled-flag-list\\\",\\n            resource_key=\\\"rk-disabled-list\\\",\\n        )\\n        await _attach_version_to_deployment(\\n            session,\\n            user_id=user_id,\\n            flow_version_id=UUID(snap[\\\"id\\\"]),\\n            deployment_id=deployment.id,\\n        )\\n\\n    resp = await client.get(f\\\"api/v1/flows/{flow['id']}/versions/\\\", headers=logged_in_headers)\\n\\n    assert resp.status_code == status.HTTP_200_OK\\n    assert \\\"is_deployed\\\" not in resp.json()[\\\"entries\\\"][0]\\n\\n\\nasync def test_list_versions_rejects_provider_id_when_feature_disabled(\\n    client: AsyncClient, logged_in_headers, monkeypatch\\n):\\n    from uuid import uuid4\\n\\n    _set_deployments_feature_flag(monkeypatch, enabled=False)\\n    flow = await _create_flow(client, logged_in_headers)\\n    await _create_snapshot(client, logged_in_headers, flow[\\\"id\\\"])\\n\\n    resp = await client.get(\\n        f\\\"api/v1/flows/{flow['id']}/versions/\\\",\\n        params={\\\"deployment_provider_id\\\": str(uuid4())},\\n        headers=logged_in_headers,\\n    )\\n\\n    assert resp.status_code == status.HTTP_400_BAD_REQUEST\\n    assert resp.json()[\\\"detail\\\"] == \\\"Cannot use deployment_provider_id: the wxo_deployments feature flag is disabled\\\"\\n\\n\\nasync def test_list_versions_rejects_unknown_provider_id(client: AsyncClient, logged_in_headers, monkeypatch):\\n    from uuid import uuid4\\n\\n    _set_deployments_feature_flag(monkeypatch, enabled=True)\\n    flow = await _create_flow(client, logged_in_headers)\\n    await _create_snapshot(client, logged_in_headers, flow[\\\"id\\\"])\\n\\n    resp = await client.get(\\n        f\\\"api/v1/flows/{flow['id']}/versions/\\\",\\n        params={\\\"deployment_provider_id\\\": str(uuid4())},\\n        headers=logged_in_headers,\\n    )\\n\\n    assert resp.status_code == status.HTTP_404_NOT_FOUND\\n    assert resp.json()[\\\"detail\\\"] == \\\"Deployment provider account not found.\\\"\\n\\n\\nasync def test_list_versions_rejects_foreign_provider_id(client: AsyncClient, logged_in_headers, monkeypatch):\\n    from uuid import uuid4\\n\\n    from langflow.services.database.models.user.model import User\\n    from langflow.services.deps import session_scope\\n\\n    _set_deployments_feature_flag(monkeypatch, enabled=True)\\n    flow = await _create_flow(client, logged_in_headers)\\n    await _create_snapshot(client, logged_in_headers, flow[\\\"id\\\"])\\n\\n    async with session_scope() as session:\\n        foreign_user = User(\\n            username=f\\\"foreign-provider-owner-{uuid4()}\\\",\\n            password=str(uuid4()),\\n            is_active=True,\\n        )\\n        session.add(foreign_user)\\n        await session.flush()\\n        foreign_provider = await _create_provider_account_row(session, user_id=foreign_user.id)\\n        foreign_provider_id = str(foreign_provider.id)\\n\\n    resp = await client.get(\\n        f\\\"api/v1/flows/{flow['id']}/versions/\\\",\\n        params={\\\"deployment_provider_id\\\": foreign_provider_id},\\n        headers=logged_in_headers,\\n    )\\n\\n    assert resp.status_code == status.HTTP_404_NOT_FOUND\\n    assert resp.json()[\\\"detail\\\"] == \\\"Deployment provider account not found.\\\"\\n\\n\\n# ---------------------------------------------------------------------------\\n# Sync-on-read: stale attachment pruning via provider verification\\n# ---------------------------------------------------------------------------\\n\\nSYNC_MODULE = \\\"langflow.api.v1.flow_version.sync_flow_version_attachments\\\"\\n\\n\\nasync def test_list_versions_sync_prunes_stale_attachment(client: AsyncClient, logged_in_headers, monkeypatch):\\n    \\\"\\\"\\\"When sync removes a stale attachment, is_deployed should flip to False.\\\"\\\"\\\"\\n    from unittest.mock import AsyncMock, patch\\n    from uuid import UUID\\n\\n    from langflow.services.deps import session_scope\\n\\n    _set_deployments_feature_flag(monkeypatch, enabled=True)\\n    flow = await _create_flow(client, logged_in_headers)\\n    snap = await _create_snapshot(client, logged_in_headers, flow[\\\"id\\\"])\\n\\n    # Set up a deployed version with a provider_snapshot_id.\\n    async with session_scope() as session:\\n        from langflow.services.database.models.flow.model import Flow\\n        from sqlmodel import select\\n\\n        flow_row = (await session.exec(select(Flow).where(Flow.id == UUID(flow[\\\"id\\\"])))).one()\\n        user_id = flow_row.user_id\\n        project_id = flow_row.folder_id\\n        provider_account = await _create_provider_account_row(session, user_id=user_id)\\n        provider_account_id = str(provider_account.id)\\n        deployment = await _create_deployment_row(\\n            session,\\n            user_id=user_id,\\n            project_id=project_id,\\n            provider_account_id=provider_account.id,\\n            name=\\\"sync-prune-test\\\",\\n            resource_key=\\\"rk-sync-prune\\\",\\n        )\\n        await _attach_version_to_deployment(\\n            session,\\n            user_id=user_id,\\n            flow_version_id=UUID(snap[\\\"id\\\"]),\\n            deployment_id=deployment.id,\\n            provider_snapshot_id=\\\"tool-abc-123\\\",\\n        )\\n        deployment_id = deployment.id\\n\\n    # Confirm is_deployed=True before sync prunes it.\\n    with patch(SYNC_MODULE, new_callable=AsyncMock):\\n        entries = await _list_versions(\\n            client,\\n            logged_in_headers,\\n            flow[\\\"id\\\"],\\n            params={\\\"deployment_provider_id\\\": provider_account_id},\\n        )\\n        assert entries[0][\\\"is_deployed\\\"] is True\\n\\n    async def _prune_sync(*_args, **_kwargs):\\n        from langflow.services.database.models.flow_version_deployment_attachment.crud import (\\n            delete_deployment_attachment,\\n        )\\n\\n        async with session_scope() as session:\\n            await delete_deployment_attachment(\\n                session,\\n                user_id=user_id,\\n                flow_version_id=UUID(snap[\\\"id\\\"]),\\n                deployment_id=deployment_id,\\n            )\\n\\n    with patch(SYNC_MODULE, new_callable=AsyncMock, side_effect=_prune_sync):\\n        entries = await _list_versions(\\n            client,\\n            logged_in_headers,\\n            flow[\\\"id\\\"],\\n            params={\\\"deployment_provider_id\\\": provider_account_id},\\n        )\\n        assert len(entries) == 1\\n        assert entries[0][\\\"is_deployed\\\"] is False\\n\\n\\nasync def test_list_versions_sync_failure_does_not_block_response(client: AsyncClient, logged_in_headers, monkeypatch):\\n    \\\"\\\"\\\"If sync raises, the list endpoint should still return results.\\\"\\\"\\\"\\n    from unittest.mock import AsyncMock, patch\\n    from uuid import UUID\\n\\n    from langflow.services.deps import session_scope\\n\\n    _set_deployments_feature_flag(monkeypatch, enabled=True)\\n    flow = await _create_flow(client, logged_in_headers)\\n    await _create_snapshot(client, logged_in_headers, flow[\\\"id\\\"])\\n    async with session_scope() as session:\\n        from langflow.services.database.models.flow.model import Flow\\n        from sqlmodel import select\\n\\n        flow_row = (await session.exec(select(Flow).where(Flow.id == UUID(flow[\\\"id\\\"])))).one()\\n        provider_account = await _create_provider_account_row(session, user_id=flow_row.user_id)\\n        provider_account_id = str(provider_account.id)\\n\\n    with patch(SYNC_MODULE, new_callable=AsyncMock, side_effect=RuntimeError(\\\"provider down\\\")):\\n        entries = await _list_versions(\\n            client,\\n            logged_in_headers,\\n            flow[\\\"id\\\"],\\n            params={\\\"deployment_provider_id\\\": provider_account_id},\\n        )\\n        assert len(entries) == 1\\n\\n\\nasync def test_get_single_version_reports_unknown_deployment_status_when_unattached(\\n    client: AsyncClient, logged_in_headers, monkeypatch\\n):\\n    \\\"\\\"\\\"Single-version reads return deployment status as unknown.\\\"\\\"\\\"\\n    _set_deployments_feature_flag(monkeypatch, enabled=True)\\n    flow = await _create_flow(client, logged_in_headers)\\n    snap = await _create_snapshot(client, logged_in_headers, flow[\\\"id\\\"])\\n\\n    resp = await client.get(f\\\"api/v1/flows/{flow['id']}/versions/{snap['id']}\\\", headers=logged_in_headers)\\n    assert resp.status_code == status.HTTP_200_OK\\n    assert resp.json()[\\\"is_deployed\\\"] is None\\n\\n\\nasync def test_get_single_version_reports_unknown_deployment_status_when_attached(\\n    client: AsyncClient, logged_in_headers, monkeypatch\\n):\\n    \\\"\\\"\\\"Single-version reads return unknown deployment status even when attached.\\\"\\\"\\\"\\n    from uuid import UUID\\n\\n    from langflow.services.deps import session_scope\\n\\n    _set_deployments_feature_flag(monkeypatch, enabled=True)\\n    flow = await _create_flow(client, logged_in_headers)\\n    snap = await _create_snapshot(client, logged_in_headers, flow[\\\"id\\\"])\\n\\n    async with session_scope() as session:\\n        from langflow.services.database.models.flow.model import Flow\\n        from sqlmodel import select\\n\\n        flow_row = (await session.exec(select(Flow).where(Flow.id == UUID(flow[\\\"id\\\"])))).one()\\n        provider_account = await _create_provider_account_row(session, user_id=flow_row.user_id)\\n        deployment = await _create_deployment_row(\\n            session,\\n            user_id=flow_row.user_id,\\n            project_id=flow_row.folder_id,\\n            provider_account_id=provider_account.id,\\n            name=\\\"single-get-attached\\\",\\n            resource_key=\\\"rk-single-get-attached\\\",\\n        )\\n        await _attach_version_to_deployment(\\n            session,\\n            user_id=flow_row.user_id,\\n            flow_version_id=UUID(snap[\\\"id\\\"]),\\n            deployment_id=deployment.id,\\n        )\\n\\n    resp = await client.get(f\\\"api/v1/flows/{flow['id']}/versions/{snap['id']}\\\", headers=logged_in_headers)\\n    assert resp.status_code == status.HTTP_200_OK\\n    assert resp.json()[\\\"is_deployed\\\"] is None\\n\\n\\nasync def test_get_single_version_reports_unknown_deployment_status_when_feature_disabled(\\n    client: AsyncClient, logged_in_headers, monkeypatch\\n):\\n    \\\"\\\"\\\"Feature-flag state does not change single-version deployment status behavior.\\\"\\\"\\\"\\n    from uuid import UUID\\n\\n    from langflow.services.deps import session_scope\\n\\n    _set_deployments_feature_flag(monkeypatch, enabled=False)\\n    flow = await _create_flow(client, logged_in_headers)\\n    snap = await _create_snapshot(client, logged_in_headers, flow[\\\"id\\\"])\\n\\n    async with session_scope() as session:\\n        from langflow.services.database.models.flow.model import Flow\\n        from sqlmodel import select\\n\\n        flow_row = (await session.exec(select(Flow).where(Flow.id == UUID(flow[\\\"id\\\"])))).one()\\n        provider_account = await _create_provider_account_row(session, user_id=flow_row.user_id)\\n        deployment = await _create_deployment_row(\\n            session,\\n            user_id=flow_row.user_id,\\n            project_id=flow_row.folder_id,\\n            provider_account_id=provider_account.id,\\n            name=\\\"single-get-disabled\\\",\\n            resource_key=\\\"rk-single-get-disabled\\\",\\n        )\\n        await _attach_version_to_deployment(\\n            session,\\n            user_id=flow_row.user_id,\\n            flow_version_id=UUID(snap[\\\"id\\\"]),\\n            deployment_id=deployment.id,\\n        )\\n\\n    resp = await client.get(f\\\"api/v1/flows/{flow['id']}/versions/{snap['id']}\\\", headers=logged_in_headers)\\n    assert resp.status_code == status.HTTP_200_OK\\n    assert resp.json()[\\\"is_deployed\\\"] is None\\n\\n\\nasync def test_get_single_version_sync_failure_does_not_block_response(\\n    client: AsyncClient, logged_in_headers, monkeypatch\\n):\\n    \\\"\\\"\\\"Single-version reads remain healthy if the list sync helper would fail.\\\"\\\"\\\"\\n    from unittest.mock import AsyncMock, patch\\n\\n    _set_deployments_feature_flag(monkeypatch, enabled=True)\\n    flow = await _create_flow(client, logged_in_headers)\\n    snap = await _create_snapshot(client, logged_in_headers, flow[\\\"id\\\"])\\n\\n    with patch(SYNC_MODULE, new_callable=AsyncMock, side_effect=RuntimeError(\\\"provider down\\\")) as mock_sync:\\n        resp = await client.get(f\\\"api/v1/flows/{flow['id']}/versions/{snap['id']}\\\", headers=logged_in_headers)\\n        assert resp.status_code == status.HTTP_200_OK\\n        assert resp.json()[\\\"id\\\"] == snap[\\\"id\\\"]\\n        assert resp.json()[\\\"is_deployed\\\"] is None\\n        mock_sync.assert_not_awaited()\\n\\n\\nasync def test_get_single_version_does_not_trigger_sync_prune(client: AsyncClient, logged_in_headers, monkeypatch):\\n    \\\"\\\"\\\"Single-version reads should not trigger sync/prune side effects.\\\"\\\"\\\"\\n    from unittest.mock import AsyncMock, patch\\n    from uuid import UUID\\n\\n    from langflow.services.deps import session_scope\\n\\n    _set_deployments_feature_flag(monkeypatch, enabled=True)\\n    flow = await _create_flow(client, logged_in_headers)\\n    snap = await _create_snapshot(client, logged_in_headers, flow[\\\"id\\\"])\\n\\n    async with session_scope() as session:\\n        from langflow.services.database.models.flow.model import Flow\\n        from langflow.services.database.models.flow_version_deployment_attachment.model import (\\n            FlowVersionDeploymentAttachment,\\n        )\\n        from sqlmodel import select\\n\\n        flow_row = (await session.exec(select(Flow).where(Flow.id == UUID(flow[\\\"id\\\"])))).one()\\n        user_id = flow_row.user_id\\n        provider_account = await _create_provider_account_row(session, user_id=user_id)\\n        deployment = await _create_deployment_row(\\n            session,\\n            user_id=user_id,\\n            project_id=flow_row.folder_id,\\n            provider_account_id=provider_account.id,\\n            name=\\\"single-get-no-sync\\\",\\n            resource_key=\\\"rk-single-get-no-sync\\\",\\n        )\\n        await _attach_version_to_deployment(\\n            session,\\n            user_id=user_id,\\n            flow_version_id=UUID(snap[\\\"id\\\"]),\\n            deployment_id=deployment.id,\\n            provider_snapshot_id=\\\"tool-xyz-789\\\",\\n        )\\n\\n    with patch(SYNC_MODULE, new_callable=AsyncMock) as mock_sync:\\n        resp = await client.get(f\\\"api/v1/flows/{flow['id']}/versions/{snap['id']}\\\", headers=logged_in_headers)\\n        assert resp.status_code == status.HTTP_200_OK\\n        assert resp.json()[\\\"is_deployed\\\"] is None\\n        mock_sync.assert_not_awaited()\\n\\n    async with session_scope() as session:\\n        from langflow.services.database.models.flow_version_deployment_attachment.model import (\\n            FlowVersionDeploymentAttachment,\\n        )\\n        from sqlmodel import select\\n\\n        attachment = (\\n            await session.exec(\\n                select(FlowVersionDeploymentAttachment).where(\\n                    FlowVersionDeploymentAttachment.flow_version_id == UUID(snap[\\\"id\\\"]),\\n                )\\n            )\\n        ).first()\\n        assert attachment is not None\\n\\n\\nasync def test_get_flow_version_entries_by_ids_rejects_oversized_batch():\\n    from unittest.mock import AsyncMock\\n    from uuid import uuid4\\n\\n    from langflow.services.database.models.flow_version.crud import get_flow_version_entries_by_ids\\n\\n    session = AsyncMock()\\n    version_ids = [uuid4() for _ in range(51)]\\n\\n    with pytest.raises(ValueError, match=\\\"version_ids supports at most 50 values\\\"):\\n        await get_flow_version_entries_by_ids(\\n            session=session,\\n            version_ids=version_ids,\\n            user_id=uuid4(),\\n        )\\n\\n    session.exec.assert_not_called()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/api/v1/test_flows.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"4617d61daf2dc027fae12f24cbd2df030b7b731613604b199028714e73f99a5b\",\"content\":\"import tempfile\\nimport uuid\\nfrom uuid import UUID\\n\\nfrom fastapi import status\\nfrom httpx import AsyncClient\\n\\n\\ndef _catalog_flow_data(component_key: str) -> dict:\\n    return {\\n        \\\"nodes\\\": [{\\\"id\\\": f\\\"{component_key}-node\\\", \\\"data\\\": {\\\"type\\\": component_key}}],\\n        \\\"edges\\\": [],\\n    }\\n\\n\\nasync def _attach_deployment_to_flow(*, user_id: UUID, flow_id: UUID, project_id: UUID) -> None:\\n    from langflow.services.database.models.deployment.model import Deployment\\n    from langflow.services.database.models.deployment_provider_account.model import (\\n        DeploymentProviderAccount,\\n        DeploymentProviderKey,\\n    )\\n    from langflow.services.database.models.flow_version.model import FlowVersion\\n    from langflow.services.database.models.flow_version_deployment_attachment.model import (\\n        FlowVersionDeploymentAttachment,\\n    )\\n    from langflow.services.deps import session_scope\\n    from lfx.services.adapters.deployment.schema import DeploymentType\\n\\n    async with session_scope() as session:\\n        provider = DeploymentProviderAccount(\\n            user_id=user_id,\\n            name=f\\\"provider-{flow_id.hex[:8]}\\\",\\n            provider_tenant_id=\\\"tenant-1\\\",\\n            provider_key=DeploymentProviderKey.WATSONX_ORCHESTRATE,\\n            provider_url=f\\\"https://provider-{flow_id.hex[:8]}.example.com\\\",\\n            api_key=\\\"encrypted-value\\\",  # pragma: allowlist secret\\n        )\\n        session.add(provider)\\n        await session.flush()\\n\\n        deployment = Deployment(\\n            user_id=user_id,\\n            project_id=project_id,\\n            deployment_provider_account_id=provider.id,\\n            resource_key=f\\\"rk-{flow_id.hex[:8]}\\\",\\n            display_name=f\\\"deployment-{flow_id.hex[:8]}\\\",\\n            deployment_type=DeploymentType.AGENT,\\n        )\\n        session.add(deployment)\\n        await session.flush()\\n\\n        flow_version = FlowVersion(\\n            flow_id=flow_id,\\n            user_id=user_id,\\n            version_number=1,\\n            data={\\\"nodes\\\": [], \\\"edges\\\": []},\\n        )\\n        session.add(flow_version)\\n        await session.flush()\\n\\n        attachment = FlowVersionDeploymentAttachment(\\n            user_id=user_id,\\n            flow_version_id=flow_version.id,\\n            deployment_id=deployment.id,\\n            provider_snapshot_id=f\\\"snapshot-{flow_id.hex[:8]}\\\",\\n        )\\n        session.add(attachment)\\n        await session.commit()\\n\\n\\nasync def test_create_flow(client: AsyncClient, logged_in_headers):\\n    # Use relative path - absolute paths outside allowed directory are rejected\\n    flow_filename = f\\\"{uuid.uuid4()}.json\\\"\\n    basic_case = {\\n        \\\"name\\\": \\\"string\\\",\\n        \\\"description\\\": \\\"string\\\",\\n        \\\"icon\\\": \\\"string\\\",\\n        \\\"icon_bg_color\\\": \\\"#ff00ff\\\",\\n        \\\"gradient\\\": \\\"string\\\",\\n        \\\"data\\\": {},\\n        \\\"is_component\\\": False,\\n        \\\"webhook\\\": False,\\n        \\\"endpoint_name\\\": \\\"string\\\",\\n        \\\"tags\\\": [\\\"string\\\"],\\n        \\\"folder_id\\\": \\\"3fa85f64-5717-4562-b3fc-2c963f66afa6\\\",\\n        \\\"fs_path\\\": flow_filename,\\n    }\\n    response = await client.post(\\\"api/v1/flows/\\\", json=basic_case, headers=logged_in_headers)\\n    result = response.json()\\n\\n    assert response.status_code == status.HTTP_201_CREATED\\n    assert isinstance(result, dict), \\\"The result must be a dictionary\\\"\\n    assert \\\"data\\\" in result, \\\"The result must have a 'data' key\\\"\\n    assert \\\"description\\\" in result, \\\"The result must have a 'description' key\\\"\\n    assert \\\"endpoint_name\\\" in result, \\\"The result must have a 'endpoint_name' key\\\"\\n    assert \\\"folder_id\\\" in result, \\\"The result must have a 'folder_id' key\\\"\\n    assert \\\"gradient\\\" in result, \\\"The result must have a 'gradient' key\\\"\\n    assert \\\"icon\\\" in result, \\\"The result must have a 'icon' key\\\"\\n    assert \\\"icon_bg_color\\\" in result, \\\"The result must have a 'icon_bg_color' key\\\"\\n    assert \\\"id\\\" in result, \\\"The result must have a 'id' key\\\"\\n    assert \\\"is_component\\\" in result, \\\"The result must have a 'is_component' key\\\"\\n    assert \\\"name\\\" in result, \\\"The result must have a 'name' key\\\"\\n    assert \\\"tags\\\" in result, \\\"The result must have a 'tags' key\\\"\\n    assert \\\"updated_at\\\" in result, \\\"The result must have a 'updated_at' key\\\"\\n    assert \\\"user_id\\\" in result, \\\"The result must have a 'user_id' key\\\"\\n    assert \\\"webhook\\\" in result, \\\"The result must have a 'webhook' key\\\"\\n\\n\\nasync def test_create_flow_retries_transient_sqlite_lock_with_fresh_payload(\\n    client: AsyncClient, logged_in_headers, monkeypatch\\n):\\n    \\\"\\\"\\\"A transient SQLite writer lock retries from a deeply copied FlowCreate snapshot.\\\"\\\"\\\"\\n    import sqlite3\\n\\n    from langflow.api.v1 import flows as flows_module\\n    from sqlalchemy.exc import OperationalError\\n\\n    original_new_flow = flows_module._new_flow\\n    attempts: list[object] = []\\n    expected_name = f\\\"create-lock-retry-{uuid.uuid4()}\\\"\\n    expected_data = {\\n        \\\"nodes\\\": [{\\\"id\\\": \\\"original-node\\\", \\\"data\\\": {\\\"settings\\\": {\\\"values\\\": [\\\"original\\\"]}}}],\\n        \\\"edges\\\": [],\\n    }\\n    insert_statement = \\\"INSERT INTO flow (id, name) VALUES (?, ?)\\\"\\n\\n    async def create_after_one_lock(**kwargs):\\n        attempts.append(kwargs[\\\"flow\\\"])\\n        if len(attempts) == 1:\\n            kwargs[\\\"flow\\\"].name = \\\"mutated-during-failed-attempt\\\"\\n            kwargs[\\\"flow\\\"].data[\\\"nodes\\\"][0][\\\"data\\\"][\\\"settings\\\"][\\\"values\\\"].append(\\\"mutated\\\")\\n            raise OperationalError(\\n                insert_statement,\\n                {\\\"name\\\": expected_name},\\n                sqlite3.OperationalError(\\\"database is locked\\\"),\\n            )\\n        return await original_new_flow(**kwargs)\\n\\n    monkeypatch.setattr(flows_module, \\\"_new_flow\\\", create_after_one_lock)\\n\\n    response = await client.post(\\n        \\\"api/v1/flows/\\\",\\n        json={\\\"name\\\": expected_name, \\\"data\\\": expected_data},\\n        headers=logged_in_headers,\\n    )\\n\\n    assert response.status_code == status.HTTP_201_CREATED, response.text\\n    assert response.json()[\\\"name\\\"] == expected_name\\n    assert response.json()[\\\"data\\\"] == expected_data\\n    assert len(attempts) == 2\\n    assert attempts[0] is not attempts[1]\\n    assert attempts[0].data is not attempts[1].data\\n    assert attempts[0].data[\\\"nodes\\\"][0] is not attempts[1].data[\\\"nodes\\\"][0]\\n\\n\\nasync def test_create_flow_duplicate_explicit_id_returns_sanitized_unique_error(client: AsyncClient, logged_in_headers):\\n    \\\"\\\"\\\"A real duplicate primary-key failure reaches the route's uniqueness mapping.\\\"\\\"\\\"\\n    explicit_id = str(uuid.uuid4())\\n    first_response = await client.post(\\n        \\\"api/v1/flows/\\\",\\n        json={\\\"id\\\": explicit_id, \\\"name\\\": f\\\"explicit-id-first-{uuid.uuid4()}\\\", \\\"data\\\": {}},\\n        headers=logged_in_headers,\\n    )\\n    assert first_response.status_code == status.HTTP_201_CREATED, first_response.text\\n\\n    duplicate_response = await client.post(\\n        \\\"api/v1/flows/\\\",\\n        json={\\\"id\\\": explicit_id, \\\"name\\\": f\\\"explicit-id-second-{uuid.uuid4()}\\\", \\\"data\\\": {}},\\n        headers=logged_in_headers,\\n    )\\n\\n    assert duplicate_response.status_code == status.HTTP_400_BAD_REQUEST, duplicate_response.text\\n    assert duplicate_response.json()[\\\"detail\\\"] == \\\"Id must be unique\\\"\\n    assert explicit_id not in duplicate_response.text\\n    assert \\\"INSERT INTO\\\" not in duplicate_response.text\\n    assert \\\"sqlalche.me\\\" not in duplicate_response.text\\n\\n\\ndef test_flow_unique_constraint_error_maps_postgres_sqlstate_without_leaking_values():\\n    \\\"\\\"\\\"PostgreSQL 23505 diagnostics map only known flow constraints to safe field names.\\\"\\\"\\\"\\n    from types import SimpleNamespace\\n\\n    from langflow.api.v1 import flows as flows_module\\n    from sqlalchemy.exc import IntegrityError\\n\\n    leaked_id = str(uuid.uuid4())\\n    expected_details = {\\n        \\\"flow_pkey\\\": \\\"Id must be unique\\\",\\n        \\\"pk_flow\\\": \\\"Id must be unique\\\",\\n        \\\"uq_flow_id\\\": \\\"Id must be unique\\\",\\n        \\\"unique_flow_name\\\": \\\"Name must be unique\\\",\\n        \\\"unique_flow_endpoint_name\\\": \\\"Endpoint name must be unique\\\",\\n    }\\n\\n    for constraint_name, expected_detail in expected_details.items():\\n        driver_error = RuntimeError(f\\\"duplicate key value {leaked_id}\\\")\\n        driver_error.sqlstate = \\\"23505\\\"\\n        driver_error.diag = SimpleNamespace(constraint_name=constraint_name)\\n        integrity_error = IntegrityError(\\\"INSERT INTO flow ...\\\", {\\\"id\\\": leaked_id}, driver_error)\\n\\n        response_error = flows_module._handle_unique_constraint_error(integrity_error)\\n\\n        assert response_error.status_code == status.HTTP_400_BAD_REQUEST\\n        assert response_error.detail == expected_detail\\n        assert leaked_id not in str(response_error.detail)\\n\\n    marker_driver_error = RuntimeError(f\\\"duplicate key value UNIQUE constraint failed: flow.id {leaked_id}\\\")\\n    marker_driver_error.sqlstate = \\\"23505\\\"\\n    marker_driver_error.diag = SimpleNamespace(constraint_name=\\\"unique_flow_name\\\")\\n    marker_integrity_error = IntegrityError(\\\"INSERT INTO flow ...\\\", {\\\"name\\\": leaked_id}, marker_driver_error)\\n\\n    marker_response_error = flows_module._handle_unique_constraint_error(marker_integrity_error)\\n\\n    assert marker_response_error.status_code == status.HTTP_400_BAD_REQUEST\\n    assert marker_response_error.detail == \\\"Name must be unique\\\"\\n    assert leaked_id not in str(marker_response_error.detail)\\n\\n    unknown_driver_error = RuntimeError(f\\\"duplicate key value {leaked_id}\\\")\\n    unknown_driver_error.sqlstate = \\\"23505\\\"\\n    unknown_driver_error.diag = SimpleNamespace(constraint_name=\\\"unrelated_unique_constraint\\\")\\n    unknown_integrity_error = IntegrityError(\\\"INSERT INTO other ...\\\", {\\\"id\\\": leaked_id}, unknown_driver_error)\\n\\n    unknown_response_error = flows_module._handle_unique_constraint_error(unknown_integrity_error)\\n\\n    assert unknown_response_error.status_code == status.HTTP_500_INTERNAL_SERVER_ERROR\\n    assert unknown_response_error.detail == \\\"Could not persist the flow.\\\"\\n    assert leaked_id not in str(unknown_response_error.detail)\\n\\n\\ndef test_flow_unique_constraint_error_rejects_unknown_sqlite_table():\\n    \\\"\\\"\\\"SQLite messages for other tables or unknown flow constraint shapes stay generic.\\\"\\\"\\\"\\n    import sqlite3\\n\\n    from langflow.api.v1 import flows as flows_module\\n    from sqlalchemy.exc import IntegrityError\\n\\n    leaked_id = str(uuid.uuid4())\\n    unknown_constraints = (\\n        \\\"unrelated.id\\\",\\n        \\\"other.name\\\",\\n   ";
